def app_now():
    # Render suele ejecutar en UTC; para registro horario necesitamos hora local (España por defecto).
    if ZoneInfo:
        try:
            return datetime.now(ZoneInfo(APP_TIMEZONE))
        except Exception:
            pass
    return datetime.now()

