def derive_hipoteca_inmobiliaria_cost(row):
    total = parse_money_value((row.get("comision") if isinstance(row, dict) else row["comision"]) or 0)
    juan = parse_money_value((row.get("comision_juan") if isinstance(row, dict) else row["comision_juan"]) or 0)
    modernia = parse_money_value((row.get("comision_modernia") if isinstance(row, dict) else row["comision_modernia"]) or 0)
    explicit = parse_money_value((row.get("cesion") if isinstance(row, dict) else row["cesion"]) or 0)
    if explicit > 0.005:
        return round(explicit, 2)
    derived = round(total - juan - modernia, 2)
    if derived > 0.005:
        return derived
    return 0.0


def hipoteca_office_has_no_cesion_costs(value):
    key = normalize_lookup_text(value)
    return key in {"PARTICULAR", "PARTICULARES"}


def build_hipoteca_accounting_entries(row):
    estado = (row.get("estado") if isinstance(row, dict) else row["estado"]) or ""
    fecha = resolve_hipoteca_accounting_date(row)
    if not fecha or not hipoteca_estado_is_closed(estado):
        return []
    cliente = str((row.get("cliente") if isinstance(row, dict) else row["cliente"]) or "").strip() or "Hipoteca"
    banco = str((row.get("banco") if isinstance(row, dict) else row["banco"]) or "").strip()
    suffix = f"{cliente}"
    if banco:
        suffix = f"{cliente} · {banco}"
    entries = []

    def add_entry(gestion, tipo, importe, concepto):
        amount = round(parse_money_value(importe), 2)
        if abs(amount) < 0.005:
            return
        entries.append(
            {
                "gestion": gestion,
                "tipo": tipo,
                "importe": amount,
                "concepto": f"{concepto} · {suffix}",
                "fecha": fecha.isoformat(),
            }
        )

    total_comision = (row.get("comision") if isinstance(row, dict) else row["comision"]) or 0
    oficina = (row.get("oficina") if isinstance(row, dict) else row["oficina"]) or ""
    split = derive_hipoteca_commissions(total_comision, oficina)
    raw_gasto_juan = (row.get("comision_juan") if isinstance(row, dict) else row["comision_juan"])
    raw_gasto_inmobiliaria = (row.get("cesion") if isinstance(row, dict) else row["cesion"])
    if raw_gasto_juan in (None, ""):
        gasto_juan = split["comision_juan"]
    else:
        gasto_juan = raw_gasto_juan
    if raw_gasto_inmobiliaria in (None, ""):
        gasto_inmobiliaria = split["cesion"]
    else:
        gasto_inmobiliaria = raw_gasto_inmobiliaria
    if hipoteca_office_has_no_cesion_costs(oficina):
        gasto_juan = 0
        gasto_inmobiliaria = 0

    add_entry("Comisión cliente", "Ingreso", total_comision, "Comisión cliente")
    add_entry("Cesión Juan", "Gasto", gasto_juan, "Cesión Juan")
    add_entry("Cesión a inmobiliarias", "Gasto", gasto_inmobiliaria, "Cesión a inmobiliarias")
    return entries


def hipoteca_accounting_exclusion_key(hipoteca_id, fecha, gestion):
    return (
        str(hipoteca_id or "").strip(),
        str(fecha or "").strip(),
        normalize_lookup_text(gestion),
    )


def load_hipoteca_accounting_exclusions(conn, empresa_id):
    try:
        rows = conn.execute(
            """
            SELECT hipoteca_id, fecha, gestion
            FROM hipotecas_contabilidad_excluidas
            WHERE empresa_id = ?
            """,
            (empresa_id,),
        ).fetchall()
    except Exception:
        return set()
    return {
        hipoteca_accounting_exclusion_key(row["hipoteca_id"], row["fecha"], row["gestion"])
        for row in rows
        if str(row["hipoteca_id"] or "").strip()
    }


def maybe_promote_study_hipoteca_accounting(conn, empresa_id, hipoteca_id, payload, now=None):
    hipoteca_id = str(hipoteca_id or "").strip()
    if not hipoteca_id:
        return False
    tipo = normalize_lookup_text(payload.get("tipo"))
    if tipo == "GASTO":
        return False
    row = conn.execute(
        """
        SELECT id, estado, fecha_firma, anio
        FROM hipotecas
        WHERE id = ?
        LIMIT 1
        """,
        (hipoteca_id,),
    ).fetchone()
    if not row or not hipoteca_estado_is_study(row["estado"]):
        return False
    fecha = parse_iso_date(payload.get("fecha")) or datetime.now(timezone.utc).date()
    stamp = now or datetime.now(timezone.utc).isoformat()
    conn.execute(
        """
        UPDATE hipotecas
        SET estado = ?, fecha_firma = COALESCE(NULLIF(TRIM(fecha_firma), ''), ?), anio = ?, updated_at = datetime(?)
        WHERE id = ?
        """,
        ("INDEMNIZACIÓN", fecha.isoformat(), int(fecha.year), stamp, hipoteca_id),
    )
    sync_hipotecas_contabilidad_entries(conn, empresa_id, now=stamp)
    return True


def sync_hipotecas_contabilidad_entries(conn, empresa_id, now=None):
    now = now or datetime.now(timezone.utc).isoformat()
    excluded_keys = load_hipoteca_accounting_exclusions(conn, empresa_id)
    rows = conn.execute(
        """
        SELECT *
        FROM hipotecas
        WHERE empresa_id = ?
        """,
        (empresa_id,),
    ).fetchall()
    expected_keys = set()
    for raw in rows:
        row = dict(raw)
        hipoteca_id = str(row.get("id") or "").strip()
        if not hipoteca_id:
            continue
        entries = build_hipoteca_accounting_entries(row)
        link = resolve_hipoteca_contabilidad_link(conn, hipoteca_id)
        cliente_id = link.get("cliente_id")
        cliente_ids_json = json.dumps([cliente_id], ensure_ascii=False) if cliente_id else None
        for item in entries:
            key = hipoteca_accounting_exclusion_key(hipoteca_id, item["fecha"], item["gestion"])
            if key in excluded_keys:
                continue
            expected_keys.add(key)
            existing = conn.execute(
                """
                SELECT id
                FROM gestoria_contabilidad
                WHERE hipoteca_id = ?
                  AND fecha = ?
                  AND LOWER(COALESCE(gestion, '')) = LOWER(?)
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (hipoteca_id, item["fecha"], item["gestion"]),
            ).fetchone()
            notes = f"{HIPOTECA_ACCOUNTING_AUTO_NOTES_PREFIX} · {item['gestion'].lower()}."
            if existing:
                conn.execute(
                    """
                    UPDATE gestoria_contabilidad
                    SET empresa_id = ?, cliente_id = ?, cliente_ids_json = ?, hipoteca_id = ?, concepto = ?, gestion = ?, tipo = ?,
                        importe = ?, notas = ?, updated_at = datetime(?)
                    WHERE id = ?
                    """,
                    (
                        empresa_id,
                        cliente_id,
                        cliente_ids_json,
                        hipoteca_id,
                        item["concepto"],
                        item["gestion"],
                        item["tipo"],
                        item["importe"],
                        notes,
                        now,
                        existing["id"],
                    ),
                )
            else:
                conn.execute(
                    """
                    INSERT INTO gestoria_contabilidad (
                      id, empresa_id, cliente_id, cliente_ids_json, hipoteca_id, fecha, concepto, gestion, tipo, importe, notas,
                      created_at, updated_at
                    ) VALUES (
                      ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                    )
                    """,
                    (
                        os.urandom(16).hex(),
                        empresa_id,
                        cliente_id,
                        cliente_ids_json,
                        hipoteca_id,
                        item["fecha"],
                        item["concepto"],
                        item["gestion"],
                        item["tipo"],
                        item["importe"],
                        notes,
                        now,
                        now,
                    ),
                )
    fixed_expected_keys = set()
    for item in build_hipoteca_fixed_cost_entries(now):
        key = (
            str(item["fecha"]).strip(),
            normalize_lookup_text(item["gestion"]),
            normalize_lookup_text(item["concepto"]),
        )
        fixed_expected_keys.add(key)
        existing = conn.execute(
            """
            SELECT id
            FROM gestoria_contabilidad
            WHERE empresa_id = ?
              AND (hipoteca_id IS NULL OR TRIM(hipoteca_id) = '')
              AND fecha = ?
              AND LOWER(COALESCE(gestion, '')) = LOWER(?)
              AND LOWER(COALESCE(concepto, '')) = LOWER(?)
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (empresa_id, item["fecha"], item["gestion"], item["concepto"]),
        ).fetchone()
        if existing:
            conn.execute(
                """
                UPDATE gestoria_contabilidad
                SET empresa_id = ?, cliente_id = NULL, cliente_ids_json = NULL, hipoteca_id = NULL, concepto = ?, gestion = ?, tipo = ?,
                    importe = ?, notas = ?, updated_at = datetime(?)
                WHERE id = ?
                """,
                (
                    empresa_id,
                    item["concepto"],
                    item["gestion"],
                    item["tipo"],
                    item["importe"],
                    item["notas"],
                    now,
                    existing["id"],
                ),
            )
        else:
            conn.execute(
                """
                INSERT INTO gestoria_contabilidad (
                  id, empresa_id, cliente_id, cliente_ids_json, hipoteca_id, fecha, concepto, gestion, tipo, importe, notas,
                  created_at, updated_at
                ) VALUES (
                  ?, ?, NULL, NULL, NULL, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                )
                """,
                (
                    os.urandom(16).hex(),
                    empresa_id,
                    item["fecha"],
                    item["concepto"],
                    item["gestion"],
                    item["tipo"],
                    item["importe"],
                    item["notas"],
                    now,
                    now,
                ),
            )
    existing_rows = conn.execute(
        """
        SELECT id, hipoteca_id, fecha, gestion
        FROM gestoria_contabilidad
        WHERE empresa_id = ?
          AND hipoteca_id IS NOT NULL
          AND TRIM(hipoteca_id) <> ''
          AND UPPER(COALESCE(notas, '')) LIKE 'AUTO CRM HIPOTECAS%'
        """,
        (empresa_id,),
    ).fetchall()
    for row in existing_rows:
        key = hipoteca_accounting_exclusion_key(row["hipoteca_id"], row["fecha"], row["gestion"])
        if key not in expected_keys:
            conn.execute("DELETE FROM gestoria_contabilidad WHERE id = ?", (row["id"],))
    fixed_rows = conn.execute(
        """
        SELECT id, fecha, gestion, concepto
        FROM gestoria_contabilidad
        WHERE empresa_id = ?
          AND (hipoteca_id IS NULL OR TRIM(hipoteca_id) = '')
          AND UPPER(COALESCE(notas, '')) LIKE UPPER(?)
        """,
        (empresa_id, f"{HIPOTECA_ACCOUNTING_FIXED_COSTS_PREFIX}%"),
    ).fetchall()
    for row in fixed_rows:
        key = (
            str(row["fecha"] or "").strip(),
            normalize_lookup_text(row["gestion"]),
            normalize_lookup_text(row["concepto"]),
        )
        if key not in fixed_expected_keys:
            conn.execute("DELETE FROM gestoria_contabilidad WHERE id = ?", (row["id"],))


def delete_hipoteca_record(conn, record_id):
    if not record_id:
        return False
    row = conn.execute("SELECT id FROM hipotecas WHERE id = ?", (record_id,)).fetchone()
    if not row:
        return False
    conn.execute("DELETE FROM hipotecas WHERE id = ?", (record_id,))
    return True


def delete_gestoria_contabilidad_record(conn, record_id, now=None):
    if not record_id:
        return False
    now = now or datetime.now(timezone.utc).isoformat()
    row = conn.execute(
        """
        SELECT id, empresa_id, hipoteca_id, fecha, gestion, notas
        FROM gestoria_contabilidad
        WHERE id = ?
        LIMIT 1
        """,
        (record_id,),
    ).fetchone()
    if not row:
        return False
    hipoteca_id = str(row["hipoteca_id"] or "").strip()
    notes = str(row["notas"] or "").strip().upper()
    if hipoteca_id and notes.startswith("AUTO CRM HIPOTECAS"):
        conn.execute(
            """
            INSERT INTO hipotecas_contabilidad_excluidas (
              id, empresa_id, hipoteca_id, fecha, gestion, created_at
            ) VALUES (?, ?, ?, ?, ?, datetime(?))
            ON CONFLICT(empresa_id, hipoteca_id, fecha, gestion) DO NOTHING
            """,
            (
                os.urandom(16).hex(),
                row["empresa_id"],
                hipoteca_id,
                row["fecha"],
                row["gestion"],
                now,
            ),
        )
    conn.execute("DELETE FROM gestoria_contabilidad WHERE id = ?", (record_id,))
    return True


def has_explicit_renewal_action(seguro_row):
    estado = normalize_lookup_text(seguro_row.get("estado"))
    estado_ren = normalize_lookup_text(seguro_row.get("estado_renovacion"))
    if seguro_row.get("renovacion_fecha") or seguro_row.get("nueva_poliza_ref"):
        return True
    if any(token in estado for token in ("BAJA", "CANCEL", "ANULAD")):
        return True
    if not estado_ren:
        return False
    return "AUTOM" not in estado_ren


def compute_seguro_display(seguro_row):
    fecha_efecto = seguro_row.get("fecha_efecto")
    venc = parse_iso_date(seguro_row.get("fecha_vencimiento")) or parse_iso_date(add_year_to_date(fecha_efecto))
    base_estado = seguro_row.get("estado") or "-"
    if not venc:
        return {"vencimiento_display": "", "estado_display": base_estado}
    today = datetime.now(timezone.utc).date()
    has_action = has_explicit_renewal_action(seguro_row)
    while venc < today and not has_action:
        try:
            venc = venc.replace(year=venc.year + 1)
        except ValueError:
            venc = venc.replace(month=2, day=28, year=venc.year + 1)
    estado = base_estado
    if parse_iso_date(seguro_row.get("fecha_vencimiento")) and parse_iso_date(seguro_row.get("fecha_vencimiento")) < today and not has_action:
        estado = "Renovada automática"
    return {"vencimiento_display": venc.isoformat(), "estado_display": estado}


def load_seguros_company_hints(path=SEGUROS_COMPANY_HINTS_PATH):
    hints = {}
    if not path.exists():
        return hints
    try:
        with path.open("r", encoding="utf-8") as handle:
            payload = json.load(handle) or {}
    except Exception:
        return hints
    raw_hints = payload.get("hints") if isinstance(payload, dict) else {}
    if not isinstance(raw_hints, dict):
        return hints
    for token, company in raw_hints.items():
        norm_token = normalize_lookup_text(token)
        if norm_token and company:
            hints[norm_token] = normalize_company_name(company)
    return hints


LEARNED_COMPANY_HINTS = load_seguros_company_hints()


def detect_company_from_text(text):
    cleaned = normalize_lookup_text(text)
    if not cleaned:
        return ""
    for pattern, name in COMPANY_ALIAS_PATTERNS:
        if re.search(pattern, cleaned, re.IGNORECASE):
            return name
    return ""


def detect_company_from_metadata(*values):
    joined = " ".join(str(v or "") for v in values).strip()
    if not joined:
        return ""
    cleaned = normalize_lookup_text(joined)
    if not cleaned:
        return ""
    if LEARNED_COMPANY_HINTS:
        for token, company in sorted(LEARNED_COMPANY_HINTS.items(), key=lambda it: len(it[0]), reverse=True):
            if token and token in cleaned:
                return company
    return detect_company_from_text(cleaned)

def normalize_fin_nif(value):
    if not value:
        return ""
    raw = str(value).strip().upper()
    if not raw:
        return ""
    raw = raw.replace(" ", "").replace("-", "").replace(".", "")
    raw = raw.replace("O", "0").replace("I", "1").replace("L", "1").replace("S", "5")
    raw = re.sub(r"[^A-Z0-9]", "", raw)
    if len(raw) > 9:
        raw = raw[:9]
    return raw

def normalize_nif(value):
    if not value:
        return ""
    raw = str(value).strip().upper()
    if not raw:
        return ""
    raw = raw.replace(" ", "").replace("-", "").replace(".", "")
    raw = raw.replace("O", "0").replace("I", "1").replace("L", "1").replace("S", "5")
    raw = re.sub(r"[^A-Z0-9]", "", raw)
    if len(raw) > 12:
        raw = raw[:12]
    return raw

FIN_REQUIRED_FIELDS = [
    ("cliente1_nombre", "Nombre cliente 1"),
    ("cliente1_dni", "DNI cliente 1"),
    ("cliente1_telefono", "Teléfono cliente 1"),
    ("fecha", "Fecha"),
    ("ingresos_conjuntos", "Ingresos conjuntos"),
]

def fin_missing_fields(row):
    missing = []
    if not row:
        return missing
    for key, label in FIN_REQUIRED_FIELDS:
        value = row.get(key) if isinstance(row, dict) else row[key]
        if value is None or str(value).strip() == "":
            missing.append(label)
    return missing

def fin_sync_missing_action(conn, empresa_id, asesoramiento_id, cliente_id, cliente_nombre, missing, now):
    if missing:
        notas = f"Completar datos asesoramiento ({', '.join(missing)}). Asesoramiento ID: {asesoramiento_id}"
        exists = conn.execute(
            """
            SELECT id, estado FROM acciones
            WHERE LOWER(servicio) = 'financiaciones'
              AND asesoramiento_id = ?
              AND tipo = 'Completar datos asesoramiento'
            LIMIT 1
            """,
            (asesoramiento_id,),
        ).fetchone()
        if exists:
            if (exists["estado"] or "").lower() != "pendiente":
                conn.execute(
                    "UPDATE acciones SET estado = 'Pendiente', updated_at = datetime(?) WHERE id = ?",
                    (now, exists["id"]),
                )
            return
        today = datetime.now().strftime("%Y-%m-%d")
        conn.execute(
            """
            INSERT INTO acciones (
              id, empresa_id, servicio, cliente_id, inmueble_id, asesoramiento_id, cliente_nombre,
              fecha, hora, tipo, responsable, estado, notas, recordatorio_min, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                empresa_id,
                "financiaciones",
                cliente_id,
                None,
                asesoramiento_id,
                cliente_nombre or "",
                today,
                None,
                "Completar datos asesoramiento",
                None,
                "Pendiente",
                notas,
                None,
                now,
                now,
            ),
        )
    else:
        conn.execute(
            """
            UPDATE acciones
            SET estado = 'Hecho', updated_at = datetime(?)
            WHERE LOWER(servicio) = 'financiaciones'
              AND asesoramiento_id = ?
              AND tipo = 'Completar datos asesoramiento'
            """,
            (now, asesoramiento_id),
        )


def seguros_sync_activation_action(conn, seguro_row, now):
    if not seguro_row:
        return
    seguro_id = str(seguro_row["id"] or "").strip()
    if not seguro_id:
        return
    empresa_id = str(seguro_row["empresa_id"] or "").strip()
    cliente_id = str(seguro_row["cliente_id"] or "").strip() or None
    fecha_efecto = str(seguro_row["fecha_efecto"] or "").strip()
    efecto_dt = parse_iso_date(fecha_efecto)
    estado_key = normalize_lookup_text(seguro_row["estado"] or "")
    in_vigor = any(token in estado_key for token in ("EN VIGOR", "VIGENTE", "ACTIVA", "ACTIVO"))
    existing = conn.execute(
        """
        SELECT id, estado
        FROM acciones
        WHERE servicio = 'Seguros'
          AND tipo = 'Activar póliza'
          AND notas LIKE ?
        LIMIT 1
        """,
        (f"%{seguro_id}%",),
    ).fetchone()
    today = datetime.now(timezone.utc).date()
    should_be_pending = (
        bool(efecto_dt)
        and efecto_dt > today
        and not in_vigor
    )
    if should_be_pending:
        notas = f"Activar póliza por entrada en vigor ({seguro_row['poliza_numero'] or 'sin número'}). Poliza ID: {seguro_id}"
        if existing:
            conn.execute(
                """
                UPDATE acciones
                SET empresa_id = ?, cliente_id = ?, cliente_nombre = ?, fecha = ?, tipo = 'Activar póliza',
                    estado = 'Pendiente', notas = ?, updated_at = datetime(?)
                WHERE id = ?
                """,
                (
                    empresa_id,
                    cliente_id,
                    seguro_row["tomador"] or "",
                    fecha_efecto,
                    notas,
                    now,
                    existing["id"],
                ),
            )
            return
        conn.execute(
            """
            INSERT INTO acciones (
              id, empresa_id, servicio, cliente_id, inmueble_id, cliente_nombre,
              fecha, hora, tipo, responsable, estado, notas, recordatorio_min, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                empresa_id,
                "Seguros",
                cliente_id,
                None,
                seguro_row["tomador"] or "",
                fecha_efecto,
                None,
                "Activar póliza",
                None,
                "Pendiente",
                notas,
                None,
                now,
                now,
            ),
        )
        return
    if existing:
        conn.execute(
            "UPDATE acciones SET estado = 'Hecho', updated_at = datetime(?) WHERE id = ?",
            (now, existing["id"]),
        )

def normalize_header(value):
    return re.sub(r"[^a-z0-9]", "", str(value or "").lower())

def load_postal_catalog(conn):
    if not POSTAL_CATALOG_PATH.exists():
        return
    count_row = conn.execute("SELECT COUNT(*) AS total FROM postal_catalogo").fetchone()
    total = 0
    if count_row:
        try:
            total = count_row["total"]
        except (TypeError, KeyError, IndexError):
            total = count_row[0]
    if total:
        return
    encodings = ("utf-8-sig", "latin-1")
    for encoding in encodings:
        try:
            with POSTAL_CATALOG_PATH.open("r", encoding=encoding, newline="") as handle:
                reader = csv.DictReader(handle)
                if not reader.fieldnames:
                    return
                headers = {normalize_header(name): name for name in reader.fieldnames}
                cp_key = next(
                    (headers[k] for k in headers if k in ("codigopostal", "codigo_postal", "postalcode", "cp", "codigo")),
                    None,
                )
                pob_key = next(
                    (headers[k] for k in headers if k in ("poblacion", "municipio", "municipionombre", "localidad", "ciudad", "nombre")),
                    None,
                )
                prov_key = next(
                    (headers[k] for k in headers if k in ("provincia", "provincianombre", "province")),
                    None,
                )
                if not cp_key:
                    return
                batch = []
                seen = set()
                for row in reader:
                    cp_raw = row.get(cp_key, "")
                    cp = normalize_postal_code(cp_raw)
                    if not cp:
                        continue
                    poblacion = (row.get(pob_key, "") if pob_key else "") or ""
                    poblacion = str(poblacion).strip()
                    provincia = (row.get(prov_key, "") if prov_key else "") or ""
                    provincia = str(provincia).strip()
                    if not provincia:
                        provincia = POSTAL_PROVINCES.get(cp[:2], "")
                    key = (cp, poblacion, provincia)
                    if key in seen:
                        continue
                    seen.add(key)
                    batch.append(key)
                    if len(batch) >= 5000:
                        conn.executemany(
                            "INSERT INTO postal_catalogo (codigo_postal, poblacion, provincia) VALUES (?, ?, ?)",
                            batch,
                        )
                        batch = []
                if batch:
                    conn.executemany(
                        "INSERT INTO postal_catalogo (codigo_postal, poblacion, provincia) VALUES (?, ?, ?)",
                        batch,
                    )
            return
        except UnicodeDecodeError:
            continue

def hash_password(password):
    return runtime_hash_password(password)


def verify_password(password, password_hash):
    return runtime_verify_password(password, password_hash)


def _cleanup_expired_sessions():
    now = time.time()
    expired = []
    for token, session in AUTH_SESSIONS.items():
        if float(session.get("expires_at") or 0) <= now:
            expired.append(token)
    for token in expired:
        AUTH_SESSIONS.pop(token, None)


def create_auth_session(user_row):
    now = time.time()
    session = {
        "token": secrets.token_urlsafe(32),
        "user_id": str(user_row["id"]),
        "usuario": str(user_row["usuario"] or ""),
        "nombre": str(user_row["nombre"] or ""),
        "apellido": str(user_row["apellido"] or ""),
        "rol": str(user_row["rol"] or ""),
        "email": str(user_row["email"] or ""),
        "servicio": str(user_row["servicio"] or ""),
        "expires_at": now + APP_SESSION_TTL_SECONDS,
        "created_at": now,
    }
    with AUTH_SESSIONS_LOCK:
        _cleanup_expired_sessions()
        AUTH_SESSIONS[session["token"]] = session
    return session


def get_auth_session(token):
    if not token:
        return None
    with AUTH_SESSIONS_LOCK:
        session = AUTH_SESSIONS.get(token)
        if not session:
            return None
        if float(session.get("expires_at") or 0) <= time.time():
            AUTH_SESSIONS.pop(token, None)
            return None
        session["expires_at"] = time.time() + APP_SESSION_TTL_SECONDS
        return dict(session)


def delete_auth_session(token):
    if not token:
        return
    with AUTH_SESSIONS_LOCK:
        AUTH_SESSIONS.pop(token, None)

def _get_client_ip(handler):
    xff = (handler.headers.get("X-Forwarded-For") or "").strip()
    if xff:
        # Formato: "client, proxy1, proxy2"
        return xff.split(",")[0].strip()
    xri = (handler.headers.get("X-Real-IP") or "").strip()
    if xri:
        return xri
    try:
        return handler.client_address[0] if handler.client_address else ""
    except Exception:
        return ""


def _login_rate_key(ip, username):
    ip = str(ip or "").strip()
    user = normalize_lookup_text(username or "")
    if ip and user:
        return f"{ip}|{user}"
    if ip:
        return f"{ip}|"
    if user:
        return f"|{user}"
    return ""


def check_login_rate_limit(ip, username):
    """
    Devuelve (allowed: bool, retry_after_seconds: int).
    Limitación básica en memoria para evitar fuerza bruta en /api/login.
    """
    key = _login_rate_key(ip, username)
    if not key:
        return True, 0
    now = time.time()
    with _LOGIN_RATE_LOCK:
        entry = _LOGIN_RATE_STATE.get(key) or {}
        locked_until = float(entry.get("locked_until") or 0)
        if locked_until and locked_until > now:
            return False, int(max(1, locked_until - now))
        attempts = entry.get("attempts") or []
        # Limpia ventana
        attempts = [ts for ts in attempts if (now - float(ts)) <= LOGIN_RATE_WINDOW_SECONDS]
        entry["attempts"] = attempts
        entry["locked_until"] = 0
        _LOGIN_RATE_STATE[key] = entry
        if len(attempts) >= LOGIN_RATE_MAX_ATTEMPTS:
            entry["locked_until"] = now + LOGIN_RATE_LOCK_SECONDS
            _LOGIN_RATE_STATE[key] = entry
            return False, LOGIN_RATE_LOCK_SECONDS
        return True, 0


def register_login_attempt(ip, username, ok=False):
    key = _login_rate_key(ip, username)
    if not key:
        return
    now = time.time()
    with _LOGIN_RATE_LOCK:
        if ok:
            # En login correcto, limpiamos para no penalizar.
            _LOGIN_RATE_STATE.pop(key, None)
            return
        entry = _LOGIN_RATE_STATE.get(key) or {}
        attempts = entry.get("attempts") or []
        attempts.append(now)
        # Limpiar ventana
        attempts = [ts for ts in attempts if (now - float(ts)) <= LOGIN_RATE_WINDOW_SECONDS]
        entry["attempts"] = attempts
        if len(attempts) >= LOGIN_RATE_MAX_ATTEMPTS:
            entry["locked_until"] = now + LOGIN_RATE_LOCK_SECONDS
        _LOGIN_RATE_STATE[key] = entry


def send_mail_smtp(subject, to_email, text_body, html_body=None):
    host = (os.environ.get("SMTP_HOST") or "").strip()
    if not host:
        raise RuntimeError("SMTP_HOST no configurado")
    port = int((os.environ.get("SMTP_PORT") or "587").strip())
    username = (os.environ.get("SMTP_USER") or "").strip()
    password = (os.environ.get("SMTP_PASS") or "").strip()
    from_email = (os.environ.get("SMTP_FROM") or username or "").strip()
    if not from_email:
        raise RuntimeError("SMTP_FROM/SMTP_USER no configurado")
    use_ssl = (os.environ.get("SMTP_SSL") or "").strip().lower() in ("1", "true", "yes", "on")
    use_tls = (os.environ.get("SMTP_TLS") or "1").strip().lower() not in ("0", "false", "no", "off")
    msg = EmailMessage()
    msg["Subject"] = subject
    msg["From"] = from_email
    msg["To"] = to_email
    msg.set_content(text_body)
    if html_body:
        msg.add_alternative(html_body, subtype="html")
    if use_ssl:
        server = smtplib.SMTP_SSL(host, port, timeout=20)
    else:
        server = smtplib.SMTP(host, port, timeout=20)
    try:
        server.ehlo()
        if use_tls and not use_ssl:
            server.starttls()
            server.ehlo()
        if username:
            server.login(username, password)
        server.send_message(msg)
    finally:
        try:
            server.quit()
        except Exception:
            pass


def decode_mime_text(raw):
    if not raw:
        return ""
    parts = []
    try:
        decoded = decode_header(raw)
    except Exception:
        return str(raw)
    for chunk, encoding in decoded:
        if isinstance(chunk, bytes):
            codec = encoding or "utf-8"
            try:
                parts.append(chunk.decode(codec, errors="replace"))
            except Exception:
                parts.append(chunk.decode("utf-8", errors="replace"))
        else:
            parts.append(str(chunk))
    return "".join(parts).strip()


def html_to_text(value):
    text = str(value or "")
    text = re.sub(r"<\s*(script|style)\b[^>]*>.*?<\s*/\s*\1\s*>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def extract_pdf_attachment_text(pdf_bytes, max_pages=2):
    if not pdf_bytes:
        return ""
    tmp_path = ""
    try:
        with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp_file:
            tmp_file.write(pdf_bytes)
            tmp_path = tmp_file.name
        text, err = pdftotext_extract(tmp_path, pages=max_pages)
        if text and len(text.strip()) >= 40:
            return text
        text_full, _detail, _method = extract_pdf_text(tmp_path)
        if text_full:
            return text_full
        return text or ""
    except Exception:
        return ""
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass


def save_campaign_attachment_file(file_bytes, original_name="campana.pdf"):
    if not file_bytes:
        return "", ""
    safe_name = re.sub(r"[^A-Za-z0-9._-]", "_", os.path.basename(original_name or "campana.pdf"))
    if not safe_name.lower().endswith(".pdf"):
        safe_name = f"{safe_name}.pdf"
    folder = UPLOADS / "seguros_campanas"
    folder.mkdir(parents=True, exist_ok=True)
    file_id = os.urandom(16).hex()
    filename = f"{file_id}_{safe_name}"
    file_path = folder / filename
    file_path.write_bytes(file_bytes)
    return f"/uploads/seguros_campanas/{filename}", safe_name


def parse_decimal_amount(value):
    raw = str(value or "").strip()
    if not raw:
        return 0.0
    text = raw.replace("€", "").replace("EUR", "").replace(" ", "")
    text = re.sub(r"[^0-9,.\-]", "", text)
    if not text:
        return 0.0
    if "," in text and "." in text:
        if text.rfind(",") > text.rfind("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        text = text.replace(".", "").replace(",", ".")
    elif "." in text:
        if text.count(".") == 1 and len(text.split(".")[-1]) <= 2:
            pass
        else:
            text = text.replace(".", "")
    try:
        return float(text)
    except Exception:
        return 0.0


def detect_campaign_ramo(text):
    cleaned = normalize_lookup_text(text)
    if not cleaned:
        return ""
    patterns = [
        (r"\bHOGAR\b", "Hogar"),
        (r"\bAUTO\b|\bAUTOMOVIL\b|\bCOCHE\b", "Auto"),
        (r"\bSALUD\b|\bMEDIC(O|A)\b|\bASISTENCIA SANITARIA\b", "Salud"),
        (r"\bDECESOS\b", "Decesos"),
        (r"\bVIDA\b", "Vida"),
        (r"\bCOMERCIO\b|\bPYME\b|\bNEGOCIO\b", "Comercio"),
        (r"\bCOMUNIDAD\b", "Comunidad"),
        (r"\bRESPONSABILIDAD CIVIL\b|\bRC\b", "Responsabilidad civil"),
        (r"\bDEFENSA JURIDICA\b|\bARAG\b", "Defensa jurídica"),
        (r"\bVIAJE\b|\bVIAJES\b", "Viaje"),
        (r"\bAHORRO\b", "Ahorro"),
    ]
    for pattern, ramo in patterns:
        if re.search(pattern, cleaned, re.IGNORECASE):
            return ramo
    return ""


def parse_campaign_dates(text):
    cleaned = str(text or "")
    if not cleaned:
        return "", ""

    def _by_patterns(patterns):
        for pattern in patterns:
            match = re.search(pattern, cleaned, re.IGNORECASE)
            if not match:
                continue
            parsed = parse_iso_date(match.group(1))
            if parsed:
                return parsed.isoformat()
        return ""

    inicio = _by_patterns(
        [
            r"(?:inicio|desde|vigencia\s+desde|validez\s+desde)\s*[:\-]?\s*([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4}|[0-9]{4}-[0-9]{2}-[0-9]{2})",
        ]
    )
    fin = _by_patterns(
        [
            r"(?:fin|hasta|vigencia\s+hasta|validez\s+hasta|v[aá]lida\s+hasta|vence)\s*[:\-]?\s*([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4}|[0-9]{4}-[0-9]{2}-[0-9]{2})",
        ]
    )
    if inicio and fin:
        return inicio, fin
    date_hits = re.findall(r"([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4}|[0-9]{4}-[0-9]{2}-[0-9]{2})", cleaned)
    parsed_dates = []
    for raw in date_hits:
        parsed = parse_iso_date(raw)
        if parsed and parsed.isoformat() not in parsed_dates:
            parsed_dates.append(parsed.isoformat())
    if not inicio and parsed_dates:
        inicio = parsed_dates[0]
    if not fin and len(parsed_dates) > 1:
        fin = parsed_dates[-1]
    if inicio and fin and fin < inicio:
        inicio, fin = fin, inicio
    return inicio, fin


def extract_campaign_from_email(message_obj):
    subject = decode_mime_text(message_obj.get("Subject", ""))
    from_name, from_email = parseaddr(message_obj.get("From", ""))
    from_name = decode_mime_text(from_name)
    sender = " ".join(part for part in [from_name, from_email] if part).strip()

    text_parts = []
    html_parts = []
    attachment_parts = []
    primary_pdf_bytes = b""
    primary_pdf_name = ""
    if message_obj.is_multipart():
        for part in message_obj.walk():
            if part.get_content_maintype() == "multipart":
                continue
            content_type = str(part.get_content_type() or "").lower()
            filename = decode_mime_text(part.get_filename() or "")
            disposition = str(part.get("Content-Disposition") or "").lower()
            payload = part.get_payload(decode=True)
            if payload is None:
                continue
            is_attachment = ("attachment" in disposition) or bool(filename)
            is_pdf_attachment = content_type == "application/pdf" or filename.lower().endswith(".pdf")
            if is_attachment and is_pdf_attachment:
                pdf_text = extract_pdf_attachment_text(payload, max_pages=2)
                if pdf_text:
                    attachment_parts.append(pdf_text[:12000])
                if (not primary_pdf_bytes) and payload:
                    primary_pdf_bytes = payload
                    primary_pdf_name = filename or "campana.pdf"
                continue
            if is_attachment:
                continue
            charset = part.get_content_charset() or "utf-8"
            try:
                decoded = payload.decode(charset, errors="replace")
            except Exception:
                decoded = payload.decode("utf-8", errors="replace")
            if content_type == "text/plain":
                text_parts.append(decoded)
            elif content_type == "text/html":
                html_parts.append(decoded)
    else:
        payload = message_obj.get_payload(decode=True)
        if payload:
            charset = message_obj.get_content_charset() or "utf-8"
            try:
                decoded = payload.decode(charset, errors="replace")
            except Exception:
                decoded = payload.decode("utf-8", errors="replace")
            if str(message_obj.get_content_type() or "").lower() == "text/html":
                html_parts.append(decoded)
            else:
                text_parts.append(decoded)

    body = "\n".join(text_parts).strip() or html_to_text("\n".join(html_parts))
    attachment_text = "\n".join(attachment_parts).strip()
    search_blob = " ".join(part for part in [subject, sender, body, attachment_text] if part).strip()

    compania = detect_company_from_metadata(subject, sender, body)
    if not compania:
        compania = detect_company_from_text(search_blob)
    if not compania and from_email and "@" in from_email:
        domain = from_email.split("@", 1)[-1].lower().strip()
        domain_hits = {
            "mapfre.com": "Mapfre",
            "allianz.es": "Allianz",
            "axa.es": "AXA",
            "zurich.com": "Zurich",
            "lineadirecta.com": "Línea Directa",
            "santalucia.es": "Santa Lucia",
            "caser.es": "Caser",
            "ocaso.es": "Ocaso",
            "generali.com": "Generali",
            "fiatc.es": "Fiatc",
            "mutua.es": "Mutua Madrileña",
            "dkv.es": "DKV",
            "adeslas.es": "Adeslas",
            "asisa.es": "Asisa",
            "sanitas.es": "Sanitas",
        }
        for key, name in domain_hits.items():
            if domain == key or domain.endswith(f".{key}"):
                compania = name
                break
    ramo = detect_campaign_ramo(search_blob) or canonicalize_ramo(search_blob)
    if not ramo:
        ramo_match = re.search(r"\bramo\s*[:\-]?\s*([A-Za-zÁÉÍÓÚÜÑñçÇ\s]{3,40})", body or "", re.IGNORECASE)
        if ramo_match:
            ramo = canonicalize_ramo(ramo_match.group(1))
    fecha_inicio, fecha_fin = parse_campaign_dates(search_blob)

    precio_base = 0.0
    comision_pct = 0.0
    comision_fija = 0.0
    price_match = re.search(
        r"(?:precio|prima|tarifa|cuota|desde)\s*(?:base)?\s*[:\-]?\s*([0-9][0-9.,]{0,14})\s*€?",
        search_blob,
        re.IGNORECASE,
    )
    if price_match:
        precio_base = parse_decimal_amount(price_match.group(1))
    pct_match = re.search(
        r"(?:comisi[oó]n|brokerage|mediaci[oó]n)[^%\n\r]{0,24}([0-9]{1,2}(?:[.,][0-9]{1,2})?)\s*%",
        search_blob,
        re.IGNORECASE,
    )
    if pct_match:
        comision_pct = parse_decimal_amount(pct_match.group(1))
    fijo_match = re.search(
        r"(?:comisi[oó]n|fee|honorario)[^€\n\r]{0,24}([0-9][0-9.,]{0,14})\s*€",
        search_blob,
        re.IGNORECASE,
    )
    if fijo_match:
        comision_fija = parse_decimal_amount(fijo_match.group(1))

    url_match = re.search(r"(https?://[^\s<>\"]+)", search_blob, re.IGNORECASE)
    url = (url_match.group(1).rstrip(").,;]") if url_match else "")
    campaign_name = re.sub(r"^(RE|RV|FW|FWD)\s*:\s*", "", subject, flags=re.IGNORECASE).strip()
    if not campaign_name:
        campaign_name = f"Campaña correo {datetime.now().strftime('%Y-%m-%d')}"
    if compania and campaign_name.lower() in {"campaña", "campana", "campaña correo"}:
        campaign_name = f"Campaña {compania}"
    description = re.sub(r"\s+", " ", body).strip()
    if len(description) < 20:
        fallback_desc = " · ".join(part for part in [f"Asunto: {subject}" if subject else "", f"Remitente: {sender}" if sender else ""] if part)
        description = fallback_desc or description
    if len(description) < 40 and attachment_text:
        attachment_summary = re.sub(r"\s+", " ", attachment_text).strip()
        if len(attachment_summary) > 500:
            attachment_summary = f"{attachment_summary[:497]}..."
        description = f"{description} · PDF: {attachment_summary}".strip(" ·")
    if len(description) > 700:
        description = f"{description[:697]}..."

    quality = 0
    if compania:
        quality += 1
    if ramo:
        quality += 1
    if url:
        quality += 1
    if abs(precio_base) > 0.0001 or abs(comision_pct) > 0.0001 or abs(comision_fija) > 0.0001:
        quality += 1
    if description and len(description) >= 40:
        quality += 1

    return {
        "compania": normalize_company_name(compania),
        "nombre": campaign_name,
        "ramo": ramo or "",
        "origen": "Correo",
        "fecha_inicio": fecha_inicio,
        "fecha_fin": fecha_fin,
        "descripcion": description,
        "url": url,
        "precio_base": round(precio_base, 2) if abs(precio_base) > 0.0001 else None,
        "comision_pct": round(comision_pct, 2) if abs(comision_pct) > 0.0001 else None,
        "comision_fija": round(comision_fija, 2) if abs(comision_fija) > 0.0001 else None,
        "remitente": sender,
        "quality": quality,
        "adjunto_bytes": primary_pdf_bytes,
        "adjunto_nombre": primary_pdf_name,
    }


def import_campaigns_from_mailbox(conn, payload, now):
    host = (payload.get("host") or os.environ.get("CAMPAIGN_IMAP_HOST") or os.environ.get("IMAP_HOST") or "").strip()
    user = (payload.get("user") or os.environ.get("CAMPAIGN_IMAP_USER") or os.environ.get("IMAP_USER") or "").strip()
    password = str(payload.get("password") or os.environ.get("CAMPAIGN_IMAP_PASS") or os.environ.get("IMAP_PASS") or "").strip()
    mailbox = str(payload.get("mailbox") or os.environ.get("CAMPAIGN_IMAP_MAILBOX") or "INBOX").strip() or "INBOX"
    search = str(payload.get("search") or os.environ.get("CAMPAIGN_IMAP_SEARCH") or "UNSEEN").strip() or "UNSEEN"
    ssl_enabled = str(payload.get("ssl") or os.environ.get("CAMPAIGN_IMAP_SSL") or "1").strip().lower() not in ("0", "false", "no", "off")
    mark_seen = str(payload.get("mark_seen") or "1").strip().lower() not in ("0", "false", "no", "off")
    try:
        port = int(str(payload.get("port") or os.environ.get("CAMPAIGN_IMAP_PORT") or (993 if ssl_enabled else 143)).strip())
    except Exception:
        port = 993 if ssl_enabled else 143
    try:
        limit = max(1, min(50, int(str(payload.get("limit") or "20").strip() or "20")))
    except Exception:
        limit = 20
    if not host or not user or not password:
        raise RuntimeError("Configura host, usuario y contraseña IMAP.")

    if ssl_enabled:
        mail = imaplib.IMAP4_SSL(host, port)
    else:
        mail = imaplib.IMAP4(host, port)
        mail.starttls()
    created = 0
    skipped = 0
    errors = []
    preview = []
    try:
        mail.login(user, password)
        status, _ = mail.select(mailbox, readonly=False)
        if status != "OK":
            raise RuntimeError(f"No se pudo abrir el buzón '{mailbox}'.")
        status, data = mail.search(None, search)
        if status != "OK":
            raise RuntimeError(f"No se pudo ejecutar búsqueda IMAP '{search}'.")
        raw_ids = [token for token in (data[0] or b"").split() if token]
        if not raw_ids:
            return {"created": 0, "skipped": 0, "preview": []}
        for seq_id in raw_ids[-limit:]:
            try:
                fetch_status, msg_data = mail.fetch(seq_id, "(UID BODY.PEEK[])")
                if fetch_status != "OK" or not msg_data:
                    skipped += 1
                    continue
                raw_message = None
                imap_uid = ""
                for item in msg_data:
                    if not isinstance(item, tuple) or len(item) < 2:
                        continue
                    meta = item[0] if isinstance(item[0], (bytes, bytearray)) else b""
                    body_bytes = item[1]
                    if body_bytes and raw_message is None:
                        raw_message = body_bytes
                    uid_match = re.search(rb"UID\s+(\d+)", meta or b"")
                    if uid_match:
                        imap_uid = uid_match.group(1).decode("utf-8", errors="ignore")
                if not raw_message:
                    skipped += 1
                    continue
                msg = email.message_from_bytes(raw_message)
                subject = decode_mime_text(msg.get("Subject", ""))
                sender = decode_mime_text(msg.get("From", ""))
                date_header = str(msg.get("Date") or "").strip()
                message_id = str(msg.get("Message-ID") or "").strip()
                seq_label = seq_id.decode("utf-8", errors="ignore") if isinstance(seq_id, (bytes, bytearray)) else str(seq_id)
                fingerprint = f"{subject}|{sender}|{date_header}|{imap_uid or seq_label}"
                dedupe_key = message_id or f"sha1:{hashlib.sha1(fingerprint.encode('utf-8')).hexdigest()}"
                seen = conn.execute(
                    "SELECT 1 FROM seguros_campanas_mail_seen WHERE message_id = ? LIMIT 1",
                    (dedupe_key,),
                ).fetchone()
                if seen:
                    skipped += 1
                    if mark_seen:
                        try:
                            mail.store(seq_id, "+FLAGS", "(\\Seen)")
                        except Exception:
                            pass
                    continue
                parsed = extract_campaign_from_email(msg)
                if int(parsed.get("quality") or 0) < 2:
                    skipped += 1
                    conn.execute(
                        """
                        INSERT INTO seguros_campanas_mail_seen (
                          id, message_id, mailbox_uid, remitente, asunto, fecha_mail, campaign_id, created_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime(?))
                        """,
                        (
                            os.urandom(16).hex(),
                            dedupe_key,
                            imap_uid,
                            parsed.get("remitente") or sender,
                            f"[IGNORADO BAJA_CALIDAD] {subject}",
                            date_header,
                            None,
                            now,
                        ),
                    )
                    continue
                campaign_id = os.urandom(16).hex()
                adjunto_url = ""
                adjunto_nombre = ""
                adjunto_bytes = parsed.get("adjunto_bytes") or b""
                if adjunto_bytes:
                    try:
                        adjunto_url, adjunto_nombre = save_campaign_attachment_file(
                            adjunto_bytes,
                            parsed.get("adjunto_nombre") or f"{campaign_id}.pdf",
                        )
                    except Exception as exc:
                        if len(errors) < 5:
                            errors.append(f"Adjunto PDF no guardado ({subject}): {exc}")
                conn.execute(
                    """
                    INSERT INTO seguros_campanas (
                      id, compania, nombre, ramo, origen, fecha_inicio, fecha_fin, descripcion, url, adjunto_url, adjunto_nombre, precio_base, comision_pct, comision_fija,
                      created_at, updated_at
                    ) VALUES (
                      ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
                    )
                    """,
                    (
                        campaign_id,
                        parsed.get("compania"),
                        parsed.get("nombre"),
                        canonicalize_ramo(parsed.get("ramo")) or parsed.get("ramo"),
                        parsed.get("origen") or "Correo",
                        parsed.get("fecha_inicio") or None,
                        parsed.get("fecha_fin") or None,
                        parsed.get("descripcion") or None,
                        parsed.get("url") or None,
                        adjunto_url or None,
                        adjunto_nombre or None,
                        parsed.get("precio_base"),
                        parsed.get("comision_pct"),
                        parsed.get("comision_fija"),
                        now,
                        now,
                    ),
                )
                conn.execute(
                    """
                    INSERT INTO seguros_campanas_mail_seen (
                      id, message_id, mailbox_uid, remitente, asunto, fecha_mail, campaign_id, created_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime(?))
                    """,
                    (
                        os.urandom(16).hex(),
                        dedupe_key,
                        imap_uid,
                        parsed.get("remitente") or sender,
                        subject,
                        date_header,
                        campaign_id,
                        now,
                    ),
                )
                created += 1
                if mark_seen:
                    try:
                        mail.store(seq_id, "+FLAGS", "(\\Seen)")
                    except Exception:
                        pass
                if len(preview) < 10:
                    preview.append(
                        {
                            "compania": parsed.get("compania") or "",
                            "nombre": parsed.get("nombre") or "",
                            "ramo": parsed.get("ramo") or "",
                        }
                    )
            except Exception as exc:
                skipped += 1
                if len(errors) < 5:
                    errors.append(str(exc))
    finally:
        try:
            mail.logout()
        except Exception:
            pass
    return {"created": created, "skipped": skipped, "preview": preview, "errors": errors}

def detect_ocr_lang():
    if os.path.isdir(TESSDATA_DIR):
        has_spa = os.path.exists(os.path.join(TESSDATA_DIR, "spa.traineddata"))
        has_eng = os.path.exists(os.path.join(TESSDATA_DIR, "eng.traineddata"))
        if has_spa and has_eng:
            return "spa+eng"
        if has_spa:
            return "spa"
        if has_eng:
            return "eng"
    return "spa+eng"


def run_subprocess(args, **kwargs):
    kwargs.setdefault("timeout", OCR_SUBPROCESS_TIMEOUT_SECONDS)
    return subprocess.run(args, **kwargs)


def is_stale_ocr_job(started_at):
    if not started_at:
        return False
    raw = str(started_at).strip()
    if not raw:
        return False
    if raw.endswith("Z"):
        raw = raw[:-1]
    try:
        started_dt = datetime.fromisoformat(raw)
    except Exception:
        return False
    if started_dt.tzinfo is None:
        started_dt = started_dt.replace(tzinfo=timezone.utc)
    return datetime.now(timezone.utc) - started_dt > timedelta(minutes=OCR_JOB_STALE_MINUTES)


def s3_config():
    bucket = os.environ.get("AWS_S3_BUCKET") or os.environ.get("S3_BUCKET") or S3_BUCKET
    region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION") or S3_REGION
    return bucket, region

def s3_client():
    global S3_BOTO3_AVAILABLE
    try:
        import boto3
        from botocore.config import Config
    except ImportError:
        S3_BOTO3_AVAILABLE = False
        return None
    bucket, region = s3_config()
    if not bucket or not region:
        return None
    return boto3.client(
        "s3",
        region_name=region,
        config=Config(
            signature_version="s3v4",
            s3={"addressing_style": "virtual"},
        ),
    )


def s3_safe_key(prefix, filename):
    base = os.path.basename(filename or "archivo.pdf")
    safe = re.sub(r"[^A-Za-z0-9._-]", "_", base)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    rand = os.urandom(4).hex()
    prefix = prefix.strip("/").strip() if prefix else "seguros"
    return f"{prefix}/{stamp}_{rand}_{safe}"

def s3_get_object_bytes(key):
    client = s3_client()
    if not client:
        return None, "S3 no configurado"
    bucket, _region = s3_config()
    if not bucket:
        return None, "S3 sin bucket"
    try:
        obj = client.get_object(Bucket=bucket, Key=key)
        return obj["Body"].read(), ""
    except Exception as exc:
        return None, str(exc)


def decode_seguros_payload(payload):
    data_uri = payload.get("file_base64") or payload.get("data")
    s3_key = (payload.get("s3_key") or "").strip()
    pdf_bytes = None
    if s3_key:
        pdf_bytes, s3_err = s3_get_object_bytes(s3_key)
        if not pdf_bytes:
            raise ValueError(f"S3: {s3_err}")
    else:
        if not data_uri:
            raise ValueError("Archivo requerido")
        if "," in data_uri:
            data_uri = data_uri.split(",", 1)[1]
        try:
            pdf_bytes = base64.b64decode(data_uri)
        except Exception:
            raise ValueError("Base64 invalido")
    return pdf_bytes


def decode_document_payload(payload):
    data_uri = payload.get("file_base64") or payload.get("data")
    s3_key = (payload.get("s3_key") or "").strip()
    raw_bytes = None
    mime = ""
    filename = str(payload.get("filename") or "").strip()
    if s3_key:
        raw_bytes, s3_err = s3_get_object_bytes(s3_key)
        if not raw_bytes:
            raise ValueError(f"S3: {s3_err}")
        lower_key = s3_key.lower()
        if lower_key.endswith(".pdf"):
            mime = "application/pdf"
        elif lower_key.endswith((".jpg", ".jpeg")):
            mime = "image/jpeg"
        elif lower_key.endswith(".png"):
            mime = "image/png"
    else:
        if not data_uri:
            raise ValueError("Archivo requerido")
        if "," in data_uri:
            header, data_uri = data_uri.split(",", 1)
            if header.startswith("data:") and ";base64" in header:
                mime = header.split(":", 1)[1].split(";", 1)[0]
        try:
            raw_bytes = base64.b64decode(data_uri)
        except Exception:
            raise ValueError("Base64 invalido")
    if not raw_bytes:
        raise ValueError("Archivo vacio")
    source_hint = " ".join(
        [
            filename,
            str(payload.get("source_hint") or ""),
            s3_key,
        ]
    ).strip()
    return raw_bytes, mime, source_hint


def parse_decimal_eu(value):
    raw = str(value or "").strip()
    if not raw:
        return 0.0
    raw = raw.replace("€", "").replace("EUR", "").replace(" ", "")
    if "," in raw and "." in raw:
        if raw.rfind(",") > raw.rfind("."):
            raw = raw.replace(".", "").replace(",", ".")
        else:
            raw = raw.replace(",", "")
    elif "," in raw:
        raw = raw.replace(".", "").replace(",", ".")
    raw = re.sub(r"[^0-9.\-]", "", raw)
    if raw in ("", ".", "-", "-."):
        return 0.0
    try:
        return float(raw)
    except Exception:
        return 0.0


def extract_invoice_amount(text, labels):
    if not text:
        return 0.0
    for label in labels:
        pattern = rf"{label}\s*[:\-]?\s*([0-9][0-9\.\,\s€]*)"
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            value = parse_decimal_eu(match.group(1))
            if value > 0:
                return value
    return 0.0


def parse_invoice_text(text):
    raw = str(text or "")
    upper = normalize_lookup_text(raw)
    if not raw.strip():
        return {}
    numero = ""
    numero_match = re.search(
        r"(?:factura|fra\.?|n[úu]m(?:ero)?|n[º°])\s*[:#-]?\s*([A-Z0-9][A-Z0-9\-\/\.]{2,})",
        raw,
        re.IGNORECASE,
    )
    if numero_match:
        numero = numero_match.group(1).strip()
    fecha = ""
    fecha_match = re.search(r"\b(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})\b", raw)
    if fecha_match:
        fecha = fecha_match.group(1).strip()
    fecha_iso = ""
    if fecha:
        date_bits = re.split(r"[\/\-]", fecha)
        if len(date_bits) == 3:
            day, month, year = date_bits
            if len(year) == 2:
                year = f"20{year}"
            try:
                fecha_iso = f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
            except Exception:
                fecha_iso = ""
    nif_candidates = re.findall(
        r"\b(?:[ABCDEFGHJNPQRSUVW]\d{7}[0-9A-J]|\d{8}[A-Z])\b",
        upper,
        re.IGNORECASE,
    )
    nif = nif_candidates[0].upper() if nif_candidates else ""
    tercero = ""
    for pattern in (
        r"(?:proveedor|acreedor)\s*[:\-]\s*([^\n\r]{3,80})",
        r"(?:raz[oó]n social)\s*[:\-]\s*([^\n\r]{3,80})",
        r"(?:cliente)\s*[:\-]\s*([^\n\r]{3,80})",
    ):
        m = re.search(pattern, raw, re.IGNORECASE)
        if m:
            tercero = m.group(1).strip(" .;:")
            break
    tipo = "compra"
    if any(token in upper for token in ("FACTURA EMITIDA", "TOTAL A COBRAR", "CLIENTE")):
        tipo = "venta"
    base = extract_invoice_amount(raw, ["base imponible", "subtotal", "base"])
    cuota_iva = extract_invoice_amount(raw, ["cuota iva", "iva", "i\\.v\\.a\\."])
    cuota_irpf = extract_invoice_amount(raw, ["retencion", "irpf"])
    total = extract_invoice_amount(raw, ["total factura", "importe total", "total a pagar", "total"])
    if base <= 0 and total > 0:
        base = max(0.0, total - cuota_iva + cuota_irpf)
    if total <= 0 and base > 0:
        total = max(0.0, base + cuota_iva - cuota_irpf)
    iva_pct = 0.0
    pct_match = re.search(r"\b(4|10|21)(?:[.,]0+)?\s*%\b", raw)
    if pct_match:
        iva_pct = parse_decimal_eu(pct_match.group(1))
    elif base > 0 and cuota_iva > 0:
        iva_pct = round((cuota_iva / base) * 100.0, 2)
    descripcion = numero or "Factura"
    if tercero:
        descripcion = f"{descripcion} · {tercero}"
    return {
        "numero": numero,
        "fecha": fecha_iso,
        "nif": nif,
        "tercero": tercero,
        "tipo": tipo,
        "base_imponible": round(base, 2),
        "cuota_iva": round(cuota_iva, 2),
        "cuota_irpf": round(cuota_irpf, 2),
        "total": round(total, 2),
        "iva_pct": iva_pct,
        "descripcion": descripcion,
        "raw_text": raw.strip(),
    }


def infer_expense_account(concepto):
    text = normalize_lookup_text(concepto or "")
    mapping = [
        ("ALQUILER", "621"),
        ("ARRENDAMIENTO", "621"),
        ("REPARACION", "622"),
        ("CONSERVACION", "622"),
        ("PROFESIONAL", "623"),
        ("HONORARIO", "623"),
        ("TRANSPORTE", "624"),
        ("SEGURO", "625"),
        ("BANC", "626"),
        ("PUBLICIDAD", "627"),
        ("SUMINISTRO", "628"),
        ("LUZ", "628"),
        ("AGUA", "628"),
        ("TELEFON", "628"),
        ("INTERNET", "628"),
        ("TRIBUTO", "631"),
        ("IMPUESTO", "631"),
    ]
    for token, account in mapping:
        if token in text:
            return account
    return "629"


def infer_revenue_account(concepto):
    text = normalize_lookup_text(concepto or "")
    if "ALQUILER" in text:
        return "705"
    return "700"


def ensure_gestoria_tercero(conn, empresa_id, nif, nombre, tipo, now):
    nif_clean = (nif or "").strip().upper()
    name_clean = (nombre or "").strip()
    kind = (tipo or "").strip().lower() or "proveedor"
    account_map = {"proveedor": "400", "acreedor": "410", "cliente": "430"}
    account = account_map.get(kind, "400")
    row = None
    if name_clean:
        row = conn.execute(
            "SELECT id, cuenta_contable, nombre, nif FROM gestoria_terceros WHERE empresa_id = ? AND UPPER(COALESCE(nombre,'')) = UPPER(?) LIMIT 1",
            (empresa_id, name_clean),
        ).fetchone()
    if not row and nif_clean:
        nif_row = conn.execute(
            "SELECT id, cuenta_contable, nombre, nif FROM gestoria_terceros WHERE empresa_id = ? AND UPPER(COALESCE(nif,'')) = ? LIMIT 1",
            (empresa_id, nif_clean),
        ).fetchone()
        if nif_row:
            existing_name = normalize_lookup_text(nif_row["nombre"] or "")
            current_name = normalize_lookup_text(name_clean or "")
            if existing_name and current_name and existing_name != current_name:
                nif_clean = ""
            else:
                row = nif_row
    if row:
        conn.execute(
            """
            UPDATE gestoria_terceros
            SET nif = COALESCE(NULLIF(?, ''), nif),
                nombre = COALESCE(NULLIF(?, ''), nombre),
                tipo = ?,
                cuenta_contable = COALESCE(NULLIF(cuenta_contable, ''), ?),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (nif_clean, name_clean, kind, account, now, row["id"]),
        )
        return row["id"], row["cuenta_contable"] or account
    tercero_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_terceros (
          id, empresa_id, nif, nombre, tipo, cuenta_contable, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, datetime(?), datetime(?))
        """,
        (tercero_id, empresa_id, nif_clean, name_clean, kind, account, now, now),
    )
    return tercero_id, account


def build_invoice_asiento(parsed, counterpart_account):
    tipo = (parsed.get("tipo") or "compra").strip().lower()
    base = float(parsed.get("base_imponible") or 0.0)
    iva = float(parsed.get("cuota_iva") or 0.0)
    irpf = float(parsed.get("cuota_irpf") or 0.0)
    total = float(parsed.get("total") or 0.0)
    concepto = parsed.get("descripcion") or parsed.get("numero") or "Factura"
    lines = []
    if tipo == "venta":
        ingreso = infer_revenue_account(concepto)
        if total > 0:
            lines.append({"cuenta": counterpart_account or "430", "descripcion": "Cliente", "debe": round(total, 2), "haber": 0.0})
        if base > 0:
            lines.append({"cuenta": ingreso, "descripcion": "Ingreso", "debe": 0.0, "haber": round(base, 2)})
        if iva > 0:
            lines.append({"cuenta": "477", "descripcion": "IVA repercutido", "debe": 0.0, "haber": round(iva, 2), "impuesto": "IVA", "porcentaje": parsed.get("iva_pct") or 0.0})
    else:
        gasto = infer_expense_account(concepto)
        if base > 0:
            lines.append({"cuenta": gasto, "descripcion": "Gasto", "debe": round(base, 2), "haber": 0.0})
        if iva > 0:
            lines.append({"cuenta": "472", "descripcion": "IVA soportado", "debe": round(iva, 2), "haber": 0.0, "impuesto": "IVA", "porcentaje": parsed.get("iva_pct") or 0.0})
        if irpf > 0:
            lines.append({"cuenta": "4751", "descripcion": "H.P. acreedora retenciones", "debe": 0.0, "haber": round(irpf, 2), "impuesto": "IRPF", "porcentaje": 0.0})
        payable = total if total > 0 else max(0.0, base + iva - irpf)
        if payable > 0:
            lines.append({"cuenta": counterpart_account or "400", "descripcion": "Proveedor/Acreedor", "debe": 0.0, "haber": round(payable, 2)})
    debe = round(sum(float(item.get("debe") or 0.0) for item in lines), 2)
    haber = round(sum(float(item.get("haber") or 0.0) for item in lines), 2)
    return lines, debe, haber


def normalize_import_review_state(value):
    state = normalize_lookup_text(value or "")
    if state in {"OK", "VALIDADO", "APROBADO"}:
        return "OK"
    if state in {"DUPLICADO", "DUPLICATE"}:
        return "DUPLICADO"
    if state in {"ERROR", "ERR"}:
        return "ERROR"
    if state in {"REVISAR", "REVISION", "PENDIENTE", "PENDIENTE REVISION"}:
        return "REVISAR"
    return "REVISAR"


def normalize_import_reasons(value):
    if isinstance(value, (list, tuple, set)):
        items = [str(item or "").strip() for item in value]
        return ",".join(item for item in items if item)
    return str(value or "").strip()


def parse_confidence_value(value):
    if value in (None, ""):
        return 0.0
    try:
        parsed = float(value)
    except Exception:
        parsed = parse_money_value(value)
    if parsed < 0:
        return 0.0
    if parsed > 1:
        return 1.0 if parsed <= 100 else parsed
    return round(parsed, 4)


def map_import_category_to_account(category):
    key = normalize_lookup_text(category or "")
    mapping = {
        "ALQUILER LOCAL": "621",
        "SUMINISTROS": "628",
        "SEGURO LOCAL": "625",
        "SEGURO RC": "625",
        "SEGURO CONVENIO": "625",
        "GESTORIA": "623",
        "LOPD": "623",
        "PRL": "623",
        "CANAL DE DENUNCIAS": "623",
        "SALUD": "642",
        "ILT": "642",
        "SALARIOS": "640",
        "COMIDAS": "629",
        "VIAJE": "624",
        "INGRESO": "700",
    }
    return mapping.get(key, "")


def import_category_is_expense(category):
    return normalize_lookup_text(category or "") in {
        "SEGURO LOCAL",
        "SEGURO RC",
        "ALQUILER LOCAL",
        "SALARIOS",
        "SUMINISTROS",
        "LOPD",
        "PRL",
        "CANAL DE DENUNCIAS",
        "SEGURO CONVENIO",
        "GESTORIA",
        "SALUD",
        "ILT",
    }


def import_number_is_suspicious(value):
    token = normalize_lookup_text(value or "")
    if not token:
        return False
    if token in {"PAGADO", "EMITIDA", "CALLE", "SIMPLIFICADA", "FACTURA", "GAPP", "ORIGINAL"}:
        return True
    if not any(ch.isdigit() for ch in token):
        return True
    if re.fullmatch(r"\d{1,2}", token):
        return True
    if re.fullmatch(r"\d{4}", token):
        return True
    return False


def import_vendor_is_suspicious(value):
    token = normalize_lookup_text(value or "")
    if not token:
        return True
    if token in {"Q", "QO", "ORIGINAL", "PAGADO", "EMITIDA", "MES FEBRERO"}:
        return True
    letters = re.sub(r"[^A-Z]", "", token)
    if len(letters) <= 2:
        return True
    return False


def import_vat_is_implausible(base, cuota_iva, total):
    base = float(base or 0.0)
    cuota_iva = float(cuota_iva or 0.0)
    total = float(total or 0.0)
    if cuota_iva < 0:
        return True
    if cuota_iva <= 0:
        return False
    if total > 0 and cuota_iva > total + 0.01:
        return True
    if base > 0:
        if cuota_iva / max(base, 0.01) > 0.30:
            return True
        if total > 0 and abs((base + cuota_iva) - total) > max(1.0, total * 0.15):
            return True
    return False


def validate_import_document_for_apply(document_row):
    if not isinstance(document_row, dict):
        document_row = dict(document_row)
    reasons = []
    categoria = str(document_row.get("categoria_detectada") or "").strip()
    tipo = str(document_row.get("tipo_detectado") or "compra").strip().lower()
    numero = str(document_row.get("numero_detectado") or "").strip()
    tercero = str(document_row.get("tercero_detectado") or "").strip()
    base = parse_money_value(document_row.get("base_detectada"))
    cuota_iva = parse_money_value(document_row.get("cuota_iva_detectada"))
    total = parse_money_value(document_row.get("total_detectado"))
    if import_category_is_expense(categoria) and tipo == "venta":
        reasons.append("tipo_venta_en_gasto")
    if total <= 0 and base <= 0:
        reasons.append("importe_invalido")
    if import_vat_is_implausible(base, cuota_iva, total):
        reasons.append("iva_inverosimil")
    if import_number_is_suspicious(numero):
        reasons.append("numero_dudoso")
    if import_vendor_is_suspicious(tercero):
        reasons.append("proveedor_dudoso")
    return reasons


def describe_import_record(record):
    numero = str(record.get("numero_detectado") or record.get("numero") or "").strip()
    tercero = str(record.get("tercero_detectado") or record.get("tercero") or "").strip()
    categoria = str(record.get("categoria_detectada") or record.get("categoria_excel") or "").strip()
    archivo = str(record.get("archivo_nombre") or record.get("archivo") or "").strip()
    concept_parts = [part for part in (numero, tercero or categoria or archivo) if part]
    return " · ".join(concept_parts) or "Factura importada"


def ensure_gestoria_import_schema(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_lotes (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          origen TEXT,
          estado TEXT NOT NULL,
          periodo TEXT,
          carpeta_origen TEXT,
          template_path TEXT,
          total_documentos INTEGER NOT NULL DEFAULT 0,
          total_ok INTEGER NOT NULL DEFAULT 0,
          total_revisar INTEGER NOT NULL DEFAULT 0,
          total_duplicado INTEGER NOT NULL DEFAULT 0,
          total_error INTEGER NOT NULL DEFAULT 0,
          notas TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id)
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_documentos (
          id TEXT PRIMARY KEY,
          lote_id TEXT NOT NULL,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          factura_id TEXT,
          tercero_id TEXT,
          gestoria_doc_id TEXT,
          archivo_nombre TEXT NOT NULL,
          archivo_hash TEXT,
          doc_key TEXT,
          numero_detectado TEXT,
          fecha_detectada TEXT,
          tercero_detectado TEXT,
          nif_detectado TEXT,
          base_detectada REAL,
          cuota_iva_detectada REAL,
          total_detectado REAL,
          tipo_detectado TEXT,
          categoria_detectada TEXT,
          subcategoria_detectada TEXT,
          cuenta_sugerida TEXT,
          cuenta_tercero_sugerida TEXT,
          confianza_categoria REAL,
          confianza_extraccion REAL,
          estado_revision TEXT NOT NULL,
          motivos_revision TEXT,
          regla_aplicada TEXT,
          ocr_metodo TEXT,
          ocr_error TEXT,
          raw_text TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (lote_id) REFERENCES gestoria_import_lotes(id),
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id),
          FOREIGN KEY (factura_id) REFERENCES gestoria_facturas(id),
          FOREIGN KEY (tercero_id) REFERENCES gestoria_terceros(id),
          FOREIGN KEY (gestoria_doc_id) REFERENCES gestoria_docs(id)
        )
        """
    )
    conn.execute(
        """
        CREATE UNIQUE INDEX IF NOT EXISTS idx_gestoria_import_documentos_lote_archivo
        ON gestoria_import_documentos (lote_id, archivo_nombre)
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_documentos_estado
        ON gestoria_import_documentos (estado_revision)
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_documentos_hash
        ON gestoria_import_documentos (archivo_hash)
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_reglas (
          id TEXT PRIMARY KEY,
          empresa_id TEXT NOT NULL,
          cliente_id TEXT,
          ambito TEXT NOT NULL,
          prioridad INTEGER NOT NULL DEFAULT 100,
          activo INTEGER NOT NULL DEFAULT 1,
          proveedor_match TEXT,
          proveedor_nif_match TEXT,
          texto_match TEXT,
          categoria_forzada TEXT,
          tercero_nombre_forzado TEXT,
          tercero_nif_forzado TEXT,
          cuenta_gasto_forzada TEXT,
          cuenta_tercero_forzada TEXT,
          iva_pct_forzado REAL,
          auto_ok INTEGER NOT NULL DEFAULT 0,
          notas TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (empresa_id) REFERENCES empresas(id),
          FOREIGN KEY (cliente_id) REFERENCES clientes(id)
        )
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_reglas_scope
        ON gestoria_import_reglas (empresa_id, cliente_id, activo, prioridad)
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS gestoria_import_eventos (
          id TEXT PRIMARY KEY,
          lote_id TEXT NOT NULL,
          documento_id TEXT,
          factura_id TEXT,
          tipo TEXT NOT NULL,
          detalle TEXT,
          payload_json TEXT,
          created_at TEXT NOT NULL,
          FOREIGN KEY (lote_id) REFERENCES gestoria_import_lotes(id),
          FOREIGN KEY (documento_id) REFERENCES gestoria_import_documentos(id),
          FOREIGN KEY (factura_id) REFERENCES gestoria_facturas(id)
        )
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_gestoria_import_eventos_lote
        ON gestoria_import_eventos (lote_id, created_at)
        """
    )


def log_gestoria_import_event(conn, lote_id, tipo, now, documento_id=None, factura_id=None, detalle=None, payload=None):
    conn.execute(
        """
        INSERT INTO gestoria_import_eventos (
          id, lote_id, documento_id, factura_id, tipo, detalle, payload_json, created_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, datetime(?)
        )
        """,
        (
            os.urandom(16).hex(),
            lote_id,
            documento_id,
            factura_id,
            tipo,
            detalle,
            json.dumps(payload, ensure_ascii=False) if payload is not None else None,
            now,
        ),
    )


def refresh_gestoria_import_lote_totals(conn, lote_id, now):
    summary = conn.execute(
        """
        SELECT
          COUNT(*) AS total_documentos,
          SUM(CASE WHEN estado_revision = 'OK' THEN 1 ELSE 0 END) AS total_ok,
          SUM(CASE WHEN estado_revision = 'REVISAR' THEN 1 ELSE 0 END) AS total_revisar,
          SUM(CASE WHEN estado_revision = 'DUPLICADO' THEN 1 ELSE 0 END) AS total_duplicado,
          SUM(CASE WHEN estado_revision = 'ERROR' THEN 1 ELSE 0 END) AS total_error
        FROM gestoria_import_documentos
        WHERE lote_id = ?
        """,
        (lote_id,),
    ).fetchone()
    if not summary:
        summary = {
            "total_documentos": 0,
            "total_ok": 0,
            "total_revisar": 0,
            "total_duplicado": 0,
            "total_error": 0,
        }
    total_ok = int(summary["total_ok"] or 0)
    total_revisar = int(summary["total_revisar"] or 0)
    total_duplicado = int(summary["total_duplicado"] or 0)
    total_error = int(summary["total_error"] or 0)
    if total_error > 0:
        estado = "con_errores"
    elif total_revisar > 0:
        estado = "pendiente_revision"
    elif total_ok > 0:
        estado = "preparado"
    else:
        estado = "vacio"
    conn.execute(
        """
        UPDATE gestoria_import_lotes
        SET total_documentos = ?,
            total_ok = ?,
            total_revisar = ?,
            total_duplicado = ?,
            total_error = ?,
            estado = ?,
            updated_at = datetime(?)
        WHERE id = ?
        """,
        (
            int(summary["total_documentos"] or 0),
            total_ok,
            total_revisar,
            total_duplicado,
            total_error,
            estado,
            now,
            lote_id,
        ),
    )
    row = conn.execute("SELECT * FROM gestoria_import_lotes WHERE id = ?", (lote_id,)).fetchone()
    return dict(row) if row else None


def upsert_gestoria_import_document(conn, lote_id, empresa_id, default_cliente_id, record, now):
    archivo_nombre = str(record.get("archivo_nombre") or record.get("archivo") or "").strip()
    if not archivo_nombre:
        raise ValueError("archivo_nombre requerido")
    existing = conn.execute(
        """
        SELECT id, factura_id, tercero_id, gestoria_doc_id, created_at
        FROM gestoria_import_documentos
        WHERE lote_id = ? AND archivo_nombre = ?
        LIMIT 1
        """,
        (lote_id, archivo_nombre),
    ).fetchone()
    document_id = existing["id"] if existing else os.urandom(16).hex()
    cliente_id = str(record.get("cliente_id") or default_cliente_id or "").strip() or None
    categoria = str(record.get("categoria_detectada") or record.get("categoria_excel") or "").strip()
    tipo = str(record.get("tipo_detectado") or record.get("tipo") or "compra").strip().lower() or "compra"
    estado = normalize_import_review_state(record.get("estado_revision"))
    motivos = normalize_import_reasons(record.get("motivos_revision"))
    cuenta_sugerida = str(record.get("cuenta_sugerida") or "").strip() or map_import_category_to_account(categoria)
    cuenta_tercero = str(record.get("cuenta_tercero_sugerida") or "").strip()
    numero = str(record.get("numero_detectado") or record.get("numero") or "").strip()
    fecha = str(record.get("fecha_detectada") or record.get("fecha") or "").strip()
    tercero = str(record.get("tercero_detectado") or record.get("tercero") or "").strip()
    nif = str(record.get("nif_detectado") or record.get("nif") or "").strip().upper()
    base = round(parse_money_value(record.get("base_detectada") if "base_detectada" in record else record.get("base_imponible")), 2)
    cuota_iva = round(parse_money_value(record.get("cuota_iva_detectada") if "cuota_iva_detectada" in record else record.get("cuota_iva")), 2)
    total = round(parse_money_value(record.get("total_detectado") if "total_detectado" in record else record.get("total")), 2)
    if total <= 0:
        total = round(parse_money_value(record.get("importe_agregado")), 2)
    confianza_categoria = parse_confidence_value(record.get("confianza_categoria"))
    confianza_extraccion = parse_confidence_value(record.get("confianza_extraccion"))
    if confianza_extraccion <= 0:
        confianza_extraccion = 1.0 if total > 0 else 0.0
    raw_text = str(record.get("raw_text") or record.get("descripcion") or "").strip()
    values = (
        document_id,
        lote_id,
        empresa_id,
        cliente_id,
        existing["factura_id"] if existing else None,
        existing["tercero_id"] if existing else None,
        existing["gestoria_doc_id"] if existing else None,
        archivo_nombre,
        str(record.get("archivo_hash") or "").strip() or None,
        str(record.get("doc_key") or "").strip() or None,
        numero or None,
        fecha or None,
        tercero or None,
        nif or None,
        base,
        cuota_iva,
        total,
        tipo,
        categoria or None,
        str(record.get("subcategoria_detectada") or record.get("subcategoria") or "").strip() or None,
        cuenta_sugerida or None,
        cuenta_tercero or None,
        confianza_categoria,
        confianza_extraccion,
        estado,
        motivos or None,
        str(record.get("regla_aplicada") or record.get("motivo_categoria") or "").strip() or None,
        str(record.get("ocr_metodo") or "").strip() or None,
        str(record.get("ocr_error") or "").strip() or None,
        raw_text or None,
        existing["created_at"] if existing else now,
        now,
    )
    if getattr(conn, "__crm_backend__", "") == "postgres":
        conn.execute(
            """
            INSERT INTO gestoria_import_documentos (
              id, lote_id, empresa_id, cliente_id, factura_id, tercero_id, gestoria_doc_id,
              archivo_nombre, archivo_hash, doc_key, numero_detectado, fecha_detectada,
              tercero_detectado, nif_detectado, base_detectada, cuota_iva_detectada,
              total_detectado, tipo_detectado, categoria_detectada, subcategoria_detectada,
              cuenta_sugerida, cuenta_tercero_sugerida, confianza_categoria, confianza_extraccion,
              estado_revision, motivos_revision, regla_aplicada, ocr_metodo, ocr_error, raw_text,
              created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            ON CONFLICT (id) DO UPDATE SET
              lote_id = EXCLUDED.lote_id,
              empresa_id = EXCLUDED.empresa_id,
              cliente_id = EXCLUDED.cliente_id,
              factura_id = EXCLUDED.factura_id,
              tercero_id = EXCLUDED.tercero_id,
              gestoria_doc_id = EXCLUDED.gestoria_doc_id,
              archivo_nombre = EXCLUDED.archivo_nombre,
              archivo_hash = EXCLUDED.archivo_hash,
              doc_key = EXCLUDED.doc_key,
              numero_detectado = EXCLUDED.numero_detectado,
              fecha_detectada = EXCLUDED.fecha_detectada,
              tercero_detectado = EXCLUDED.tercero_detectado,
              nif_detectado = EXCLUDED.nif_detectado,
              base_detectada = EXCLUDED.base_detectada,
              cuota_iva_detectada = EXCLUDED.cuota_iva_detectada,
              total_detectado = EXCLUDED.total_detectado,
              tipo_detectado = EXCLUDED.tipo_detectado,
              categoria_detectada = EXCLUDED.categoria_detectada,
              subcategoria_detectada = EXCLUDED.subcategoria_detectada,
              cuenta_sugerida = EXCLUDED.cuenta_sugerida,
              cuenta_tercero_sugerida = EXCLUDED.cuenta_tercero_sugerida,
              confianza_categoria = EXCLUDED.confianza_categoria,
              confianza_extraccion = EXCLUDED.confianza_extraccion,
              estado_revision = EXCLUDED.estado_revision,
              motivos_revision = EXCLUDED.motivos_revision,
              regla_aplicada = EXCLUDED.regla_aplicada,
              ocr_metodo = EXCLUDED.ocr_metodo,
              ocr_error = EXCLUDED.ocr_error,
              raw_text = EXCLUDED.raw_text,
              created_at = EXCLUDED.created_at,
              updated_at = EXCLUDED.updated_at
            """,
            values,
        )
    else:
        conn.execute(
            """
            INSERT OR REPLACE INTO gestoria_import_documentos (
              id, lote_id, empresa_id, cliente_id, factura_id, tercero_id, gestoria_doc_id,
              archivo_nombre, archivo_hash, doc_key, numero_detectado, fecha_detectada,
              tercero_detectado, nif_detectado, base_detectada, cuota_iva_detectada,
              total_detectado, tipo_detectado, categoria_detectada, subcategoria_detectada,
              cuenta_sugerida, cuenta_tercero_sugerida, confianza_categoria, confianza_extraccion,
              estado_revision, motivos_revision, regla_aplicada, ocr_metodo, ocr_error, raw_text,
              created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            values,
        )
    return document_id


def apply_gestoria_import_document(conn, document_row, now):
    if not isinstance(document_row, dict):
        document_row = dict(document_row)
    reasons = validate_import_document_for_apply(document_row)
    if reasons:
        raise ValueError(",".join(reasons))
    tipo = str(document_row["tipo_detectado"] or "compra").strip().lower() or "compra"
    numero = str(document_row["numero_detectado"] or "").strip()
    fecha = str(document_row["fecha_detectada"] or "").strip() or datetime.now().strftime("%Y-%m-%d")
    tercero_nombre = str(document_row["tercero_detectado"] or "").strip() or str(document_row["archivo_nombre"] or "").strip()
    tercero_nif = str(document_row["nif_detectado"] or "").strip().upper()
    categoria = str(document_row["categoria_detectada"] or "").strip()
    descripcion = describe_import_record(document_row)
    base = round(parse_money_value(document_row["base_detectada"]), 2)
    cuota_iva = round(parse_money_value(document_row["cuota_iva_detectada"]), 2)
    total = round(parse_money_value(document_row["total_detectado"]), 2)
    if total <= 0 and base > 0 and cuota_iva > 0:
        total = round(base + cuota_iva, 2)
    if base <= 0 and total > 0 and cuota_iva > 0:
        base = round(max(0.0, total - cuota_iva), 2)
    iva_pct = 0.0
    if base > 0 and cuota_iva > 0:
        iva_pct = round((cuota_iva / base) * 100.0, 2)
    third_type = "cliente" if tipo == "venta" else ("proveedor" if numero else "acreedor")
    tercero_id, counterpart_account = ensure_gestoria_tercero(
        conn,
        document_row["empresa_id"],
        tercero_nif,
        tercero_nombre,
        third_type,
        now,
    )
    if document_row["cuenta_tercero_sugerida"]:
        counterpart_account = str(document_row["cuenta_tercero_sugerida"]).strip() or counterpart_account
        conn.execute(
            """
            UPDATE gestoria_terceros
            SET cuenta_contable = COALESCE(NULLIF(?, ''), cuenta_contable),
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (counterpart_account, now, tercero_id),
        )
    concepto = descripcion
    if categoria and categoria not in normalize_lookup_text(concepto):
        concepto = f"{concepto} · {categoria}" if concepto else categoria
    parsed_factura = {
        "tipo": tipo,
        "numero": numero,
        "fecha": fecha,
        "nif": tercero_nif,
        "tercero": tercero_nombre,
        "base_imponible": base,
        "cuota_iva": cuota_iva,
        "cuota_irpf": 0.0,
        "total": total,
        "iva_pct": iva_pct,
        "descripcion": concepto,
        "raw_text": document_row["raw_text"] or "",
    }
    lines, total_debe, total_haber = build_invoice_asiento(parsed_factura, counterpart_account)
    forced_account = str(document_row["cuenta_sugerida"] or "").strip() or map_import_category_to_account(categoria)
    if forced_account:
        for item in lines:
            cuenta = str(item.get("cuenta") or "").strip()
            if tipo == "venta":
                if cuenta.startswith("7"):
                    item["cuenta"] = forced_account
            else:
                if cuenta.startswith("6"):
                    item["cuenta"] = forced_account
    factura_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO gestoria_facturas (
          id, empresa_id, cliente_id, tercero_id, tipo, numero, fecha_emision, descripcion,
          base_imponible, cuota_iva, cuota_irpf, total, iva_pct, estado_ocr, doc_key, raw_text,
          import_documento_id, origen_importacion, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            factura_id,
            document_row["empresa_id"],
            document_row["cliente_id"],
            tercero_id,
            tipo,
            numero or None,
            fecha,
            concepto,
            base,
            cuota_iva,
            0.0,
            total,
            iva_pct,
            "importado",
            document_row["doc_key"],
            document_row["raw_text"],
            document_row["id"],
            "gestoria_import",
            now,
            now,
        ),
    )
    asiento_id = os.urandom(16).hex()
    referencia = numero or factura_id
    conn.execute(
        """
        INSERT INTO gestoria_asientos (
          id, empresa_id, cliente_id, factura_id, fecha, concepto, diario, referencia,
          total_debe, total_haber, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            asiento_id,
            document_row["empresa_id"],
            document_row["cliente_id"],
            factura_id,
            fecha,
            concepto,
            "FACT",
            referencia,
            total_debe,
            total_haber,
            now,
            now,
        ),
    )
    for item in lines:
        conn.execute(
            """
            INSERT INTO gestoria_asiento_lineas (
              id, asiento_id, tercero_id, cuenta, descripcion, debe, haber,
              impuesto_tipo, impuesto_pct, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
            )
            """,
            (
                os.urandom(16).hex(),
                asiento_id,
                tercero_id,
                item.get("cuenta"),
                item.get("descripcion"),
                item.get("debe") or 0.0,
                item.get("haber") or 0.0,
                item.get("impuesto"),
                item.get("porcentaje"),
                now,
                now,
            ),
        )
    conn.execute(
        """
        INSERT INTO gestoria_contabilidad (
          id, empresa_id, cliente_id, cliente_ids_json, fecha, concepto, gestion, tipo, importe, notas, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            os.urandom(16).hex(),
            document_row["empresa_id"],
            document_row["cliente_id"],
            json.dumps([document_row["cliente_id"]], ensure_ascii=False) if document_row["cliente_id"] else None,
            fecha,
            concepto,
            "Contable",
            "Ingreso" if tipo == "venta" else "Gasto",
            total,
            f"Importador facturas · lote {document_row['lote_id']} · documento {document_row['id']} · asiento {asiento_id}",
            now,
            now,
        ),
    )
    conn.execute(
        """
        UPDATE gestoria_import_documentos
        SET factura_id = ?, tercero_id = ?, updated_at = datetime(?)
        WHERE id = ?
        """,
        (factura_id, tercero_id, now, document_row["id"]),
    )
    return {
        "factura_id": factura_id,
        "asiento_id": asiento_id,
        "tercero_id": tercero_id,
        "lineas": lines,
        "totales": {"debe": total_debe, "haber": total_haber},
    }


def apply_gestoria_import_lote(conn, lote_id, empresa_id, now, limit=None):
    sql = """
        SELECT *
        FROM gestoria_import_documentos
        WHERE lote_id = ?
          AND empresa_id = ?
          AND estado_revision = 'OK'
          AND factura_id IS NULL
        ORDER BY fecha_detectada ASC, created_at ASC
    """
    values = [lote_id, empresa_id]
    if limit:
        sql += " LIMIT ?"
        values.append(int(limit))
    rows = conn.execute(sql, values).fetchall()
    applied = []
    errors = []
    for row in rows:
        try:
            result = apply_gestoria_import_document(conn, row, now)
            applied.append({"documento_id": row["id"], **result})
            log_gestoria_import_event(
                conn,
                lote_id,
                "aplicado",
                now,
                documento_id=row["id"],
                factura_id=result["factura_id"],
                detalle="Documento aplicado a factura/asiento",
                payload={"archivo_nombre": row["archivo_nombre"], "factura_id": result["factura_id"], "asiento_id": result["asiento_id"]},
            )
        except Exception as exc:
            conn.execute(
                """
                UPDATE gestoria_import_documentos
                SET estado_revision = 'ERROR',
                    motivos_revision = COALESCE(NULLIF(TRIM(COALESCE(motivos_revision, '') || ',error_aplicacion'), ''), 'error_aplicacion'),
                    updated_at = datetime(?)
                WHERE id = ?
                """,
                (now, row["id"]),
            )
            errors.append({"documento_id": row["id"], "archivo_nombre": row["archivo_nombre"], "error": str(exc)})
            log_gestoria_import_event(
                conn,
                lote_id,
                "error_aplicacion",
                now,
                documento_id=row["id"],
                detalle=str(exc),
                payload={"archivo_nombre": row["archivo_nombre"]},
            )
    lote = refresh_gestoria_import_lote_totals(conn, lote_id, now)
    pending_ok = conn.execute(
        """
        SELECT COUNT(*) AS n
        FROM gestoria_import_documentos
        WHERE lote_id = ?
          AND empresa_id = ?
          AND estado_revision = 'OK'
          AND factura_id IS NULL
        """,
        (lote_id, empresa_id),
    ).fetchone()
    pending_ok_count = int((pending_ok["n"] if pending_ok else 0) or 0)
    if lote and pending_ok_count == 0 and int(lote.get("total_ok") or 0) > 0 and not errors:
        conn.execute(
            """
            UPDATE gestoria_import_lotes
            SET estado = 'aplicado',
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (now, lote_id),
        )
        lote = conn.execute("SELECT * FROM gestoria_import_lotes WHERE id = ?", (lote_id,)).fetchone()
        lote = dict(lote) if lote else None
    return {"applied": applied, "errors": errors, "lote": lote}

def process_seguros_ocr(payload, conn):
    pdf_bytes = decode_seguros_payload(payload)
    fast_mode = str(payload.get("fast_mode") or "").strip().lower() in ("1", "true", "yes", "on")
    tmp_path = None
    text = ""
    err_detail = ""
    method = ""
    source_hint = " ".join(
        [
            str(payload.get("filename") or ""),
            str(payload.get("s3_key") or ""),
            str(payload.get("source_hint") or ""),
        ]
    ).strip()
    hinted_company = detect_company_from_metadata(source_hint)
    required_keys = ("tomador", "poliza_numero", "compania", "fecha_efecto")
    ai_used = False
    ai_error = ""
    field_sources = {}
    candidate_fields = []
    def candidate_score(quality):
        if not isinstance(quality, dict):
            return 0
        required_valid = len(quality.get("required_valid") or [])
        required_filled = len(quality.get("required_filled") or [])
        confidence = float(quality.get("confidence") or 0)
        return required_valid * 100 + required_filled * 10 + int(confidence * 100)
    try:
        with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp_file:
            tmp_file.write(pdf_bytes)
            tmp_path = tmp_file.name
        text, err_detail, method = extract_pdf_text(tmp_path)
        if not text:
            raise RuntimeError(err_detail or "No se pudo extraer texto")
        fields = parse_poliza_text(text, source_hint=source_hint, hinted_company=hinted_company)
        candidate_fields.append(("pdf_text", normalize_extracted_fields(fields), 1.0))
        best_quality = compute_ocr_quality(fields, required_keys)
        if (not fast_mode) and (
            not any(str(value or "").strip() for value in fields.values()) or (
            not fields.get("poliza_numero")
            or not fields.get("tomador")
            or not fields.get("compania")
            or not fields.get("fecha_efecto")
            )
        ):
            ocr_text, ocr_err = ocr_pdf_all_pages(tmp_path, use_external=external_ocr_available())
            if ocr_text:
                ocr_fields = parse_poliza_text(ocr_text, source_hint=source_hint, hinted_company=hinted_company)
                candidate_fields.append(("ocr_all_pages", normalize_extracted_fields(ocr_fields), 1.05))
                ocr_quality = compute_ocr_quality(ocr_fields, required_keys)
                if candidate_score(ocr_quality) >= candidate_score(best_quality):
                    fields = ocr_fields
                    best_quality = ocr_quality
                    text = ocr_text
                    method = "vision" if external_ocr_available() else "tesseract"
            elif ocr_err and not err_detail:
                err_detail = ocr_err
        doc_text = ""
        missing_required = any(not fields.get(key) for key in required_keys)
        if (missing_required or candidate_score(best_quality) < 250) and docai_available() and not fast_mode:
            doc_text, doc_fields, doc_err = ocr_image_docai(pdf_bytes, "application/pdf")
            if doc_err and not err_detail:
                err_detail = doc_err
            doc_mapped = map_docai_poliza_fields(doc_fields)
            doc_parsed = parse_poliza_text(doc_text, source_hint=source_hint, hinted_company=hinted_company) if doc_text else {}
            candidate_fields.append(("docai_fields", normalize_extracted_fields(doc_mapped), 1.1))
            candidate_fields.append(("docai_parsed", normalize_extracted_fields(doc_parsed), 1.05))
            merged = dict(fields)
            for key, value in doc_mapped.items():
                if value and not merged.get(key):
                    merged[key] = value
            for key, value in doc_parsed.items():
                if value and not merged.get(key):
                    merged[key] = value
            merged_quality = compute_ocr_quality(merged, required_keys)
            if candidate_score(merged_quality) >= candidate_score(best_quality):
                fields = merged
                best_quality = merged_quality
            if doc_text and doc_text.strip():
                method = "docai"
        missing_required = any(not fields.get(key) for key in required_keys)
        need_zones = missing_required or (not fast_mode and candidate_score(best_quality) < 320)
        if need_zones:
            zones_text, zones_err = ocr_poliza_key_regions(tmp_path, use_external=external_ocr_available())
            if zones_text:
                zones_fields = parse_poliza_text(
                    zones_text,
                    source_hint=source_hint,
                    hinted_company=hinted_company,
                )
                candidate_fields.append(("zones", normalize_extracted_fields(zones_fields), 1.08))
                zones_merged = merge_fields(fields, zones_fields)
                zones_quality = compute_ocr_quality(zones_merged, required_keys)
                if candidate_score(zones_quality) >= candidate_score(best_quality):
                    fields = zones_merged
                    best_quality = zones_quality
                    if method:
                        method = f"{method}+zones"
                    else:
                        method = "zones"
            elif zones_err and not err_detail:
                err_detail = zones_err
        if hinted_company and not fields.get("compania"):
            fields["compania"] = hinted_company
        missing_required = any(not fields.get(key) for key in required_keys)
        if fast_mode and missing_required:
            # Último intento rápido sin OCR externo ni IA para evitar latencia alta.
            quick_text, quick_err = ocr_pdf_all_pages(tmp_path, use_external=False)
            if quick_text:
                quick_fields = parse_poliza_text(quick_text, source_hint=source_hint, hinted_company=hinted_company)
                quick_merged = merge_fields(fields, quick_fields)
                quick_quality = compute_ocr_quality(quick_merged, required_keys)
                if candidate_score(quick_quality) >= candidate_score(best_quality):
                    fields = quick_merged
                    best_quality = quick_quality
                    text = quick_text
                    method = "tesseract"
            elif quick_err and not err_detail:
                err_detail = quick_err
            missing_required = any(not fields.get(key) for key in required_keys)
        if (not fast_mode) and openai_available() and (missing_required or candidate_score(best_quality) < 320):
            ai_text = text or ""
            if doc_text and doc_text.strip():
                ai_text = f"{ai_text}\n\n{doc_text}".strip()
            if tmp_path and OCR_OPENAI_VISION_PAGES > 0:
                image_urls, vision_img_err = pdf_to_png_data_urls(
                    tmp_path,
                    max_pages=OCR_OPENAI_VISION_PAGES,
                    dpi=OCR_OPENAI_VISION_DPI,
                )
                if image_urls:
                    ai_vision_fields, ai_vision_err = call_openai_extract_seguro_vision(
                        image_urls,
                        text=ai_text,
                        source_hint=source_hint,
                        hinted_company=hinted_company,
                    )
                    if ai_vision_err:
                        ai_error = ai_vision_err
                    elif ai_vision_fields:
                        ai_used = True
                        candidate_fields.append(("openai_vision", normalize_extracted_fields(ai_vision_fields), 1.18))
                        merged = dict(fields)
                        for key, value in ai_vision_fields.items():
                            if value and not str(merged.get(key) or "").strip():
                                merged[key] = value
                        ai_quality = compute_ocr_quality(merged, required_keys)
                        if candidate_score(ai_quality) >= candidate_score(best_quality):
                            fields = merged
                            best_quality = ai_quality
                elif vision_img_err and not ai_error:
                    ai_error = vision_img_err
            if ai_text:
                ai_fields, ai_error_msg = call_openai_extract_seguro(
                    ai_text,
                    source_hint=source_hint,
                    hinted_company=hinted_company,
                )
                if ai_error_msg:
                    ai_error = ai_error_msg
                elif ai_fields:
                    ai_used = True
                    candidate_fields.append(("openai_text", normalize_extracted_fields(ai_fields), 0.98))
                    merged = dict(fields)
                    for key, value in ai_fields.items():
                        if value and not str(merged.get(key) or "").strip():
                            merged[key] = value
                    ai_quality = compute_ocr_quality(merged, required_keys)
                    if candidate_score(ai_quality) >= candidate_score(best_quality):
                        fields = merged
                        best_quality = ai_quality
        if (not fast_mode) and OCR_EXPERT_MODE and candidate_fields:
            expert_fields, expert_sources = blend_ocr_field_candidates(candidate_fields, required_keys)
            expert_quality = compute_ocr_quality(expert_fields, required_keys)
            if candidate_score(expert_quality) >= candidate_score(best_quality):
                fields = expert_fields
                best_quality = expert_quality
                field_sources = expert_sources
        # Post-fix final para AXA Profesional: evita valores del mediador y fechas truncadas.
        company_key = normalize_company_key(fields.get("compania") or hinted_company or "")
        text_upper = normalize_lookup_text(text)
        if ("AXA" in company_key) and ("AXA PROFESIONAL" in text_upper or "POLIZA DE SEGURO DE PROFESIONAL" in text_upper):
            def _norm_date_local(value):
                raw = str(value or "").strip()
                raw = raw.replace(".", "/").replace("-", "/")
                raw = re.sub(r"\s+", "", raw)
                return raw
            def _clean_name_local(value):
                raw = normalize_person_name(value or "")
                raw = re.sub(r"\s{2,}", " ", raw).strip(" ,;:-")
                return raw
            fields["ramo"] = "Profesional"
            pol = re.search(r"p[oó]liza\s*(?:n[º°o]|no\.?)\s*([0-9]{2})[- ]?([0-9]{7,})", text, re.IGNORECASE)
            if pol:
                fields["poliza_numero"] = f"{pol.group(1)}-{pol.group(2)}"
            dates = re.search(
                r"Datos\s+de\s+la\s+Poliza[\s\S]{0,900}?Fecha\s+efecto[\s\S]{0,200}?Fecha\s+vencimiento[\s\S]{0,220}?([0-9]{1,2}[./-][0-9]{1,2}[./-]20[0-9]{2})[\s\S]{0,120}?([0-9]{1,2}[./-][0-9]{1,2}[./-]20[0-9]{2})",
                text,
                re.IGNORECASE,
            )
            if dates:
                fields["fecha_efecto"] = _norm_date_local(dates.group(1))
                fields["fecha_vencimiento"] = _norm_date_local(dates.group(2))
            tom = re.search(r"Tomador\s+([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s]{6,}?)\s+Producto", text, re.IGNORECASE)
            if tom:
                fields["tomador"] = _clean_name_local(tom.group(1))
            if not fields.get("tomador") or len((fields.get("tomador") or "").split()) < 3:
                aseg = re.search(r"Nombre\s+del\s+asegurado\s*[\r\n]+\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s]{8,})", text, re.IGNORECASE)
                if aseg:
                    fields["tomador"] = _clean_name_local(aseg.group(1))
            if normalize_phone(fields.get("telefono") or "") == "900909014":
                fields["telefono"] = ""
            if "fincasvelazquez" in str(fields.get("email") or "").lower():
                fields["email"] = ""
            dir_norm = normalize_lookup_text(fields.get("direccion") or "")
            if "DOMICILIO SOCIAL" in dir_norm or "MEDIADOR" in dir_norm or "PALMA DE MALLORCA" in dir_norm:
                fields["direccion"] = ""
            if not fields.get("direccion"):
                addr = re.search(r"\b(CL\s+calle[^\n]{5,160}?\d{5}\s+[A-ZÁÉÍÓÚÑ]{3,})", text, re.IGNORECASE)
                if addr:
                    fields["direccion"] = re.sub(r"\s+", " ", addr.group(1)).strip()
        if ("ALLIANZ" in company_key) and ("CERTIFICADO DE SEGURO" in text_upper or "ALLIANZ R C PYME" in text_upper or "ALLIANZ R.C.PYME" in text_upper):
            if not fields.get("ramo"):
                fields["ramo"] = "Responsabilidad civil"
            allianz_general = re.search(
                r"Datos\s+Generales([\s\S]{0,2200}?)Datos\s+del\s+Asegurado",
                text,
                re.IGNORECASE,
            )
            allianz_scope = allianz_general.group(1) if allianz_general else text
            pol = re.search(r"P[oó]liza\s*n[º°o]\s*:\s*([0-9]{6,12})", text, re.IGNORECASE)
            if pol:
                fields["poliza_numero"] = pol.group(1).strip()
            dur = re.search(
                r"Duraci[oó]n\s*:\s*Desde[\s\S]{0,220}?del\s+(\d{1,2}/\d{1,2}/\d{4})[\s\S]{0,240}?hasta[\s\S]{0,220}?del\s+(\d{1,2}/\d{1,2}/\d{4})",
                text,
                re.IGNORECASE,
            )
            if dur:
                fields["fecha_efecto"] = dur.group(1)
                fields["fecha_vencimiento"] = dur.group(2)
            m = re.search(
                r"Datos\s+Generales\s*\n\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s,.'\-]{5,})\s*\n\s*Tomador\s+del\s+Seguro",
                text,
                re.IGNORECASE,
            )
            if m:
                name = normalize_person_name(m.group(1))
                name = re.sub(r"\s+", " ", name).strip(" ,;:-")
                if name and len(name.split()) >= 2:
                    fields["tomador"] = name
            # Si tomador quedó como una dirección, priorizar razón social del bloque general.
            tomador_norm = normalize_lookup_text(fields.get("tomador") or "")
            looks_address = (
                " CL " in f" {tomador_norm} "
                or " CALLE " in f" {tomador_norm} "
                or " AVDA " in f" {tomador_norm} "
                or " AVD " in f" {tomador_norm} "
            )
            if looks_address or not fields.get("tomador"):
                lines = [ln.strip() for ln in allianz_scope.splitlines() if ln.strip()]
                for idx, ln in enumerate(lines):
                    if re.search(r"Tomador\s+del", ln, re.IGNORECASE):
                        if idx > 0:
                            candidate = re.sub(r"\s+", " ", lines[idx - 1]).strip(" ,;:-")
                            if candidate and len(candidate.split()) >= 2:
                                fields["tomador"] = candidate
                        break
            nif_line = re.search(r"\bNIF\s*:\s*([A-Z0-9.\-]{8,16})", allianz_scope, re.IGNORECASE)
            if nif_line:
                fields["nif"] = re.sub(r"[^A-Z0-9]", "", nif_line.group(1).upper())
                fields["dni"] = fields["nif"]
            if fields.get("fecha_efecto") and fields.get("fecha_vencimiento") and fields["fecha_efecto"] == fields["fecha_vencimiento"]:
                fields["fecha_vencimiento"] = add_year_to_date(fields["fecha_efecto"])
        doc_type = classify_seguros_document(text)
        if doc_type == "otro" and doc_text:
            doc_type = classify_seguros_document(doc_text)
        ocr_quality = compute_ocr_quality(fields, required_keys)
        if field_sources:
            ocr_quality["field_sources"] = field_sources
        cliente_match = False
        cliente_id = None
        tomador = (fields.get("tomador") or "").strip()
        nif = (fields.get("nif") or fields.get("dni") or "").strip()
        if tomador or nif:
            if nif:
                nif_norm = re.sub(r"\s+", "", nif).upper()
                row = conn.execute(
                    "SELECT id FROM clientes WHERE REPLACE(UPPER(nif), ' ', '') = ?",
                    (nif_norm,),
                ).fetchone()
                if row:
                    cliente_id = row["id"]
                    cliente_match = True
            if not cliente_match and tomador:
                nombre_norm = re.sub(r"\s+", " ", tomador).strip().upper()
                row = conn.execute(
                    "SELECT id FROM clientes WHERE TRIM(UPPER(nombre)) = ?",
                    (nombre_norm,),
                ).fetchone()
                if row:
                    cliente_id = row["id"]
                    cliente_match = True
        return {
            "fields": fields,
            "text": text,
            "language": detect_ocr_lang(),
            "method": method,
            "doc_type": doc_type,
            "ocr_quality": ocr_quality,
            "cliente_id": cliente_id,
            "cliente_match": cliente_match,
            "ai_used": ai_used,
            "ai_error": ai_error,
        }
    finally:
        if tmp_path and os.path.exists(tmp_path):
            os.unlink(tmp_path)


def enqueue_ocr_job(db_path, kind, payload):
    job_id = os.urandom(16).hex()
    now = datetime.now(timezone.utc).isoformat()
    conn = open_sqlite_conn(db_path, with_row_factory=False)
    conn.execute(
        """
        INSERT INTO ocr_jobs (id, kind, status, payload_json, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (job_id, kind, "pending", json.dumps(payload), now, now),
    )
    conn.commit()
    conn.close()
    return job_id


def fetch_next_ocr_job(conn):
    cutoff = (datetime.now(timezone.utc) - timedelta(minutes=OCR_JOB_STALE_MINUTES)).isoformat()
    row = conn.execute(
        """
        SELECT id, kind, payload_json
        FROM ocr_jobs
        WHERE status = 'pending'
           OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
        ORDER BY created_at ASC
        LIMIT 1
        """,
        (cutoff,),
    ).fetchone()
    return row


def claim_next_ocr_job(conn):
    cutoff = (datetime.now(timezone.utc) - timedelta(minutes=OCR_JOB_STALE_MINUTES)).isoformat()
    now = datetime.now(timezone.utc).isoformat()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            """
            SELECT id, kind, payload_json
            FROM ocr_jobs
            WHERE status = 'pending'
               OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
            ORDER BY created_at ASC
            LIMIT 1
            """,
            (cutoff,),
        ).fetchone()
        if not row:
            conn.commit()
            return None
        updated = conn.execute(
            """
            UPDATE ocr_jobs
            SET status = 'processing', error = NULL, started_at = ?, updated_at = ?
            WHERE id = ?
              AND (
                status = 'pending'
                OR (status = 'processing' AND finished_at IS NULL AND started_at IS NOT NULL AND started_at < ?)
              )
            """,
            (now, now, row["id"], cutoff),
        ).rowcount
        conn.commit()
        if updated == 1:
            return row
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    return None


def update_ocr_job(conn, job_id, status, result=None, error=None):
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        """
        UPDATE ocr_jobs
        SET status = ?, result_json = COALESCE(?, result_json), error = ?, updated_at = ?,
            started_at = CASE
                WHEN ? = 'processing' THEN ?
                WHEN started_at IS NULL THEN ?
                ELSE started_at
            END,
            finished_at = CASE WHEN ? IN ('done','error') THEN ? ELSE finished_at END
        WHERE id = ?
        """,
        (
            status,
            json.dumps(result) if result is not None else None,
            error,
            now,
            status,
            now,
            now,
            status,
            now,
            job_id,
        ),
    )


def ocr_worker_loop(jobs_db_path, main_db_path):
    while True:
        jobs_conn = None
        job_id = None
        try:
            jobs_conn = open_sqlite_conn(jobs_db_path, with_row_factory=True)
            row = claim_next_ocr_job(jobs_conn)
            if not row:
                jobs_conn.close()
                time.sleep(0.6)
                continue
            job_id = row["id"]
            kind = row["kind"]
            payload = json.loads(row["payload_json"] or "{}")
            if kind == "seguros":
                main_conn = open_sqlite_conn(main_db_path, with_row_factory=True)
                try:
                    result = process_seguros_ocr(payload, main_conn)
                finally:
                    main_conn.close()
            else:
                raise RuntimeError("Tipo OCR no soportado")
            update_ocr_job(jobs_conn, job_id, "done", result=result, error=None)
            jobs_conn.commit()
            jobs_conn.close()
        except Exception as exc:
            try:
                if jobs_conn and job_id:
                    update_ocr_job(jobs_conn, job_id, "error", result=None, error=str(exc))
                    jobs_conn.commit()
            except Exception:
                pass
            try:
                if jobs_conn:
                    jobs_conn.close()
            except Exception:
                pass
            time.sleep(1.0)

def preprocess_image_for_ocr(src_path, out_path=None):
    tmp_base = tempfile.gettempdir()
    created = False
    if not out_path:
        tmp_file = tempfile.NamedTemporaryFile(suffix=".png", delete=False, dir=tmp_base)
        out_path = tmp_file.name
        tmp_file.close()
        created = True
    magick = shutil.which("magick") or shutil.which("convert")
    if magick and os.path.exists(magick):
        try:
            run_subprocess(
                [
                    magick,
                    src_path,
                    "-colorspace",
                    "Gray",
                    "-density",
                    "300",
                    "-resize",
                    "2500x2500",
                    "-deskew",
                    "40%",
                    "-sharpen",
                    "0x1",
                    "-contrast-stretch",
                    "1%x1%",
                    out_path,
                ],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE,
                text=True,
            )
            return out_path, created
        except Exception:
            pass
    try:
        run_subprocess(
            ["sips", "-s", "format", "png", src_path, "--out", out_path],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        try:
            run_subprocess(
                ["sips", "-Z", "2400", out_path, "--out", out_path],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        except Exception:
            pass
        return out_path, created
    except Exception:
        return src_path, created

def ocr_image_file(image_path):
    lang = detect_ocr_lang()
    tesseract_cmd = (
        shutil.which("tesseract")
        or "/opt/homebrew/bin/tesseract"
        or "/usr/local/bin/tesseract"
    )
    if not tesseract_cmd or not os.path.exists(tesseract_cmd):
        return "", "tesseract no encontrado en PATH"
    env = os.environ.copy()
    if os.path.isdir(TESSDATA_DIR):
        env["TESSDATA_PREFIX"] = TESSDATA_DIR
    tmp_base = tempfile.gettempdir()
    with tempfile.TemporaryDirectory(dir=tmp_base) as tmpdir:
        processed, created = preprocess_image_for_ocr(image_path)
        variants = [processed]
        magick = shutil.which("magick") or shutil.which("convert")
        if magick and os.path.exists(magick) and os.path.exists(processed):
            for idx, extra in enumerate(
                (
                    ["-threshold", "55%", "-despeckle"],
                    ["-adaptive-threshold", "15x15+10%", "-sharpen", "0x1.2"],
                )
            ):
                out_variant = os.path.join(tmpdir, f"ocr_var_{idx}.png")
                try:
                    run_subprocess(
                        [magick, processed, *extra, out_variant],
                        check=True,
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.PIPE,
                        text=True,
                    )
                    if os.path.exists(out_variant):
                        variants.append(out_variant)
                except Exception:
                    continue
        def run_tesseract(psm, source_path):
            result = run_subprocess(
                [
                    tesseract_cmd,
                    source_path,
                    "stdout",
                    "-l",
                    lang,
                    "--oem",
                    "1",
                    "--psm",
                    str(psm),
                    "-c",
                    "user_defined_dpi=300",
                    "-c",
                    "preserve_interword_spaces=1",
                ],
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=env,
                text=True,
            )
            return result.stdout or ""
        try:
            candidates = []
            for source_path in variants:
                for psm in OCR_TESSERACT_PSMS:
                    try:
                        candidates.append(run_tesseract(psm, source_path))
                    except subprocess.CalledProcessError:
                        continue
            if not candidates:
                return "", "tesseract: sin salida"
            best = max(candidates, key=lambda t: (len(t.strip()), sum(ch.isdigit() for ch in t)))
            return best, ""
        except subprocess.CalledProcessError as err:
            return "", f"tesseract: {err.stderr.strip()}"
        except Exception as err:
            return "", f"tesseract: {err}"
        finally:
            if created and processed and os.path.exists(processed):
                try:
                    os.unlink(processed)
                except Exception:
                    pass

def ocr_image_external(image_bytes):
    credentials_path = os.environ.get("GOOGLE_APPLICATION_CREDENTIALS")
    api_key = os.environ.get("GOOGLE_VISION_API_KEY") or os.environ.get("VISION_API_KEY")
    auth_header = None
    if credentials_path and os.path.exists(credentials_path):
        try:
            from google.oauth2 import service_account
            from google.auth.transport.requests import Request
        except Exception:
            return "", "OCR externo: instala google-auth y requests (pip install google-auth requests)"
        try:
            creds = service_account.Credentials.from_service_account_file(
                credentials_path,
                scopes=["https://www.googleapis.com/auth/cloud-platform"],
            )
            creds.refresh(Request())
            auth_header = f"Bearer {creds.token}"
        except Exception as err:
            return "", f"OCR externo: credenciales inválidas ({err})"
    elif not api_key:
        return "", "OCR externo no configurado"
    payload = {
        "requests": [
            {
                "image": {"content": base64.b64encode(image_bytes).decode("utf-8")},
                "features": [{"type": "DOCUMENT_TEXT_DETECTION"}],
            }
        ]
    }
    data = json.dumps(payload).encode("utf-8")
    if auth_header:
        url = "https://vision.googleapis.com/v1/images:annotate"
        headers = {"Content-Type": "application/json", "Authorization": auth_header}
    else:
        url = f"https://vision.googleapis.com/v1/images:annotate?key={api_key}"
        headers = {"Content-Type": "application/json"}
    req = urllib.request.Request(url, data=data, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            res = json.loads(resp.read().decode("utf-8"))
    except Exception as err:
        return "", f"OCR externo: {err}"
    try:
        text = res["responses"][0].get("fullTextAnnotation", {}).get("text", "")
        return text, ""
    except Exception:
        return "", "OCR externo: sin texto"

def external_ocr_available():
    credentials_path = os.environ.get("GOOGLE_APPLICATION_CREDENTIALS")
    api_key = os.environ.get("GOOGLE_VISION_API_KEY") or os.environ.get("VISION_API_KEY")
    return bool(api_key) or (credentials_path and os.path.exists(credentials_path))

def docai_available():
    processor_id = os.environ.get("DOCUMENTAI_PROCESSOR_ID") or os.environ.get("DOC_AI_PROCESSOR_ID")
    return bool(processor_id)

def normalize_field_label(value):
    value = value or ""
    value = value.lower()
    value = value.replace("á", "a").replace("é", "e").replace("í", "i").replace("ó", "o").replace("ú", "u")
    value = re.sub(r"[^a-z0-9 ]+", " ", value)
    value = re.sub(r"\s+", " ", value).strip()
    return value

def ocr_image_docai(image_bytes, mime_type):
    credentials_path = os.environ.get("GOOGLE_APPLICATION_CREDENTIALS")
    if not credentials_path or not os.path.exists(credentials_path):
        return "", {}, "Document AI: credenciales no configuradas"
    processor_id = os.environ.get("DOCUMENTAI_PROCESSOR_ID") or os.environ.get("DOC_AI_PROCESSOR_ID")
    if not processor_id:
        return "", {}, "Document AI: falta DOCUMENTAI_PROCESSOR_ID"
    location = os.environ.get("DOCUMENTAI_LOCATION") or "eu"
    try:
        from google.oauth2 import service_account
        from google.auth.transport.requests import Request
    except Exception:
        return "", {}, "Document AI: instala google-auth y requests"
    try:
        creds = service_account.Credentials.from_service_account_file(
            credentials_path,
            scopes=["https://www.googleapis.com/auth/cloud-platform"],
        )
        creds.refresh(Request())
        project_id = creds.project_id
    except Exception as err:
        return "", {}, f"Document AI: credenciales inválidas ({err})"
    if not project_id:
        return "", {}, "Document AI: project_id no encontrado"
    url = (
        f"https://{location}-documentai.googleapis.com/v1/projects/{project_id}"
        f"/locations/{location}/processors/{processor_id}:process"
    )
    payload = {
        "rawDocument": {
            "content": base64.b64encode(image_bytes).decode("utf-8"),
            "mimeType": mime_type or "image/jpeg",
        }
    }
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=data,
        headers={"Content-Type": "application/json", "Authorization": f"Bearer {creds.token}"},
    )
    try:
        with urllib.request.urlopen(req, timeout=25) as resp:
            res = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as err:
        try:
            detail = err.read().decode("utf-8")
        except Exception:
            detail = ""
        return "", {}, f"Document AI: {err} {detail}".strip()
    except Exception as err:
        return "", {}, f"Document AI: {err}"
    doc = res.get("document") or {}
    text = doc.get("text", "")
    fields = {}
    occurrences = {}
    for field in doc.get("pages", []) or []:
        for form_field in field.get("formFields", []) or []:
            name_text = ""
            value_text = ""
            name = form_field.get("fieldName", {}).get("textAnchor", {}).get("textSegments", [])
            for seg in name:
                try:
                    start = int(seg.get("startIndex", 0))
                    end = int(seg.get("endIndex", 0))
                    name_text += text[start:end]
                except Exception:
                    continue
            value = form_field.get("fieldValue", {}).get("textAnchor", {}).get("textSegments", [])
            for seg in value:
                try:
                    start = int(seg.get("startIndex", 0))
                    end = int(seg.get("endIndex", 0))
                    value_text += text[start:end]
                except Exception:
                    continue
            label = normalize_field_label(name_text)
            val = value_text.strip()
            if not label or not val:
                continue
            occurrences[label] = occurrences.get(label, 0) + 1
            key = label
            if label in (
                "nombre y apellidos",
                "nombre apellidos",
                "nombre",
                "dni",
                "nif",
                "telefono",
                "movil",
                "correo electronico",
                "email",
                "fecha nacimiento",
                "estado civil",
                "hijos",
                "profesion",
                "tipo contrato",
                "ingresos nomina",
                "ingresos",
                "nomina",
                "patrimonio alquiler",
                "prestamos",
            ):
                suffix = "1" if occurrences[label] == 1 else "2"
                key = f"{label} {suffix}"
            fields[key] = val
    return text, fields, ""

def map_docai_fields(doc_fields):
    doc_fields = doc_fields or {}
    def doc_pick(label, idx=1):
        key = f"{label} {idx}"
        return doc_fields.get(key, "") or doc_fields.get(label, "")
    fields = {}
    fields["cliente1_nombre"] = doc_pick("nombre y apellidos", 1) or doc_pick("nombre", 1)
    fields["cliente2_nombre"] = doc_pick("nombre y apellidos", 2) or doc_pick("nombre", 2)
    fields["cliente1_dni"] = doc_pick("dni", 1) or doc_pick("nif", 1)
    fields["cliente2_dni"] = doc_pick("dni", 2) or doc_pick("nif", 2)
    fields["cliente1_telefono"] = doc_pick("telefono", 1) or doc_pick("movil", 1)
    fields["cliente2_telefono"] = doc_pick("telefono", 2) or doc_pick("movil", 2)
    fields["cliente1_email"] = doc_pick("correo electronico", 1) or doc_pick("email", 1)
    fields["cliente2_email"] = doc_pick("correo electronico", 2) or doc_pick("email", 2)
    fields["cliente1_fecha_nacimiento"] = doc_pick("fecha nacimiento", 1)
    fields["cliente2_fecha_nacimiento"] = doc_pick("fecha nacimiento", 2)
    fields["cliente1_estado_civil"] = doc_pick("estado civil", 1)
    fields["cliente2_estado_civil"] = doc_pick("estado civil", 2)
    fields["cliente1_hijos"] = doc_pick("hijos", 1)
    fields["cliente2_hijos"] = doc_pick("hijos", 2)
    fields["cliente1_profesion"] = doc_pick("profesion", 1)
    fields["cliente2_profesion"] = doc_pick("profesion", 2)
    fields["cliente1_tipo_contrato"] = doc_pick("tipo contrato", 1)
    fields["cliente2_tipo_contrato"] = doc_pick("tipo contrato", 2)
    fields["cliente1_ingresos"] = doc_pick("ingresos nomina", 1) or doc_pick("ingresos", 1) or doc_pick("nomina", 1)
    fields["cliente2_ingresos"] = doc_pick("ingresos nomina", 2) or doc_pick("ingresos", 2) or doc_pick("nomina", 2)
    fields["cliente1_patrimonio"] = doc_pick("patrimonio alquiler", 1)
    fields["cliente2_patrimonio"] = doc_pick("patrimonio alquiler", 2)
    fields["cliente1_prestamos"] = doc_pick("prestamos", 1)
    fields["cliente2_prestamos"] = doc_pick("prestamos", 2)
    return fields

def map_docai_poliza_fields(doc_fields):
    doc_fields = doc_fields or {}
    def doc_pick(labels):
        for label in labels:
            key = normalize_field_label(label)
            if doc_fields.get(key):
                return doc_fields.get(key)
        return ""
    fields = {}
    fields["tomador"] = doc_pick([
        "tomador",
        "asegurado",
        "asegurado principal",
        "titular",
        "contratante",
        "nombre",
        "nombre y apellidos",
    ])
    fields["dni"] = doc_pick(["dni", "nif", "cif", "documento", "doc identificacion"])
    fields["telefono"] = doc_pick(["telefono", "móvil", "movil"])
    fields["email"] = doc_pick(["correo electronico", "email"])
    fields["direccion"] = doc_pick(["direccion", "domicilio"])
    fields["compania"] = doc_pick(["compania", "compañia", "aseguradora", "entidad aseguradora"])
    fields["ramo"] = doc_pick(["ramo", "modalidad", "producto"])
    fields["poliza_numero"] = doc_pick([
        "poliza",
        "numero poliza",
        "nº poliza",
        "número poliza",
        "certificado",
        "contrato",
    ])
    fields["fecha_efecto"] = doc_pick([
        "fecha efecto",
        "efecto",
        "inicio vigencia",
        "fecha inicio",
        "vigencia desde",
    ])
    fields["fecha_vencimiento"] = doc_pick([
        "fecha vencimiento",
        "vencimiento",
        "fin vigencia",
        "vigencia hasta",
    ])
    fields["prima_neta"] = doc_pick(["prima neta", "neta"])
    fields["prima_total"] = doc_pick(["prima total", "prima anual", "total recibo", "total"])
    return fields

def compute_ocr_quality(fields, required_keys=None):
    fields = fields or {}
    required_keys = required_keys or ()
    def is_valid_date(value):
        if not value:
            return False
        date_text = str(value).strip()
        if re.search(r"\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b", date_text):
            return True
        return bool(re.search(r"\b\d{4}-\d{2}-\d{2}\b", date_text))
    def is_valid_poliza(value):
        if not value:
            return False
        token = re.sub(r"[^A-Z0-9]", "", str(value).upper())
        return len(token) >= 6 and bool(re.search(r"\d", token))
    def is_valid_company(value):
        if not value:
            return False
        company = normalize_company_name(value)
        if len(company) < 3:
            return False
        lowered = company.lower()
        banned = ("compania", "compañia", "aseguradora", "seguro", "poliza", "póliza")
        return lowered not in banned
    def is_valid_nif_any(value):
        if not value:
            return False
        raw = normalize_nif(value)
        return bool(
            re.match(r"^[0-9]{8}[A-Z]$", raw)
            or re.match(r"^[XYZ][0-9]{7}[A-Z]$", raw)
            or re.match(r"^[ABCDEFGHJNPQRSUVW][0-9]{7}[0-9A-Z]$", raw)
        )
    def field_is_valid(key, value):
        if not str(value or "").strip():
            return False
        if key in ("fecha_efecto", "fecha_vencimiento", "fecha_nacimiento"):
            return is_valid_date(value)
        if key in ("poliza_numero",):
            return is_valid_poliza(value)
        if key in ("compania",):
            return is_valid_company(value)
        if key in ("dni", "nif"):
            return is_valid_nif_any(value)
        return True
    provided = [key for key, value in fields.items() if str(value or "").strip()]
    required_filled = [key for key in required_keys if str(fields.get(key) or "").strip()]
    required_valid = [key for key in required_keys if field_is_valid(key, fields.get(key))]
    invalid_required = [key for key in required_filled if key not in required_valid]
    total_required = len(required_keys)
    ratio = (len(required_valid) / total_required) if total_required else 0
    if total_required and ratio >= 0.75:
        calidad = "alta"
    elif total_required and ratio >= 0.45:
        calidad = "media"
    elif total_required:
        calidad = "baja"
    else:
        calidad = "desconocida"
    confidence = round((len(required_valid) / total_required), 3) if total_required else 0
    return {
        "calidad": calidad,
        "campos": provided,
        "required_filled": required_filled,
        "required_valid": required_valid,
        "required_invalid": invalid_required,
        "missing_required": [key for key in required_keys if key not in required_filled],
        "confidence": confidence,
    }


def is_valid_ocr_field(key, value):
    raw = str(value or "").strip()
    if not raw:
        return False
    if key in ("fecha_efecto", "fecha_vencimiento", "fecha_nacimiento"):
        return bool(
            re.search(r"\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b", raw)
            or re.search(r"\b\d{4}-\d{2}-\d{2}\b", raw)
        )
    if key == "poliza_numero":
        token = normalize_poliza_key(raw)
        if len(token) < 6 or not re.search(r"\d", token):
            return False
        if any(month in token for month in ("ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO", "SEPTIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE")):
            return False
        return True
    if key == "compania":
        company = normalize_company_name(raw)
        if len(company) < 3:
            return False
        return normalize_lookup_text(company) not in ("COMPANIA", "ASEGURADORA", "SEGURO", "POLIZA")
    if key in ("dni", "nif"):
        nif = normalize_nif(raw)
        return bool(
            re.match(r"^[0-9]{8}[A-Z]$", nif)
            or re.match(r"^[XYZ][0-9]{7}[A-Z]$", nif)
            or re.match(r"^[ABCDEFGHJNPQRSUVW][0-9]{7}[0-9A-Z]$", nif)
        )
    if key in ("telefono",):
        return bool(re.match(r"^[0-9]{9}$", normalize_phone(raw) or ""))
    if key in ("email",):
        return bool(re.match(r"^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$", raw.upper()))
    if key in ("prima_neta", "prima_total"):
        return bool(re.match(r"^\d{1,3}(?:\.\d{3})*,\d{2}$|^\d+,\d{2}$|^\d+(?:\.\d+)?$", raw))
    if key == "ramo":
        if len(raw) > 48:
            return False
        if "@" in raw or "€" in raw:
            return False
        if re.search(r"\d{2,}", raw):
            return False
        return True
    return True


def normalize_extracted_fields(fields):
    fields = dict(fields or {})
    if fields.get("tomador"):
        fields["tomador"] = normalize_person_name(fields["tomador"])
    if fields.get("dni"):
        fields["dni"] = normalize_nif(fields["dni"])
    if fields.get("nif"):
        fields["nif"] = normalize_nif(fields["nif"])
    if fields.get("telefono"):
        fields["telefono"] = normalize_phone(fields["telefono"])
    if fields.get("email"):
        fields["email"] = normalize_email(fields["email"])
    if fields.get("compania"):
        fields["compania"] = normalize_company_name(fields["compania"])
    if fields.get("fecha_efecto"):
        fields["fecha_efecto"] = str(fields["fecha_efecto"]).strip()
    if fields.get("fecha_vencimiento"):
        fields["fecha_vencimiento"] = str(fields["fecha_vencimiento"]).strip()
    if fields.get("fecha_nacimiento"):
        fields["fecha_nacimiento"] = str(fields["fecha_nacimiento"]).strip()
    if fields.get("poliza_numero"):
        fields["poliza_numero"] = normalize_poliza_key(fields["poliza_numero"])
    return fields


def blend_ocr_field_candidates(candidates, required_keys=None):
    required_keys = tuple(required_keys or ())
    keys = (
        "tomador",
        "dni",
        "nif",
        "telefono",
        "email",
        "direccion",
        "compania",
        "ramo",
        "poliza_numero",
        "fecha_efecto",
        "fecha_vencimiento",
        "prima_neta",
        "prima_total",
    )
    merged = {}
    debug = {}
    for key in keys:
        ranked = []
        for source_name, source_fields, source_weight in candidates:
            val = str((source_fields or {}).get(key) or "").strip()
            if not val:
                continue
            score = float(source_weight)
            valid = is_valid_ocr_field(key, val)
            if valid:
                score += 2.0
            else:
                score -= 1.25
            if key in required_keys:
                score += 0.8
            if key in ("tomador", "direccion") and len(val) >= 8:
                score += 0.2
            if key == "ramo":
                ramo_up = normalize_lookup_text(val)
                if ramo_up in ("HOGAR", "AUTO", "RESPONSABILIDAD CIVIL", "IMPAGO ALQUILER", "ALQUILER", "COMERCIO"):
                    score += 0.6
            if key == "compania":
                if normalize_company_key(val):
                    score += 0.4
            ranked.append((score, valid, source_name, val))
        if not ranked:
            continue
        ranked.sort(key=lambda item: (item[0], item[1], len(item[3])), reverse=True)
        best = ranked[0]
        merged[key] = best[3]
        debug[key] = {
            "source": best[2],
            "score": round(best[0], 3),
            "valid": bool(best[1]),
        }
    merged = normalize_extracted_fields(merged)
    return merged, debug

def compute_fin_quality(fields):
    required = (
        "inmobiliaria_asesor",
        "fecha",
        "asesor",
        "cliente1_nombre",
        "cliente1_dni",
        "cliente1_telefono",
        "cliente1_email",
        "cliente1_ingresos",
    )
    return compute_ocr_quality(fields, required)

def openai_available():
    return bool(os.environ.get("OPENAI_API_KEY"))

def normalize_openai_model_name(value, default="gpt-4o-mini"):
    raw = str(value or "").strip()
    if not raw:
        return default
    if re.match(r"^gpt[-_]", raw, re.IGNORECASE):
        return raw.replace("_", "-").lower()
    return raw

def extract_openai_output(resp):
    if not resp:
        return ""
    if isinstance(resp, dict):
        if resp.get("output_text"):
            return resp.get("output_text")
        output = resp.get("output") or []
        parts = []
        for item in output:
            content = item.get("content") or []
            for block in content:
                if block.get("type") == "output_text":
                    parts.append(block.get("text", ""))
        if parts:
            return "\n".join(parts).strip()
    return ""

def call_openai(prompt, model=None, temperature=0.2, max_tokens=600):
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return "", "OPENAI_API_KEY no configurada"
    model = normalize_openai_model_name(model or os.environ.get("OPENAI_MODEL"))
    payload = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": [
                    {
                        "type": "input_text",
                        "text": "Eres un copiloto interno para un CRM de seguros. Responde en español.",
                    }
                ],
            },
            {"role": "user", "content": [{"type": "input_text", "text": prompt}]},
        ],
        "temperature": temperature,
        "max_output_tokens": max_tokens,
        "store": False,
    }
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        "https://api.openai.com/v1/responses",
        data=data,
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            res = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as err:
        body = ""
        try:
            body = err.read().decode("utf-8", errors="replace")
        except Exception:
            body = ""
        details = body or str(err)
        return "", f"OpenAI error ({err.code}): {details}"
    except Exception as err:
        return "", f"OpenAI error: {err}"
    return extract_openai_output(res), ""


def call_openai_content(user_content, model=None, temperature=0.0, max_tokens=700):
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return "", "OPENAI_API_KEY no configurada"
    model = normalize_openai_model_name(model or os.environ.get("OPENAI_MODEL"))
