def normalize_legal_area(area):
    key = normalize_lookup_text(area or "").lower()
    if key in LEGAL_AREA_DEFINITIONS:
        return key
    return "inmobiliaria"


def get_legal_copilot_path(area="inmobiliaria"):
    area_key = normalize_legal_area(area)
    if area_key == "inmobiliaria":
        return LEGAL_COPILOT_PATH
    return LEGAL_AREA_DEFINITIONS[area_key]["path"]


def get_legal_copilot_payload(area="inmobiliaria"):
    area_key = normalize_legal_area(area)
    path = get_legal_copilot_path(area_key)
    cache = LEGAL_COPILOT_AREA_CACHE.setdefault(area_key, {"mtime": None, "payload": None})
    try:
        mtime = path.stat().st_mtime
    except FileNotFoundError:
        if area_key == "inmobiliaria":
            return {"version": 1, "area": area_key, "topics": LEGAL_COPILOT_TOPICS}
        return {"version": 1, "area": area_key, "topics": {}}
    except Exception:
        if area_key == "inmobiliaria":
            return {"version": 1, "area": area_key, "topics": LEGAL_COPILOT_TOPICS}
        return {"version": 1, "area": area_key, "topics": {}}
    cached_mtime = cache.get("mtime")
    cached_payload = cache.get("payload")
    if cached_payload and cached_mtime == mtime:
        return cached_payload
    try:
        with path.open("r", encoding="utf-8") as handle:
            payload = json.load(handle)
        if isinstance(payload, dict) and isinstance(payload.get("topics"), dict):
            payload.setdefault("version", 1)
            payload.setdefault("area", area_key)
            cache["mtime"] = mtime
            cache["payload"] = payload
            if area_key == "inmobiliaria":
                LEGAL_COPILOT_CACHE["mtime"] = mtime
                LEGAL_COPILOT_CACHE["topics"] = payload.get("topics")
            return payload
    except Exception:
        pass
    if area_key == "inmobiliaria":
        return {"version": 1, "area": area_key, "topics": LEGAL_COPILOT_TOPICS}
    return {"version": 1, "area": area_key, "topics": {}}


def get_legal_copilot_topics(area="inmobiliaria"):
    return get_legal_copilot_payload(area).get("topics") or {}


def get_legal_copilot_catalog():
    areas = []
    for area_key, meta in LEGAL_AREA_DEFINITIONS.items():
        topics = get_legal_copilot_topics(area_key)
        areas.append(
            {
                "key": area_key,
                "label": meta["label"],
                "default_topic": meta.get("default_topic"),
                "topics": [
                    {"key": topic_key, "title": str(topic_payload.get("title") or topic_key)}
                    for topic_key, topic_payload in topics.items()
                ],
            }
        )
    return {"areas": areas}


def get_legal_radar_sources_config():
    try:
        mtime = LEGAL_RADAR_SOURCES_PATH.stat().st_mtime
    except FileNotFoundError:
        return {"version": 1, "area": "inmobiliaria", "auto_sync_knowledge": True, "sources": []}
    except Exception:
        return {"version": 1, "area": "inmobiliaria", "auto_sync_knowledge": True, "sources": []}
    cached_mtime = LEGAL_RADAR_SOURCES_CACHE.get("mtime")
    cached_payload = LEGAL_RADAR_SOURCES_CACHE.get("payload")
    if cached_payload and cached_mtime == mtime:
        return cached_payload
    try:
        with LEGAL_RADAR_SOURCES_PATH.open("r", encoding="utf-8") as handle:
            payload = json.load(handle)
        if not isinstance(payload, dict):
            raise ValueError("invalid legal radar sources payload")
        payload.setdefault("version", 1)
        payload.setdefault("area", "inmobiliaria")
        payload.setdefault("auto_sync_knowledge", True)
        payload["sources"] = [item for item in list(payload.get("sources") or []) if isinstance(item, dict)]
        LEGAL_RADAR_SOURCES_CACHE["mtime"] = mtime
        LEGAL_RADAR_SOURCES_CACHE["payload"] = payload
        return payload
    except Exception:
        return {"version": 1, "area": "inmobiliaria", "auto_sync_knowledge": True, "sources": []}


def get_convenios_catalog():
    try:
        mtime = CONVENIOS_CATALOG_PATH.stat().st_mtime
    except FileNotFoundError:
        return {"version": 1, "convenios": []}
    except Exception:
        return {"version": 1, "convenios": []}
    cached_mtime = CONVENIOS_CATALOG_CACHE.get("mtime")
    cached_payload = CONVENIOS_CATALOG_CACHE.get("payload")
    if cached_payload and cached_mtime == mtime:
        return cached_payload
    try:
        with CONVENIOS_CATALOG_PATH.open("r", encoding="utf-8") as handle:
            payload = json.load(handle)
        if not isinstance(payload, dict):
            raise ValueError("invalid convenios payload")
        payload.setdefault("version", 1)
        payload["convenios"] = [item for item in list(payload.get("convenios") or []) if isinstance(item, dict)]
        CONVENIOS_CATALOG_CACHE["mtime"] = mtime
        CONVENIOS_CATALOG_CACHE["payload"] = payload
        return payload
    except Exception:
        return {"version": 1, "convenios": []}


def suggest_convenio_for_company(sector, cnae=""):
    sector_norm = normalize_lookup_text(sector or "").lower()
    cnae_norm = re.sub(r"[^0-9]", "", str(cnae or ""))
    catalog = get_convenios_catalog()
    for item in list(catalog.get("convenios") or []):
        keywords = [normalize_lookup_text(k).lower() for k in list(item.get("keywords") or []) if str(k or "").strip()]
        cnae_prefixes = [re.sub(r"[^0-9]", "", str(p or "")) for p in list(item.get("cnae_prefixes") or []) if str(p or "").strip()]
        if cnae_norm and cnae_prefixes:
            if any(cnae_norm.startswith(prefix) for prefix in cnae_prefixes if prefix):
                return item
        if sector_norm and keywords:
            if any(keyword and keyword in sector_norm for keyword in keywords):
                return item
    return None


def extract_legal_reference(text):
    value = str(text or "")
    patterns = [
        r"\bBOE-A-\d{4}-\d+\b",
        r"\bBOJA(?:\s*n[úu]m\.)?\s*\d+\b",
        r"\bLey\s+\d+/\d{4}\b",
        r"\bReal\s+Decreto(?:-ley)?\s+\d+/\d{4}\b",
        r"\bDecreto\s+\d+/\d{4}\b",
        r"\bOrden\s+[A-Z]{2,}\s*/\s*\d+/\d{4}\b",
    ]
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if match:
            return re.sub(r"\s+", " ", match.group(0)).strip()
    return ""


def extract_feed_text(element, names):
    for name in names:
        node = element.find(name)
        if node is not None and (node.text or "").strip():
            return node.text.strip()
    return ""


def parse_legal_feed_entries(raw_bytes, source_config):
    entries = []
    if not raw_bytes:
        return entries
    try:
        root = ET.fromstring(raw_bytes)
    except Exception:
        return entries
    source_key = str(source_config.get("key") or source_config.get("fuente") or "source").strip()
    rss_items = root.findall(".//item")
    if rss_items:
        for item in rss_items:
            title = extract_feed_text(item, ["title"])
            link = extract_feed_text(item, ["link"])
            published = extract_feed_text(item, ["pubDate", "dc:date"])
            summary = extract_feed_text(item, ["description"])
            guid = extract_feed_text(item, ["guid"])
            text_parts = [title, summary, guid, link]
            entries.append(
                {
                    "source_key": source_key,
                    "title": title,
                    "link": link,
                    "published": published,
                    "summary": summary,
                    "reference": extract_legal_reference(" ".join(part for part in text_parts if part)),
                    "raw_text": " ".join(part for part in text_parts if part),
                }
            )
        return entries
    atom_ns = {"atom": "http://www.w3.org/2005/Atom"}
    atom_items = root.findall(".//atom:entry", atom_ns)
    for item in atom_items:
        title = extract_feed_text(item, ["{http://www.w3.org/2005/Atom}title"])
        published = extract_feed_text(item, ["{http://www.w3.org/2005/Atom}updated", "{http://www.w3.org/2005/Atom}published"])
        summary = extract_feed_text(item, ["{http://www.w3.org/2005/Atom}summary", "{http://www.w3.org/2005/Atom}content"])
        link = ""
        for link_node in item.findall("{http://www.w3.org/2005/Atom}link"):
            href = str(link_node.attrib.get("href") or "").strip()
            if href:
                link = href
                break
        entry_id = extract_feed_text(item, ["{http://www.w3.org/2005/Atom}id"])
        text_parts = [title, summary, entry_id, link]
        entries.append(
            {
                "source_key": source_key,
                "title": title,
                "link": link,
                "published": published,
                "summary": summary,
                "reference": extract_legal_reference(" ".join(part for part in text_parts if part)),
                "raw_text": " ".join(part for part in text_parts if part),
            }
        )
    return entries


def classify_legal_feed_entry(area, source_config, entry):
    area_key = normalize_legal_area(area)
    operations_by_topic = {}
    haystack = normalize_lookup_text(
        " ".join(
            [
                str(entry.get("title") or ""),
                str(entry.get("summary") or ""),
                str(entry.get("reference") or ""),
                str(entry.get("link") or ""),
            ]
        )
    ).lower()
    if not haystack:
        return None
    best_match = None
    best_score = 0
    for rule in list(source_config.get("rules") or []):
        if not isinstance(rule, dict):
            continue
        keywords = [normalize_lookup_text(item).lower() for item in list(rule.get("keywords") or []) if str(item or "").strip()]
        matched = [keyword for keyword in keywords if keyword and keyword in haystack]
        score = len(matched)
        if score <= 0:
            continue
        if score > best_score:
            best_score = score
            topic_key = str(rule.get("topic_key") or "").strip() or None
            operations = operations_by_topic.get(topic_key)
            if operations is None:
                operations = get_legal_topic_operations(area_key, topic_key)
                operations_by_topic[topic_key] = operations
            best_match = {
                "area": area_key,
                "source_key": str(source_config.get("key") or "").strip() or None,
                "fuente": str(source_config.get("fuente") or source_config.get("title") or "").strip() or None,
                "reference": str(entry.get("reference") or "").strip() or extract_legal_reference(entry.get("raw_text") or ""),
                "title": str(entry.get("title") or "").strip() or "Novedad legal detectada",
                "published": str(entry.get("published") or "").strip() or None,
                "impacto": str(rule.get("impacto") or source_config.get("impacto_default") or "Medio").strip() or "Medio",
                "topic_key": topic_key,
                "url": str(entry.get("link") or "").strip() or None,
                "summary": str(entry.get("summary") or "").strip() or None,
                "accion_recomendada": str(rule.get("accion_recomendada") or "").strip() or None,
                "affected_documents": list(rule.get("affected_documents") or operations.get("documents") or []),
                "affected_workflows": list(rule.get("affected_workflows") or operations.get("workflows") or []),
                "affected_clauses": list(rule.get("affected_clauses") or operations.get("clauses") or []),
                "impact_score": rule.get("impact_score") if rule.get("impact_score") not in (None, "") else operations.get("impact_score"),
                "matched_keywords": matched,
                "auto_detected": 1,
            }
    return best_match


def fetch_legal_feed_content(source_config, timeout=20):
    url = str(source_config.get("feed_url") or "").strip()
    if not url:
        raise ValueError("feed_url requerido")
    request = urllib.request.Request(url, headers={"User-Agent": "ModerniaLegalRadar/1.0"})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return response.read()


def upsert_legal_radar_item_from_detection(conn, detection, now):
    if not detection:
        return {"created": False, "updated": False, "id": None}
    area = str(detection.get("area") or "inmobiliaria").strip().lower() or "inmobiliaria"
    url = str(detection.get("url") or "").strip()
    reference = str(detection.get("reference") or "").strip()
    title = str(detection.get("title") or "").strip()
    row = None
    if url:
        row = conn.execute(
            "SELECT id FROM legal_radar_items WHERE area = ? AND url = ? LIMIT 1",
            (area, url),
        ).fetchone()
    if row is None and reference and title:
        row = conn.execute(
            "SELECT id FROM legal_radar_items WHERE area = ? AND referencia = ? AND titulo = ? LIMIT 1",
            (area, reference, title),
        ).fetchone()
    if row is None and title:
        row = conn.execute(
            "SELECT id FROM legal_radar_items WHERE area = ? AND titulo = ? AND COALESCE(fecha_publicacion,'') = COALESCE(?, '') LIMIT 1",
            (area, title, str(detection.get("published") or "").strip()),
        ).fetchone()
    matched_keywords = ", ".join(list(detection.get("matched_keywords") or [])) or None
    operations = get_legal_topic_operations(area, detection.get("topic_key"))
    affected_documents = json.dumps(list(detection.get("affected_documents") or operations.get("documents") or []), ensure_ascii=False)
    affected_workflows = json.dumps(list(detection.get("affected_workflows") or operations.get("workflows") or []), ensure_ascii=False)
    affected_clauses = json.dumps(list(detection.get("affected_clauses") or operations.get("clauses") or []), ensure_ascii=False)
    impact_score = detection.get("impact_score")
    if impact_score in (None, ""):
        impact_score = operations.get("impact_score") or None
    if row is not None:
        conn.execute(
            """
            UPDATE legal_radar_items
            SET fuente = COALESCE(?, fuente),
                referencia = COALESCE(?, referencia),
                fecha_publicacion = COALESCE(?, fecha_publicacion),
                impacto = COALESCE(?, impacto),
                topic_key = COALESCE(?, topic_key),
                url = COALESCE(?, url),
                resumen = COALESCE(?, resumen),
                accion_recomendada = COALESCE(?, accion_recomendada),
                affected_documents = COALESCE(?, affected_documents),
                affected_workflows = COALESCE(?, affected_workflows),
                affected_clauses = COALESCE(?, affected_clauses),
                impact_score = COALESCE(?, impact_score),
                source_key = COALESCE(?, source_key),
                matched_keywords = COALESCE(?, matched_keywords),
                auto_detected = CASE WHEN ? THEN 1 ELSE auto_detected END,
                updated_at = datetime(?)
            WHERE id = ?
            """,
            (
                detection.get("fuente"),
                reference or None,
                detection.get("published"),
                detection.get("impacto"),
                detection.get("topic_key"),
                url or None,
                detection.get("summary"),
                detection.get("accion_recomendada"),
                affected_documents,
                affected_workflows,
                affected_clauses,
                impact_score,
                detection.get("source_key"),
                matched_keywords,
                int(bool(detection.get("auto_detected"))),
                now,
                row["id"],
            ),
        )
        return {"created": False, "updated": True, "id": row["id"]}
    item_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO legal_radar_items (
          id, area, fuente, referencia, titulo, fecha_publicacion, estado, impacto,
          topic_key, url, resumen, accion_recomendada, affected_documents, affected_workflows,
          affected_clauses, impact_score, source_key, matched_keywords,
          auto_detected, created_at, updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, 'Pendiente', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime(?), datetime(?)
        )
        """,
        (
            item_id,
            area,
            detection.get("fuente"),
            reference or None,
            title or "Novedad legal detectada",
            detection.get("published"),
            detection.get("impacto"),
            detection.get("topic_key"),
            url or None,
            detection.get("summary"),
            detection.get("accion_recomendada"),
            affected_documents,
            affected_workflows,
            affected_clauses,
            impact_score,
            detection.get("source_key"),
            matched_keywords,
            int(bool(detection.get("auto_detected"))),
            now,
            now,
        ),
    )
    return {"created": True, "updated": False, "id": item_id}


def sync_legal_knowledge_updates(conn, area="inmobiliaria", now=None):
    now_value = now or datetime.now(timezone.utc).isoformat()
    area_value = normalize_legal_area(area)
    path = get_legal_copilot_path(area_value)
    payload = get_legal_copilot_payload(area_value)
    if not isinstance(payload, dict):
        payload = {"version": 1, "area": area_value, "topics": {}}
    payload["version"] = payload.get("version") or 1
    payload["area"] = payload.get("area") or area_value
    topics = payload.get("topics")
    if not isinstance(topics, dict):
        topics = json.loads(json.dumps(LEGAL_COPILOT_TOPICS if area_value == "inmobiliaria" else {}))
        payload["topics"] = topics
    meta = payload.setdefault("meta", {})
    rows = conn.execute(
        """
        SELECT id, fuente, referencia, titulo, fecha_publicacion, impacto, topic_key, url,
               resumen, accion_recomendada, affected_documents, affected_workflows,
               affected_clauses, impact_score, source_key, matched_keywords
        FROM legal_radar_items
        WHERE area = ?
          AND auto_detected = 1
          AND COALESCE(knowledge_synced_at, '') = ''
        ORDER BY COALESCE(NULLIF(fecha_publicacion, ''), created_at) DESC, updated_at DESC
        """,
        (area_value,),
    ).fetchall()
    synced = 0
    topic_counts = {}
    for row in rows:
        topic_key = str(row["topic_key"] or "").strip()
        if not topic_key or topic_key not in topics:
            continue
        topic = topics.get(topic_key)
        if not isinstance(topic, dict):
            continue
        recent_updates = [item for item in list(topic.get("recent_updates") or []) if isinstance(item, dict)]
        if any(str(item.get("radar_item_id") or "") == row["id"] for item in recent_updates):
            conn.execute(
                "UPDATE legal_radar_items SET knowledge_synced_at = datetime(?) WHERE id = ?",
                (now_value, row["id"]),
            )
            continue
        recent_updates.insert(
            0,
            {
                "radar_item_id": row["id"],
                "title": row["titulo"],
                "fuente": row["fuente"],
                "referencia": row["referencia"],
                "fecha_publicacion": row["fecha_publicacion"],
                "impacto": row["impacto"],
                "url": row["url"],
                "summary": row["resumen"],
                "accion_recomendada": row["accion_recomendada"],
                "affected_documents": json.loads(row["affected_documents"] or "[]") if str(row["affected_documents"] or "").strip() else [],
                "affected_workflows": json.loads(row["affected_workflows"] or "[]") if str(row["affected_workflows"] or "").strip() else [],
                "affected_clauses": json.loads(row["affected_clauses"] or "[]") if str(row["affected_clauses"] or "").strip() else [],
                "impact_score": row["impact_score"],
                "source_key": row["source_key"],
                "matched_keywords": [item.strip() for item in str(row["matched_keywords"] or "").split(",") if item.strip()],
                "synced_at": now_value,
            },
        )
        topic["recent_updates"] = recent_updates[:12]
        conn.execute(
            "UPDATE legal_radar_items SET knowledge_synced_at = datetime(?) WHERE id = ?",
            (now_value, row["id"]),
        )
        synced += 1
        topic_counts[topic_key] = topic_counts.get(topic_key, 0) + 1
    if synced:
        history = [item for item in list(meta.get("sync_history") or []) if isinstance(item, dict)]
        history.insert(0, {"synced_at": now_value, "area": area_value, "items": synced, "topics": topic_counts})
        meta["sync_history"] = history[:20]
        meta["last_auto_sync_at"] = now_value
        meta["last_auto_sync_summary"] = {"items": synced, "topics": topic_counts}
        with path.open("w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)
            handle.write("\n")
        LEGAL_COPILOT_AREA_CACHE.pop(area_value, None)
        if area_value == "inmobiliaria":
            LEGAL_COPILOT_CACHE["mtime"] = None
            LEGAL_COPILOT_CACHE["topics"] = None
    return {"synced": synced, "topics": topic_counts}


def scan_legal_radar_sources(conn, area="inmobiliaria", now=None, source_keys=None, *, sync_knowledge=True):
    area_value = normalize_legal_area(area)
    config = get_legal_radar_sources_config()
    now_value = now or datetime.now(timezone.utc).isoformat()
    target_keys = {str(item).strip() for item in list(source_keys or []) if str(item).strip()}
    created = 0
    updated = 0
    scanned = 0
    matched = 0
    errors = []
    for source in list(config.get("sources") or []):
        if not isinstance(source, dict):
            continue
        source_area = normalize_legal_area(source.get("area") or area_value)
        if source_area != area_value:
            continue
        source_key = str(source.get("key") or "").strip()
        if target_keys and source_key not in target_keys:
            continue
        if str(source.get("enabled", True)).strip().lower() in {"0", "false", "no", "off"}:
            continue
        scanned += 1
        try:
            raw = fetch_legal_feed_content(source)
            entries = parse_legal_feed_entries(raw, source)
            for entry in entries[: max(1, min(100, int(source.get("max_entries") or 30)) )]:
                detection = classify_legal_feed_entry(area_value, source, entry)
                if not detection:
                    continue
                matched += 1
                outcome = upsert_legal_radar_item_from_detection(conn, detection, now_value)
                created += 1 if outcome["created"] else 0
                updated += 1 if outcome["updated"] else 0
        except Exception as exc:
            errors.append({"source_key": source_key or None, "error": str(exc)})
    sync_summary = {"synced": 0, "topics": {}}
    if sync_knowledge and bool(config.get("auto_sync_knowledge", True)):
        sync_summary = sync_legal_knowledge_updates(conn, area=area_value, now=now_value)
    return {
        "scanned_sources": scanned,
        "matched_entries": matched,
        "created": created,
        "updated": updated,
        "errors": errors,
        "knowledge_sync": sync_summary,
    }


def normalize_dgt_reference(value):
    raw = str(value or "").upper().replace(" ", "")
    match = re.search(r"\b([A-Z]?\d{4}-\d{2})\b", raw)
    if not match:
        return ""
    ref = match.group(1)
    if ref[0].isdigit():
        ref = f"V{ref}"
    return ref


def build_dgt_consulta_url(reference):
    normalized = normalize_dgt_reference(reference)
    if not normalized:
        return ""
    return f"https://petete.tributos.hacienda.gob.es/consultas/?num_consulta={urllib.parse.quote(normalized)}"


def lookup_dgt_consulta(reference):
    normalized = normalize_dgt_reference(reference)
    if not normalized:
        return {"error": "Referencia DGT no válida"}
    url = build_dgt_consulta_url(normalized)
    payload = {
        "fuente": "DGT",
        "referencia": normalized,
        "url": url,
        "title": f"Consulta vinculante {normalized}",
        "summary": "Consulta tributaria oficial de la Dirección General de Tributos.",
    }
    try:
        request = urllib.request.Request(url, headers={"User-Agent": "ModerniaLegalRadar/1.0"})
        with urllib.request.urlopen(request, timeout=20) as response:
            html_text = response.read().decode("utf-8", errors="ignore")
        title_match = re.search(r"<title>(.*?)</title>", html_text, flags=re.IGNORECASE | re.DOTALL)
        if title_match:
            title_text = html.unescape(re.sub(r"\s+", " ", title_match.group(1))).strip()
            if title_text:
                payload["page_title"] = title_text
        snippet_match = re.search(r"<h1[^>]*>(.*?)</h1>", html_text, flags=re.IGNORECASE | re.DOTALL)
        if snippet_match:
            heading = html.unescape(re.sub(r"<[^>]+>", " ", snippet_match.group(1)))
            heading = re.sub(r"\s+", " ", heading).strip()
            if heading:
                payload["summary"] = heading
    except Exception as exc:
        payload["warning"] = str(exc)
    return payload


def resolve_legal_copilot_topic(area, topic, question):
    area_key = normalize_legal_area(area)
    topics = get_legal_copilot_topics(area_key)
    topic_key = str(topic or "").strip()
    if topic_key in topics:
        return topic_key, topics[topic_key]
    haystack = normalize_lookup_text(question or "").lower()
    best_key = None
    best_score = 0.0
    for candidate, payload in topics.items():
        keywords = [normalize_lookup_text(item).lower() for item in list(payload.get("keywords") or []) if str(item or "").strip()]
        if not keywords and area_key == "inmobiliaria":
            fallback_map = {
                "encargo_venta": ["encargo venta", "exclusiva venta"],
                "encargo_alquiler": ["encargo alquiler"],
                "propuesta_compra": ["propuesta compra", "promesa compra"],
                "propuesta_alquiler": ["propuesta alquiler"],
                "reserva_arras": ["arras", "reserva"],
                "contrato_privado_compraventa": ["contrato privado compraventa", "compraventa"],
                "contrato_privado_arrendamiento": ["contrato privado arrendamiento", "arrendamiento"],
                "consumo_andalucia": ["consumo", "andalucia"],
                "visitas": ["visita", "hoja de visita"],
            }
            keywords = fallback_map.get(candidate, [])
        score = 0.0
        for keyword in keywords:
            if not keyword:
                continue
            if keyword in haystack:
                score += 4.0 + (0.25 * len(keyword.split()))
                continue
            tokens = [token for token in keyword.split() if len(token) >= 4]
            if not tokens:
                continue
            matched_tokens = sum(1 for token in tokens if token in haystack)
            if not matched_tokens:
                continue
            coverage = matched_tokens / len(tokens)
            score += matched_tokens * coverage
        if score > best_score:
            best_key = candidate
            best_score = score
    if best_key:
        return best_key, topics.get(best_key)
    fallback_key = LEGAL_AREA_DEFINITIONS.get(area_key, {}).get("default_topic")
    if fallback_key not in topics:
        fallback_key = next(iter(topics.keys()), None)
    if not fallback_key:
        return None, None
    return fallback_key, topics.get(fallback_key)


def fetch_legal_radar_items(conn, area="inmobiliaria", limit=100):
    try:
        limit_value = max(1, min(500, int(limit)))
    except Exception:
        limit_value = 100
    rows = conn.execute(
        """
        SELECT id, area, fuente, referencia, titulo, fecha_publicacion, estado, impacto,
               topic_key, url, resumen, accion_recomendada, affected_documents, affected_workflows,
               affected_clauses, impact_score, reviewed_at, reviewed_by,
               applied_at, source_key, matched_keywords, auto_detected, knowledge_synced_at,
               created_at, updated_at
        FROM legal_radar_items
        WHERE area = ?
        ORDER BY
          CASE LOWER(COALESCE(estado, ''))
            WHEN 'pendiente' THEN 0
            WHEN 'revisado' THEN 1
            WHEN 'aplicado' THEN 2
            ELSE 3
          END,
          COALESCE(NULLIF(fecha_publicacion, ''), created_at) DESC,
          updated_at DESC
        LIMIT ?
        """,
        (area, limit_value),
    ).fetchall()
    summary = {"pendiente": 0, "revisado": 0, "aplicado": 0, "auto_detected": 0, "knowledge_synced": 0}
    for row in rows:
        key = normalize_lookup_text(row["estado"] or "").lower()
        if key == "pendiente":
            summary["pendiente"] += 1
        elif key == "revisado":
            summary["revisado"] += 1
        elif key == "aplicado":
            summary["aplicado"] += 1
        if int(row["auto_detected"] or 0):
            summary["auto_detected"] += 1
        if str(row["knowledge_synced_at"] or "").strip():
            summary["knowledge_synced"] += 1
    parsed_rows = []
    for row in rows:
        item = dict(row)
        for key in ("affected_documents", "affected_workflows", "affected_clauses"):
            raw_value = str(item.get(key) or "").strip()
            if raw_value:
                try:
                    item[key] = json.loads(raw_value)
                except Exception:
                    item[key] = [part.strip() for part in raw_value.split(",") if part.strip()]
            else:
                item[key] = []
        parsed_rows.append(item)
    return {"rows": parsed_rows, "summary": summary}


