def parse_inmobiliaria_address_for_catastro(value):
    raw = re.sub(r"\s+", " ", str(value or "").strip())
    # En la UI a veces viene como "Dirección · Zona" o con separadores visuales.
    # Para Catastro sólo usamos la parte de la calle + número.
    raw = raw.split("·", 1)[0].strip()
    raw = raw.split("|", 1)[0].strip()
    if not raw:
        return {"sigla": "", "calle": "", "numero": "", "bloque": "", "escalera": "", "planta": "", "puerta": ""}
    normalized = raw.upper()
    normalized = normalized.replace("C/", "CALLE ")
    normalized = normalized.replace("AVDA.", "AVENIDA ")
    normalized = normalized.replace("AVDA", "AVENIDA ")
    normalized = normalized.replace("AV.", "AV ")
    normalized = normalized.replace("·", " ")
    normalized = normalized.replace(",", " ")
    normalized = normalized.replace("º", " ")
    normalized = normalized.replace("ª", " ")
    normalized = re.sub(r"\s+", " ", normalized).strip()
    tokens = normalized.split(" ")
    sigla = ""
    body = tokens
    if tokens:
        first = re.sub(r"[^A-Z]", "", tokens[0])
        sigla = CATRASTRO_STREET_TYPE_MAP.get(first, "")
        if sigla:
            body = tokens[1:]
    number_idx = next((idx for idx, token in enumerate(body) if re.fullmatch(r"\d+[A-Z]?", token or "")), -1)
    calle_tokens = body[:number_idx] if number_idx >= 0 else body
    numero = body[number_idx] if number_idx >= 0 else ""
    extras = body[number_idx + 1 :] if number_idx >= 0 else []

    def extract_extra(patterns):
        for idx, token in enumerate(extras):
            clean = re.sub(r"[^A-Z0-9]", "", token or "")
            if clean in patterns and idx + 1 < len(extras):
                return re.sub(r"[^A-Z0-9]", "", extras[idx + 1] or "")
        return ""

    return {
        "sigla": sigla or "CL",
        "calle": " ".join(calle_tokens).strip(),
        "numero": numero,
        "bloque": extract_extra({"BL", "BLOQUE"}),
        "escalera": extract_extra({"ESC", "ESCALERA"}),
        "planta": extract_extra({"PL", "PLANTA", "PISO"}),
        "puerta": extract_extra({"PTA", "PUERTA"}),
    }


def build_catastro_street_queries(parts):
    calle = str(parts.get("calle") or "").strip()
    sigla = str(parts.get("sigla") or "").strip()
    if not calle:
        return []
    queries = []
    seen = set()

    def add_query(tipo_via, nombre_via):
        key = (str(tipo_via or "").strip().upper(), str(nombre_via or "").strip().upper())
        if not key[1] or key in seen:
            return
        seen.add(key)
        queries.append({"TipoVia": key[0], "NombreVia": key[1]})

    add_query(sigla, calle)
    add_query("", calle)

    tokens = [token for token in calle.split(" ") if token]
    if len(tokens) >= 2:
        add_query("", " ".join(tokens[-2:]))
    if len(tokens) >= 3:
        add_query("", " ".join(tokens[-3:]))
    for token in tokens:
        if len(token) >= 5:
            add_query("", token)
    return queries


def _xml_local_name(tag):
    return str(tag or "").rsplit("}", 1)[-1].lower()


def extract_catastro_candidates_from_xml(xml_text, fallback_label=""):
    if not xml_text:
        return {"candidates": [], "messages": []}
    root = ET.fromstring(xml_text)
    pc1_values = []
    pc2_values = []
    labels = []
    messages = []
    for elem in root.iter():
        tag = _xml_local_name(elem.tag)
        text = " ".join(part.strip() for part in elem.itertext() if str(part).strip()).strip()
        if not text:
            continue
        if tag == "pc1":
            pc1_values.append(re.sub(r"\s+", "", text))
        elif tag == "pc2":
            pc2_values.append(re.sub(r"\s+", "", text))
        elif tag in {"ldt", "direccion", "dir"}:
            labels.append(text)
        elif tag in {"err", "lerr", "error", "des"}:
            lowered = text.lower()
            if "error" in lowered or "no existe" in lowered or "no encontrado" in lowered:
                messages.append(text)
    candidates = []
    seen = set()
    for index, pc1 in enumerate(pc1_values):
        pc2 = pc2_values[index] if index < len(pc2_values) else ""
        ref = re.sub(r"[^A-Z0-9]", "", f"{pc1}{pc2}".upper())
        if not ref or ref in seen:
            continue
        seen.add(ref)
        label = labels[index] if index < len(labels) else fallback_label
        candidates.append(
            {
                "referencia_catastral": ref,
                "label": label or fallback_label or ref,
            }
        )
    return {"candidates": candidates, "messages": messages}


def extract_catastro_streets_from_xml(xml_text):
    if not xml_text:
        return []
    root = ET.fromstring(xml_text)
    streets = []
    seen = set()
    for calle in root.iter():
        if _xml_local_name(calle.tag) != "calle":
            continue
        tv = ""
        nv = ""
        for child in calle.iter():
            tag = _xml_local_name(child.tag)
            text = " ".join(part.strip() for part in child.itertext() if str(part).strip()).strip()
            if tag == "tv" and text:
                tv = text
            elif tag == "nv" and text:
                nv = text
        key = (tv, nv)
        if not nv or key in seen:
            continue
        seen.add(key)
        streets.append({"tipo_via": tv, "nombre_via": nv})
    return streets


def extract_catastro_numbers_from_xml(xml_text, *, street_label=""):
    if not xml_text:
        return {"candidates": [], "messages": []}
    root = ET.fromstring(xml_text)
    messages = []
    candidates = []
    seen = set()
    for elem in root.iter():
        tag = _xml_local_name(elem.tag)
        text = " ".join(part.strip() for part in elem.itertext() if str(part).strip()).strip()
        if tag in {"err", "des"} and text:
            lowered = text.lower()
            if "numero" in lowered or "número" in lowered or "error" in lowered:
                messages.append(text)
    for nump in root.iter():
        if _xml_local_name(nump.tag) != "nump":
            continue
        pc1 = pc2 = pnp = plp = ""
        for child in nump.iter():
            tag = _xml_local_name(child.tag)
            text = " ".join(part.strip() for part in child.itertext() if str(part).strip()).strip()
            if tag == "pc1":
                pc1 = re.sub(r"\s+", "", text)
            elif tag == "pc2":
                pc2 = re.sub(r"\s+", "", text)
            elif tag == "pnp":
                pnp = re.sub(r"\s+", "", text)
            elif tag == "plp":
                plp = re.sub(r"\s+", "", text)
        ref = re.sub(r"[^A-Z0-9]", "", f"{pc1}{pc2}".upper())
        if not ref or ref in seen:
            continue
        seen.add(ref)
        suffix = f" {plp}" if plp else ""
        label = f"{street_label} {pnp}{suffix}".strip()
        candidates.append({"referencia_catastral": ref, "label": label})
    return {"candidates": candidates, "messages": messages}


def _fetch_catastro_xml(url, params):
    query = urllib.parse.urlencode(params)
    full_url = f"{url}?{query}"
    with urllib.request.urlopen(full_url, timeout=8) as response:
        xml_text = response.read().decode("utf-8", errors="ignore")
    return full_url, xml_text


def clean_catastro_reference(value):
    return re.sub(r"[^A-Z0-9]", "", str(value or "").upper())


def split_catastro_reference(value):
    clean = clean_catastro_reference(value)
    if len(clean) < 14:
        return "", "", clean
    return clean[:7], clean[7:14], clean


def _geocode_query_candidates(address, municipio="", provincia="", codigo_postal=""):
    base = str(address or "").strip()
    town = str(municipio or "").strip()
    region = str(provincia or "").strip()
    postal = normalize_postal_code(codigo_postal)
    if not base:
        return []
    first_line = base.split(",")[0].strip()
    simplified = re.sub(r"\b\d+\s+[A-Z]{1,2}\b$", "", first_line, flags=re.I).strip()
    simplified = re.sub(r"\b\d+\s+\d+\s*[A-Z]?\b$", lambda m: m.group(0).split()[0], simplified, flags=re.I).strip()
    parts_full = [base, town, region, postal, "España"]
    parts_simple = [simplified or first_line, town, region, postal, "España"]
    candidates = []
    for parts in (parts_full, parts_simple):
        query = ", ".join([part for part in parts if part])
        if query and query not in candidates:
            candidates.append(query)
    return candidates


GEOCODE_CACHE_MAX_AGE_DAYS = max(1, int(os.environ.get("APP_GEOCODE_CACHE_MAX_AGE_DAYS", "365")))


def _geocode_cache_key(query, municipio="", provincia="", codigo_postal=""):
    parts = [
        normalize_lookup_text(query or ""),
        normalize_lookup_text(municipio or ""),
        normalize_lookup_text(provincia or ""),
        normalize_postal_code(codigo_postal or ""),
    ]
    return "|".join(parts).strip("|")


def get_geocode_cache(conn, query, municipio="", provincia="", codigo_postal=""):
    if not conn:
        return None
    key = _geocode_cache_key(query, municipio=municipio, provincia=provincia, codigo_postal=codigo_postal)
    if not key:
        return None
    try:
        row = conn.execute(
            """
            SELECT lat, lon, display_name, provider, updated_at
            FROM geocode_cache
            WHERE cache_key = ?
            LIMIT 1
            """,
            (key,),
        ).fetchone()
    except Exception:
        return None
    if not row:
        return None
    updated_raw = str(row["updated_at"] or "").strip()
    if updated_raw:
        try:
            dt = datetime.fromisoformat(updated_raw.replace("Z", ""))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            age_days = (datetime.now(timezone.utc) - dt).days
            if age_days > GEOCODE_CACHE_MAX_AGE_DAYS:
                return None
        except Exception:
            pass
    try:
        lat = float(row["lat"])
        lon = float(row["lon"])
    except Exception:
        return None
    if not lat or not lon:
        return None
    return {
        "ok": True,
        "lat": lat,
        "lon": lon,
        "display_name": row["display_name"] or str(query or ""),
        "provider": (row["provider"] or "cache"),
        "cached": True,
    }


def upsert_geocode_cache(conn, query, municipio, provincia, codigo_postal, lat, lon, display_name, provider, now_iso):
    if not conn:
        return False
    key = _geocode_cache_key(query, municipio=municipio, provincia=provincia, codigo_postal=codigo_postal)
    if not key:
        return False
    try:
        conn.execute(
            """
            INSERT INTO geocode_cache (
              cache_key, query, municipio, provincia, codigo_postal, lat, lon, display_name, provider, created_at, updated_at
            ) VALUES (
              ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?
            )
            ON CONFLICT(cache_key) DO UPDATE SET
              lat = excluded.lat,
              lon = excluded.lon,
              display_name = excluded.display_name,
              provider = excluded.provider,
              updated_at = excluded.updated_at
            """,
            (
                key,
                str(query or "").strip(),
                str(municipio or "").strip(),
                str(provincia or "").strip(),
                normalize_postal_code(codigo_postal or ""),
                float(lat),
                float(lon),
                str(display_name or "").strip(),
                str(provider or "").strip(),
                now_iso,
                now_iso,
            ),
        )
        return True
    except Exception:
        return False


def _fetch_nominatim_query(query):
    params = urllib.parse.urlencode(
        {
            "format": "jsonv2",
            "limit": 1,
            "countrycodes": "es",
            "q": query,
        }
    )
    req = urllib.request.Request(
        f"https://nominatim.openstreetmap.org/search?{params}",
        headers={
            "User-Agent": "ModerniaERP/1.0 (contacto@grupomodernia.es)",
            "Accept-Language": "es",
        },
    )
    with urllib.request.urlopen(req, timeout=8) as response:
        return json.loads(response.read().decode("utf-8", errors="ignore"))


