def row_value(row, key, default=None):
    if row is None:
        return default
    if isinstance(row, dict):
        return row.get(key, default)
    try:
        return row[key]
    except Exception:
        try:
            return row[0]
        except Exception:
            return default


def get_db(db_path):
    if db_is_postgres_enabled():
        return open_postgres_conn(with_row_factory=True)
    return open_sqlite_conn(db_path, with_row_factory=True)


def open_sqlite_conn(db_path, with_row_factory=False):
    try:
        timeout_seconds = float(os.environ.get("APP_SQLITE_TIMEOUT_SECONDS") or "5")
    except Exception:
        timeout_seconds = 5.0
    conn = sqlite3.connect(db_path, timeout=max(1.0, timeout_seconds))
    if with_row_factory:
        conn.row_factory = sqlite3.Row
    # Reduce bloqueos en escenarios multi-hilo (web + OCR worker).
    try:
        conn.execute("PRAGMA journal_mode=WAL")
    except Exception:
        pass
    if SQLITE_FOREIGN_KEYS_ENABLED:
        try:
            conn.execute("PRAGMA foreign_keys=ON")
        except Exception:
            pass
    try:
        busy_ms = int(os.environ.get("APP_SQLITE_BUSY_TIMEOUT_MS") or "5000")
        conn.execute(f"PRAGMA busy_timeout={max(0, busy_ms)}")
    except Exception:
        pass
    try:
        conn.execute("PRAGMA synchronous=NORMAL")
    except Exception:
        pass
    return conn


def ensure_tables(db_path):
    if db_is_postgres_enabled():
        conn = open_postgres_conn(with_row_factory=False)
        # En Postgres, muchos "best-effort" (índices, backfills) están envueltos en try/except.
        # En Postgres un error deja la transacción en estado abortado hasta rollback, así que usamos autocommit
        # durante el bootstrap del esquema para no bloquear el arranque por errores no críticos.
        try:
            raw_conn = getattr(conn, "_conn", None)
            if raw_conn is not None:
                raw_conn.autocommit = True
        except Exception:
            pass
    else:
        conn = open_sqlite_conn(db_path, with_row_factory=False)
    apply_schema_file(conn, ROOT.parent / "schema.sql")
    ensure_column(conn, "empresas", "logo_url", "logo_url TEXT")
