def infer_workspace_doc_classification(nombre, tipo, servicio):
    text = normalize_lookup_text(" ".join(str(value or "") for value in (nombre, tipo, servicio)))
    if not text:
        return None
    if "FACTURA" in text:
        return "Factura"
    if "POLIZA" in text or "RECIBO" in text:
        return "Póliza"
    if "ESCRITURA" in text or "NOTA SIMPLE" in text:
        return "Escritura"
    if "DNI" in text or "NIF" in text or "PASAPORTE" in text:
        return "Identidad"
    if "MODELO" in text or "RENTA" in text or "IRPF" in text:
        return "Fiscal"
    if "NOMINA" in text or "CONTRATO" in text:
        return "Laboral"
    return None


def fetch_workspace_company_ids(conn, workspace_id):
    ws_id = str(workspace_id or "").strip()
    if not ws_id:
        return []
    rows = conn.execute(
        "SELECT empresa_id FROM workspace_empresas WHERE workspace_id = ?",
        (ws_id,),
    ).fetchall()
    empresa_ids = [str(row_value(row, "empresa_id") or row_value(row, 0) or "").strip() for row in rows]
    empresa_ids = [eid for eid in empresa_ids if eid]
    if empresa_ids:
        return empresa_ids
    if not WORKSPACE_AUTO_LINK_COMPANIES:
        return []
    # Backfill: si el workspace no tiene empresas asociadas, no podemos mostrar RRHH/operativa.
    # Creamos los links por defecto usando empresas activas existentes.
    try:
        all_rows = conn.execute(
            "SELECT id FROM empresas WHERE COALESCE(activo, 1) = 1 ORDER BY nombre",
        ).fetchall()
    except Exception:
        all_rows = []
    fallback = [str(row_value(row, "id") or row_value(row, 0) or "").strip() for row in (all_rows or [])]
    fallback = [eid for eid in fallback if eid]
    if not fallback:
        return []
    now = datetime.now(timezone.utc).isoformat()
    for eid in fallback:
        try:
            conn.execute(
                """
                INSERT OR IGNORE INTO workspace_empresas (
                  id, workspace_id, empresa_id, rol, created_at, updated_at
                ) VALUES (?, ?, ?, 'operativa', datetime(?), datetime(?))
                """,
                (os.urandom(16).hex(), ws_id, eid, now, now),
            )
        except Exception:
            pass
    try:
        conn.commit()
    except Exception:
        pass
    return fallback


def resolve_workspace_company_ids(conn, workspace_id, empresa_id=None):
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return []
    scoped_id = str(empresa_id or "").strip()
    if not scoped_id:
        return empresa_ids
    allowed_ids = {str(value) for value in empresa_ids if value}
    return [scoped_id] if scoped_id in allowed_ids else []


def fetch_workspace_clientes(conn, workspace_id, q="", limit=60):
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {"rows": []}
    placeholders = ",".join(["?"] * len(empresa_ids))
    where = [f"ce.empresa_id IN ({placeholders})"]
    values = list(empresa_ids)
    if q:
        where.append("(c.nombre LIKE ? OR c.nif LIKE ? OR c.telefono LIKE ? OR c.email LIKE ?)")
        values.extend([f"%{q}%"] * 4)
    rows = conn.execute(
        f"""
        SELECT
          c.id,
          c.nombre,
          COALESCE(c.nif, '') AS nif,
          COALESCE(c.telefono, '') AS telefono,
          COALESCE(c.email, '') AS email,
          GROUP_CONCAT(DISTINCT e.nombre) AS empresas,
          GROUP_CONCAT(DISTINCT ce.servicio) AS servicios
        FROM clientes c
        JOIN clientes_empresas ce ON ce.cliente_id = c.id
        LEFT JOIN empresas e ON e.id = ce.empresa_id
        WHERE {' AND '.join(where)}
        GROUP BY c.id
        ORDER BY c.nombre COLLATE NOCASE ASC
        LIMIT ?
        """,
        [*values, max(1, min(int(limit or 60), 150))],
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}


def fetch_workspace_cliente_360(conn, workspace_id, cliente_id):
    empresa_ids = fetch_workspace_company_ids(conn, workspace_id)
    if not empresa_ids:
        return {"error": "Tenant sin empresas activas"}
    placeholders = ",".join(["?"] * len(empresa_ids))
    allowed = conn.execute(
        f"""
        SELECT 1
        FROM clientes_empresas
        WHERE cliente_id = ?
          AND empresa_id IN ({placeholders})
        LIMIT 1
        """,
        [cliente_id, *empresa_ids],
    ).fetchone()
    if not allowed:
        return {"error": "Cliente no disponible en este tenant"}

    payload = build_cliente_ficha_payload(conn, cliente_id)
    if not payload:
        return {"error": "Cliente no encontrado"}

    empresa_set = {str(item) for item in empresa_ids if item}
    empresas = [
        row for row in (payload.get("empresas") or [])
        if str(row.get("empresa_id") or "") in empresa_set
    ]

    servicios_activos = []
    for row in empresas:
        service_key = normalize_service_key(row.get("servicio"))
        if service_key == "hipotecas":
            service_key = "financiaciones"
        if service_key and row.get("is_active") and service_key not in servicios_activos:
            servicios_activos.append(service_key)
    allowed_service_keys = set(servicios_activos)

    docs_all = []
    docs_by_service = {"seguros": [], "gestoria": [], "financiaciones": [], "inmobiliaria": [], "otros": []}
    for row in payload.get("documentacion", {}).get("all", []):
        row_empresa_id = str(row.get("empresa_id") or "")
        service_key = normalize_service_key(row.get("referencia_tipo") or row.get("tipo"))
        if row_empresa_id and row_empresa_id not in empresa_set:
            continue
        if row_empresa_id or service_key in allowed_service_keys:
            docs_all.append(row)
            docs_by_service[service_key if service_key in docs_by_service else "otros"].append(row)

    facturas = [
        row for row in (payload.get("facturas") or [])
        if str(row.get("empresa_id") or "") in empresa_set
    ]
    gestoria_trabajos = [
        row for row in (payload.get("servicios", {}).get("gestoria_trabajos") or [])
        if str(row.get("empresa_id") or "") in empresa_set
    ]
    acciones = [
        row for row in (payload.get("servicios", {}).get("acciones") or [])
        if str(row.get("empresa_id") or "") in empresa_set
    ]
    seguros_rows = [
        row for row in (payload.get("servicios", {}).get("seguros") or [])
        if not row.get("empresa_id") or str(row.get("empresa_id") or "") in empresa_set
    ]

    historico = []
    for row in payload.get("historico") or []:
        service_key = normalize_service_key(row.get("servicio"))
        if service_key == "hipotecas":
            service_key = "financiaciones"
        if service_key in allowed_service_keys:
            historico.append(row)

    pendientes_trabajos = sum(
        1 for row in gestoria_trabajos
        if "FINAL" not in normalize_lookup_text(row.get("estado"))
        and "CANCEL" not in normalize_lookup_text(row.get("estado"))
    )
    pendientes_acciones = sum(
        1 for row in acciones
        if all(token not in normalize_lookup_text(row.get("estado")) for token in ("HECHO", "FINAL", "CANCEL"))
    )
    today = datetime.now(timezone.utc).date()
    citas_programadas = [
        row for row in acciones
        if parse_iso_date(row.get("fecha")) and parse_iso_date(row.get("fecha")) >= today
    ]
    primas_total = sum(parse_money_value(row.get("prima_total")) for row in seguros_rows)
    realizado = sum(
        parse_money_value(row.get("importe"))
        for row in gestoria_trabajos
        if "FINAL" in normalize_lookup_text(row.get("estado"))
    )
    cobrado = sum(
        parse_money_value(row.get("importe_asignado") if row.get("importe_asignado") not in (None, "") else row.get("importe"))
        for row in facturas
        if normalize_lookup_text(row.get("tipo")) != "GASTO"
    )
    rentabilidad = cobrado - realizado

    return {
        "cliente": payload.get("cliente") or {},
        "empresas": empresas,
        "relaciones": payload.get("relaciones") or [],
        "servicios_activos": servicios_activos,
        "documentacion": {
            "all": docs_all,
            "by_service": docs_by_service,
        },
        "docs_summary": {
            "total": len(docs_all),
            "gestoria": len(docs_by_service["gestoria"]),
            "seguros": len(docs_by_service["seguros"]),
            "financiaciones": len(docs_by_service["financiaciones"]),
            "inmobiliaria": len(docs_by_service["inmobiliaria"]),
        },
        "servicios": {
            "seguros": seguros_rows,
            "gestoria_trabajos": gestoria_trabajos,
            "acciones": acciones,
        },
        "facturas": facturas,
        "historico": historico[:100],
        "dashboard": {
            "rentabilidad": {
                "realizado": realizado,
                "cobrado": cobrado,
                "margen": rentabilidad,
            },
            "primas_total": primas_total,
            "tareas_pendientes": pendientes_trabajos + pendientes_acciones,
            "citas_programadas": len(citas_programadas),
            "proxima_cita": min([row["fecha"] for row in citas_programadas if row.get("fecha")], default=""),
        },
    }


def fetch_workspace_gestoria_overview(conn, workspace_id, empresa_id=None):
    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not empresa_ids:
        return {
            "counts": {
                "total": 0,
                "activos": 0,
                "modelos_mes": 0,
                "rentas_pendientes_presentar": 0,
                "acciones_pendientes": 0,
                "presupuestos_estudio": 0,
            },
            "modelos_vencidos": [],
            "rentas_pendientes": [],
            "acciones_vencidas": [],
            "presupuestos_estudio": [],
        }
    placeholders = ",".join(["?"] * len(empresa_ids))
    service_filter = (
        "LOWER(ce.servicio) IN ('gestoria', 'gestoría', "
        "'administracion fincas', 'administración fincas')"
    )
    today = datetime.now().date()
    current_month = today.strftime("%Y-%m")

    total = conn.execute(
        f"""
        SELECT COUNT(DISTINCT c.id) AS total
        FROM clientes c
        JOIN clientes_empresas ce ON ce.cliente_id = c.id
        WHERE ce.empresa_id IN ({placeholders})
          AND {service_filter}
        """,
        empresa_ids,
    ).fetchone()
    active_rows = conn.execute(
        f"""
        SELECT DISTINCT c.id AS cliente_id, ce.estado
        FROM clientes c
        JOIN clientes_empresas ce ON ce.cliente_id = c.id
        WHERE ce.empresa_id IN ({placeholders})
          AND {service_filter}
        """,
        empresa_ids,
    ).fetchall()
    active_ids = {row["cliente_id"] for row in active_rows if is_gestoria_dashboard_active_state(row["estado"])}
    modelos_mes = conn.execute(
        f"""
        SELECT COUNT(DISTINCT m.id) AS total
        FROM gestoria_modelos m
        JOIN clientes_empresas ce ON ce.cliente_id = m.cliente_id
        WHERE ce.empresa_id IN ({placeholders})
          AND {service_filter}
          AND m.proxima_fecha IS NOT NULL
          AND strftime('%Y-%m', m.proxima_fecha) = ?
        """,
        [*empresa_ids, current_month],
    ).fetchone()
    modelos_vencidos = conn.execute(
        f"""
        SELECT DISTINCT c.nombre AS cliente, m.modelo, m.proxima_fecha, m.estado
        FROM gestoria_modelos m
        JOIN clientes c ON c.id = m.cliente_id
        JOIN clientes_empresas ce ON ce.cliente_id = c.id
        WHERE ce.empresa_id IN ({placeholders})
          AND {service_filter}
          AND m.proxima_fecha IS NOT NULL
          AND date(m.proxima_fecha) < date(?)
          AND (m.estado IS NULL OR LOWER(m.estado) != 'presentado')
        ORDER BY m.proxima_fecha ASC
        LIMIT 12
        """,
        [*empresa_ids, today.isoformat()],
    ).fetchall()
    acciones_pendientes = conn.execute(
        f"""
        SELECT COUNT(*) AS total
        FROM acciones a
        WHERE a.empresa_id IN ({placeholders})
          AND LOWER(a.servicio) = 'gestoria'
          AND (a.estado IS NULL OR LOWER(a.estado) != 'hecho')
          AND a.fecha IS NOT NULL
          AND date(a.fecha) >= date(?)
        """,
        [*empresa_ids, today.isoformat()],
    ).fetchone()
    acciones_vencidas = conn.execute(
        f"""
        SELECT a.fecha, a.hora, COALESCE(c.nombre, a.cliente_nombre) AS cliente, a.tipo, a.estado
        FROM acciones a
        LEFT JOIN clientes c ON c.id = a.cliente_id
        WHERE a.empresa_id IN ({placeholders})
          AND LOWER(a.servicio) = 'gestoria'
          AND a.fecha IS NOT NULL
          AND date(a.fecha) < date(?)
          AND (a.estado IS NULL OR LOWER(a.estado) != 'hecho')
        ORDER BY a.fecha ASC, a.hora ASC
        LIMIT 12
        """,
        [*empresa_ids, today.isoformat()],
    ).fetchall()
    presupuestos_estudio = conn.execute(
        f"""
        SELECT p.fecha, p.fecha_seguimiento, p.titulo, p.motivo_estado, COALESCE(c.nombre, '') AS cliente
        FROM workspace_presupuestos p
        LEFT JOIN clientes c ON c.id = p.cliente_id
        WHERE p.workspace_id = ?
          AND p.empresa_id IN ({placeholders})
          AND LOWER(COALESCE(p.servicio, '')) IN ('gestoria', 'administracion fincas', 'fincas')
          AND LOWER(COALESCE(p.estado, '')) = 'estudio'
        ORDER BY COALESCE(p.fecha_seguimiento, p.fecha, p.updated_at) ASC
        LIMIT 12
        """,
        [workspace_id, *empresa_ids],
    ).fetchall()

    renta_index = {}
    for empresa_id in empresa_ids:
        for row in collect_gestoria_renta_card_items(conn, empresa_id, q="", estado="", limit=500):
            cliente_id = str(row.get("cliente_id") or "")
            latest = row.get("renta_latest") or {}
            current = renta_index.get(cliente_id)
            current_entry = current.get("renta_latest") if current else {}
            current_ex = int(current_entry.get("ejercicio") or 0) if current_entry else 0
            next_ex = int(latest.get("ejercicio") or 0) if latest else 0
            if not current or next_ex >= current_ex:
                renta_index[cliente_id] = row
    rentas_borrador = [
        row for row in renta_index.values()
        if normalize_renta_presentacion_status((row.get("renta_latest") or {}).get("estado_presentacion")) == "Borrador"
    ]

    return {
        "counts": {
            "total": total["total"] if total else 0,
            "activos": len(active_ids),
            "modelos_mes": modelos_mes["total"] if modelos_mes else 0,
            "rentas_pendientes_presentar": len(rentas_borrador),
            "acciones_pendientes": acciones_pendientes["total"] if acciones_pendientes else 0,
            "presupuestos_estudio": len(presupuestos_estudio),
        },
        "modelos_vencidos": [dict(r) for r in modelos_vencidos],
        "rentas_pendientes": [
            {
                "cliente": row.get("nombre"),
                "ejercicio": (row.get("renta_latest") or {}).get("ejercicio") or "",
                "nif": row.get("nif") or "",
                "estado_presentacion": (row.get("renta_latest") or {}).get("estado_presentacion") or "Borrador",
            }
            for row in rentas_borrador[:12]
        ],
        "acciones_vencidas": [dict(r) for r in acciones_vencidas],
        "presupuestos_estudio": [dict(r) for r in presupuestos_estudio],
    }


def fetch_workspace_seguros_overview(conn, workspace_id, empresa_id=None):
    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not empresa_ids:
        return {
            "counts": {
                "total": 0,
                "en_vigor": 0,
                "presupuesto": 0,
                "renovaciones_30d": 0,
                "prima_total": 0,
                "alertas_abiertas": 0,
            },
            "renovaciones_proximas": [],
            "alertas_comerciales": [],
            "top_companias": [],
            "top_ramos": [],
        }
    placeholders = ",".join(["?"] * len(empresa_ids))
    bucket_expr = seguro_estado_bucket_expr("s")
    fecha_efecto_expr = seguro_date_sql("fecha_efecto", "s")
    fecha_venc_expr = (
        f"COALESCE({seguro_date_sql('fecha_vencimiento', 's')}, "
        f"CASE WHEN {fecha_efecto_expr} IS NOT NULL THEN DATE({fecha_efecto_expr}, '+1 year') ELSE NULL END)"
    )
    compania_expr = "LOWER(TRIM(COALESCE(s.compania, '')))"
    today = datetime.now().date().isoformat()

    totals = conn.execute(
        f"""
        SELECT
          COUNT(*) AS total,
          SUM(CASE WHEN {bucket_expr} = 'en_vigor' THEN 1 ELSE 0 END) AS en_vigor,
          SUM(CASE WHEN {bucket_expr} = 'presupuesto' THEN 1 ELSE 0 END) AS presupuesto,
          SUM(CASE WHEN {fecha_venc_expr} IS NOT NULL
                    AND DATE({fecha_venc_expr}) BETWEEN DATE(?) AND DATE(?, '+30 day')
                    AND {bucket_expr} IN ('en_vigor', 'contratada')
              THEN 1 ELSE 0 END) AS renovaciones_30d,
          SUM(COALESCE(s.prima_total, s.prima_neta, 0)) AS prima_total
        FROM seguros s
        WHERE s.empresa_id IN ({placeholders})
          AND ({compania_expr} = '' OR {compania_expr} != 'sin seguro')
        """,
        [today, today, *empresa_ids],
    ).fetchone()

    renovaciones = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.tomador), ''), c.nombre, '') AS tomador,
          COALESCE(NULLIF(TRIM(s.compania), ''), 'Sin compañía') AS compania,
          COALESCE(NULLIF(TRIM(s.ramo), ''), 'Sin ramo') AS ramo,
          {fecha_venc_expr} AS fecha_vencimiento
        FROM seguros s
        LEFT JOIN clientes c ON c.id = s.cliente_id
        WHERE s.empresa_id IN ({placeholders})
          AND {fecha_venc_expr} IS NOT NULL
          AND DATE({fecha_venc_expr}) BETWEEN DATE(?) AND DATE(?, '+30 day')
          AND {bucket_expr} IN ('en_vigor', 'contratada')
          AND ({compania_expr} = '' OR {compania_expr} != 'sin seguro')
        ORDER BY DATE({fecha_venc_expr}) ASC, COALESCE(NULLIF(TRIM(s.tomador), ''), c.nombre, '') COLLATE NOCASE ASC
        LIMIT 12
        """,
        [*empresa_ids, today, today],
    ).fetchall()

    alertas = conn.execute(
        f"""
        SELECT
          a.fecha,
          a.hora,
          COALESCE(c.nombre, a.cliente_nombre, '') AS cliente,
          a.tipo,
          a.estado
        FROM acciones a
        LEFT JOIN clientes c ON c.id = a.cliente_id
        WHERE a.empresa_id IN ({placeholders})
          AND LOWER(TRIM(COALESCE(a.servicio, ''))) = 'seguros'
          AND (a.estado IS NULL OR LOWER(TRIM(a.estado)) NOT IN ('hecho', 'finalizado', 'cancelado'))
        ORDER BY
          CASE
            WHEN a.fecha IS NULL OR TRIM(a.fecha) = '' THEN 1
            WHEN DATE(a.fecha) < DATE(?) THEN 0
            ELSE 1
          END,
          DATE(COALESCE(a.fecha, '9999-12-31')) ASC,
          TIME(COALESCE(a.hora, '23:59')) ASC
        LIMIT 12
        """,
        [*empresa_ids, today],
    ).fetchall()

    companias_rows = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.compania), ''), 'Sin compañía') AS label,
          COUNT(*) AS total,
          SUM(COALESCE(s.prima_total, s.prima_neta, 0)) AS prima_total
        FROM seguros s
        WHERE s.empresa_id IN ({placeholders})
          AND ({compania_expr} = '' OR {compania_expr} != 'sin seguro')
        GROUP BY COALESCE(NULLIF(TRIM(s.compania), ''), 'Sin compañía')
        ORDER BY COUNT(*) DESC, label COLLATE NOCASE ASC
        LIMIT 8
        """,
        empresa_ids,
    ).fetchall()

    ramos_rows = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(s.ramo), ''), 'Sin ramo') AS label,
          COUNT(*) AS total,
          SUM(COALESCE(s.prima_total, s.prima_neta, 0)) AS prima_total
        FROM seguros s
        WHERE s.empresa_id IN ({placeholders})
          AND ({compania_expr} = '' OR {compania_expr} != 'sin seguro')
        GROUP BY COALESCE(NULLIF(TRIM(s.ramo), ''), 'Sin ramo')
        ORDER BY COUNT(*) DESC, label COLLATE NOCASE ASC
        LIMIT 8
        """,
        empresa_ids,
    ).fetchall()

    return {
        "counts": {
            "total": int((totals["total"] if totals else 0) or 0),
            "en_vigor": int((totals["en_vigor"] if totals else 0) or 0),
            "presupuesto": int((totals["presupuesto"] if totals else 0) or 0),
            "renovaciones_30d": int((totals["renovaciones_30d"] if totals else 0) or 0),
            "prima_total": round(parse_money_value(totals["prima_total"] if totals else 0), 2),
            "alertas_abiertas": len(alertas),
        },
        "renovaciones_proximas": [dict(r) for r in renovaciones],
        "alertas_comerciales": [dict(r) for r in alertas],
        "top_companias": [
            {
                "label": row["label"],
                "total": int(row["total"] or 0),
                "prima_total": round(parse_money_value(row["prima_total"]), 2),
            }
            for row in companias_rows
        ],
        "top_ramos": [
            {
                "label": row["label"],
                "total": int(row["total"] or 0),
                "prima_total": round(parse_money_value(row["prima_total"]), 2),
            }
            for row in ramos_rows
        ],
    }


def fetch_workspace_fin_overview(conn, workspace_id, empresa_id=None):
    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not empresa_ids:
        return {
            "counts": {
                "total": 0,
                "firmadas": 0,
                "asesoramientos_abiertos": 0,
                "encargos_abiertos": 0,
                "comision_total": 0,
                "alertas_abiertas": 0,
            },
            "asesoramientos_abiertos": [],
            "firmas_recientes": [],
            "alertas_comerciales": [],
            "top_bancos": [],
        }
    placeholders = ",".join(["?"] * len(empresa_ids))
    total_row = conn.execute(
        f"""
        SELECT
          COUNT(*) AS total,
          SUM(CASE WHEN fecha_firma IS NOT NULL AND TRIM(fecha_firma) <> '' THEN 1 ELSE 0 END) AS firmadas,
          SUM(COALESCE(comision, comision_modernia, 0)) AS comision_total,
          SUM(CASE WHEN encargo IS NOT NULL AND TRIM(encargo) <> '' AND LOWER(TRIM(encargo)) NOT IN ('no', 'rechazado', 'cancelado') THEN 1 ELSE 0 END) AS encargos_abiertos
        FROM hipotecas
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    asesoramientos_abiertos = conn.execute(
        f"""
        SELECT
          COUNT(*) AS total
        FROM asesoramientos_financiacion af
        WHERE af.empresa_id IN ({placeholders})
          AND LOWER(COALESCE(af.estado, '')) NOT IN ('firmada', 'cerrado', 'cerrada', 'cancelado', 'cancelada', 'rechazado', 'rechazada')
        """,
        empresa_ids,
    ).fetchone()
    alertas = conn.execute(
        f"""
        SELECT
          a.fecha,
          a.hora,
          COALESCE(c.nombre, a.cliente_nombre, '') AS cliente,
          a.tipo,
          a.estado
        FROM acciones a
        LEFT JOIN clientes c ON c.id = a.cliente_id
        WHERE a.empresa_id IN ({placeholders})
          AND LOWER(TRIM(COALESCE(a.servicio, ''))) = 'financiaciones'
          AND (a.estado IS NULL OR LOWER(TRIM(a.estado)) NOT IN ('hecho', 'finalizado', 'cancelado'))
        ORDER BY DATE(COALESCE(a.fecha, '9999-12-31')) ASC, TIME(COALESCE(a.hora, '23:59')) ASC
        LIMIT 12
        """,
        empresa_ids,
    ).fetchall()
    asesoramientos_rows = conn.execute(
        f"""
        SELECT
          af.fecha,
          af.estado,
          COALESCE(NULLIF(TRIM(af.cliente1_nombre), ''), NULLIF(TRIM(af.cliente2_nombre), ''), c.nombre, '') AS cliente,
          COALESCE(af.ingresos_conjuntos, 0) AS ingresos_conjuntos
        FROM asesoramientos_financiacion af
        LEFT JOIN clientes c ON c.id = af.cliente1_id
        WHERE af.empresa_id IN ({placeholders})
          AND LOWER(COALESCE(af.estado, '')) NOT IN ('firmada', 'cerrado', 'cerrada', 'cancelado', 'cancelada', 'rechazado', 'rechazada')
        ORDER BY DATE(COALESCE(af.fecha, af.created_at)) DESC
        LIMIT 12
        """,
        empresa_ids,
    ).fetchall()
    firmas_rows = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(h.cliente), ''), c.nombre, '') AS cliente,
          COALESCE(NULLIF(TRIM(h.banco), ''), 'Sin banco') AS banco,
          h.fecha_firma,
          COALESCE(h.comision, h.comision_modernia, 0) AS comision
        FROM hipotecas h
        LEFT JOIN clientes c ON c.id = h.cliente_id
        WHERE h.empresa_id IN ({placeholders})
          AND h.fecha_firma IS NOT NULL
          AND TRIM(h.fecha_firma) <> ''
        ORDER BY DATE(h.fecha_firma) DESC
        LIMIT 12
        """,
        empresa_ids,
    ).fetchall()
    bancos_rows = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(h.banco), ''), 'Sin banco') AS label,
          COUNT(*) AS total,
          SUM(COALESCE(h.comision, h.comision_modernia, 0)) AS comision_total
        FROM hipotecas h
        WHERE h.empresa_id IN ({placeholders})
        GROUP BY COALESCE(NULLIF(TRIM(h.banco), ''), 'Sin banco')
        ORDER BY COUNT(*) DESC, label COLLATE NOCASE ASC
        LIMIT 8
        """,
        empresa_ids,
    ).fetchall()
    return {
        "counts": {
            "total": int((total_row["total"] if total_row else 0) or 0),
            "firmadas": int((total_row["firmadas"] if total_row else 0) or 0),
            "asesoramientos_abiertos": int((asesoramientos_abiertos["total"] if asesoramientos_abiertos else 0) or 0),
            "encargos_abiertos": int((total_row["encargos_abiertos"] if total_row else 0) or 0),
            "comision_total": round(parse_money_value(total_row["comision_total"] if total_row else 0), 2),
            "alertas_abiertas": len(alertas),
        },
        "asesoramientos_abiertos": [dict(r) for r in asesoramientos_rows],
        "firmas_recientes": [
            {
                **dict(r),
                "comision": round(parse_money_value(r["comision"]), 2),
            }
            for r in firmas_rows
        ],
        "alertas_comerciales": [dict(r) for r in alertas],
        "top_bancos": [
            {
                "label": row["label"],
                "total": int(row["total"] or 0),
                "comision_total": round(parse_money_value(row["comision_total"]), 2),
            }
            for row in bancos_rows
        ],
    }


def fetch_workspace_inmo_overview(conn, workspace_id, empresa_id=None):
    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not empresa_ids:
        return {
            "counts": {
                "inmuebles": 0,
                "captaciones_activas": 0,
                "compraventas": 0,
                "volumen_cierre": 0,
                "visitas_programadas": 0,
                "demandas_activas": 0,
            },
            "captaciones_activas": [],
            "operaciones_recientes": [],
            "proximas_visitas": [],
            "top_zonas": [],
        }
    placeholders = ",".join(["?"] * len(empresa_ids))
    today = datetime.now().date().isoformat()
    inmuebles_total = conn.execute(
        f"SELECT COUNT(*) AS total FROM inmuebles WHERE empresa_id IN ({placeholders})",
        empresa_ids,
    ).fetchone()
    captaciones_summary = conn.execute(
        f"""
        SELECT
          COUNT(*) AS total,
          SUM(CASE WHEN LOWER(COALESCE(etapa, '')) NOT IN ('cerrado negativamente', 'vendido', 'alquiler') THEN 1 ELSE 0 END) AS activas
        FROM captaciones
        WHERE empresa_id IN ({placeholders})
        """,
        empresa_ids,
    ).fetchone()
    operaciones_summary = conn.execute(
        f"""
        SELECT
          COUNT(*) AS total,
          SUM(COALESCE(precio_escritura, precio_contrato, precio_propuesta, 0)) AS volumen
        FROM operaciones_inmobiliarias
        WHERE empresa_id IN ({placeholders})
          AND LOWER(COALESCE(tipo_operacion, '')) = 'venta'
        """,
        empresa_ids,
    ).fetchone()
    visitas_programadas = conn.execute(
        f"""
        SELECT COUNT(*) AS total
        FROM visitas
        WHERE empresa_id IN ({placeholders})
          AND fecha IS NOT NULL
          AND DATE(fecha) >= DATE(?)
          AND LOWER(COALESCE(estado, '')) NOT IN ('cancelada', 'cancelado', 'hecha', 'realizada')
        """,
        [*empresa_ids, today],
    ).fetchone()
    demandas_activas = conn.execute(
        f"""
        SELECT COUNT(*) AS total
        FROM demandas
        WHERE empresa_id IN ({placeholders})
          AND LOWER(COALESCE(estado, '')) NOT IN ('cerrada', 'cerrado', 'cancelada', 'cancelado')
        """,
        empresa_ids,
    ).fetchone()
    captaciones_rows = conn.execute(
        f"""
        SELECT direccion, zona, propietario, precio_objetivo
        FROM captaciones
        WHERE empresa_id IN ({placeholders})
          AND LOWER(COALESCE(etapa, '')) NOT IN ('cerrado negativamente', 'vendido', 'alquiler')
        ORDER BY COALESCE(updated_at, created_at) DESC
        LIMIT 12
        """,
        empresa_ids,
    ).fetchall()
    operaciones_rows = conn.execute(
        f"""
        SELECT direccion, tipo_operacion, COALESCE(fecha_operacion, fecha_escritura, fecha_contrato, fecha_propuesta) AS fecha_operacion,
               precio_propuesta, precio_contrato, precio_escritura
        FROM operaciones_inmobiliarias
        WHERE empresa_id IN ({placeholders})
        ORDER BY DATE(COALESCE(fecha_operacion, fecha_escritura, fecha_contrato, fecha_propuesta, created_at)) DESC
        LIMIT 12
        """,
        empresa_ids,
    ).fetchall()
    visitas_rows = conn.execute(
        f"""
        SELECT
          v.fecha,
          v.hora,
          v.estado,
          COALESCE(i.direccion, '') AS inmueble,
          COALESCE(c.nombre, '') AS cliente
        FROM visitas v
        LEFT JOIN inmuebles i ON i.id = v.inmueble_id
        LEFT JOIN demandas d ON d.id = v.demanda_id
        LEFT JOIN clientes c ON c.id = d.cliente_id
        WHERE v.empresa_id IN ({placeholders})
          AND v.fecha IS NOT NULL
          AND DATE(v.fecha) >= DATE(?)
          AND LOWER(COALESCE(v.estado, '')) NOT IN ('cancelada', 'cancelado', 'hecha', 'realizada')
        ORDER BY DATE(v.fecha) ASC, TIME(COALESCE(v.hora, '23:59')) ASC
        LIMIT 12
        """,
        [*empresa_ids, today],
    ).fetchall()
    zonas_rows = conn.execute(
        f"""
        SELECT
          COALESCE(NULLIF(TRIM(zona), ''), 'Sin zona') AS label,
          COUNT(*) AS total,
          SUM(COALESCE(precio_objetivo, 0)) AS precio_total
        FROM captaciones
        WHERE empresa_id IN ({placeholders})
        GROUP BY COALESCE(NULLIF(TRIM(zona), ''), 'Sin zona')
        ORDER BY COUNT(*) DESC, label COLLATE NOCASE ASC
        LIMIT 8
        """,
        empresa_ids,
    ).fetchall()
    return {
        "counts": {
            "inmuebles": int((inmuebles_total["total"] if inmuebles_total else 0) or 0),
            "captaciones_activas": int((captaciones_summary["activas"] if captaciones_summary else 0) or 0),
            "compraventas": int((operaciones_summary["total"] if operaciones_summary else 0) or 0),
            "volumen_cierre": round(parse_money_value(operaciones_summary["volumen"] if operaciones_summary else 0), 2),
            "visitas_programadas": int((visitas_programadas["total"] if visitas_programadas else 0) or 0),
            "demandas_activas": int((demandas_activas["total"] if demandas_activas else 0) or 0),
        },
        "captaciones_activas": [dict(r) for r in captaciones_rows],
        "operaciones_recientes": [dict(r) for r in operaciones_rows],
        "proximas_visitas": [dict(r) for r in visitas_rows],
        "top_zonas": [
            {
                "label": row["label"],
                "total": int(row["total"] or 0),
                "precio_total": round(parse_money_value(row["precio_total"]), 2),
            }
            for row in zonas_rows
        ],
    }


def fetch_workspace_service_desks(conn, workspace_id, empresa_id=None):
    empresa_ids = resolve_workspace_company_ids(conn, workspace_id, empresa_id=empresa_id)
    if not empresa_ids:
        return {"gestoria": [], "seguros": [], "financiacion": [], "inmobiliaria": []}
    placeholders = ",".join(["?"] * len(empresa_ids))
    today = app_now().date().isoformat()

    def _format_valor(rows):
        formatted = []
        for item in rows or []:
            row = dict(item) if not isinstance(item, dict) else dict(item)
            raw = row.get("valor")
            if raw in (None, ""):
                row["valor"] = ""
                formatted.append(row)
                continue
            try:
                num = float(raw)
            except Exception:
                row["valor"] = str(raw or "")
                formatted.append(row)
                continue
            row["valor"] = format_eur(num) if num > 0 else ""
            formatted.append(row)
        return formatted
    # Gestoría: evitar UNION pesado (reduce tiempos y cuelgues en SQLite).
    service_filter = (
        "LOWER(ce.servicio) IN ('gestoria', 'gestoría', "
        "'administracion fincas', 'administración fincas')"
    )
    modelo_rows = conn.execute(
        f"""
        SELECT
          c.id AS cliente_id,
          COALESCE(c.nombre, '') AS titulo,
          'Modelo ' || COALESCE(m.modelo, '') AS subtitulo,
          COALESCE(m.estado, 'Pendiente') AS estado,
          m.proxima_fecha AS fecha,
          '' AS valor,
          1 AS sort_group
        FROM gestoria_modelos m
        JOIN clientes c ON c.id = m.cliente_id
        JOIN clientes_empresas ce ON ce.cliente_id = c.id
        WHERE ce.empresa_id IN ({placeholders})
          AND {service_filter}
          AND m.proxima_fecha IS NOT NULL
          AND DATE(m.proxima_fecha) <= DATE(?, '+30 day')
        ORDER BY DATE(m.proxima_fecha) ASC, titulo COLLATE NOCASE ASC
        LIMIT 8
        """,
        [*empresa_ids, today],
    ).fetchall()
    trabajo_rows = conn.execute(
        f"""
        SELECT
          gt.cliente_id,
          COALESCE(c.nombre, '') AS titulo,
          COALESCE(gt.tipo_trabajo, 'Trabajo') AS subtitulo,
          COALESCE(gt.estado, 'Pendiente') AS estado,
          COALESCE(gt.fecha_fin, gt.fecha_inicio, '') AS fecha,
          CASE WHEN COALESCE(gt.importe, 0) > 0 THEN COALESCE(gt.importe, 0) ELSE NULL END AS valor,
          2 AS sort_group
        FROM gestoria_trabajos gt
        LEFT JOIN clientes c ON c.id = gt.cliente_id
        WHERE gt.empresa_id IN ({placeholders})
          AND LOWER(COALESCE(gt.estado, '')) NOT IN ('finalizado', 'finalizada', 'cancelado', 'cancelada')
        ORDER BY DATE(COALESCE(gt.fecha_fin, gt.fecha_inicio, '9999-12-31')) ASC, titulo COLLATE NOCASE ASC
        LIMIT 8
        """,
        empresa_ids,
    ).fetchall()
    gestoria_rows = [*modelo_rows, *trabajo_rows]
    gestoria_rows.sort(
        key=lambda row: (
            int(row["sort_group"] or 9) if isinstance(row, sqlite3.Row) else int(row.get("sort_group") or 9),
            str((row["fecha"] if isinstance(row, sqlite3.Row) else row.get("fecha")) or "9999-12-31")[:10],
            str((row["titulo"] if isinstance(row, sqlite3.Row) else row.get("titulo")) or "").lower(),
        )
    )
    gestoria_rows = gestoria_rows[:16]

    seguros_rows = conn.execute(
        f"""
        SELECT
          s.cliente_id,
          COALESCE(NULLIF(TRIM(s.tomador), ''), c.nombre, '') AS titulo,
          COALESCE(NULLIF(TRIM(s.compania), ''), 'Sin compañía') || ' · ' || COALESCE(NULLIF(TRIM(s.ramo), ''), 'Sin ramo') AS subtitulo,
          COALESCE(NULLIF(TRIM(s.estado), ''), 'Pendiente') AS estado,
          COALESCE({seguro_date_sql('fecha_vencimiento', 's')}, {seguro_date_sql('fecha_efecto', 's')}) AS fecha,
          CASE WHEN COALESCE(s.prima_total, s.prima_neta, 0) > 0 THEN COALESCE(s.prima_total, s.prima_neta, 0) ELSE NULL END AS valor
        FROM seguros s
        LEFT JOIN clientes c ON c.id = s.cliente_id
        WHERE s.empresa_id IN ({placeholders})
          AND LOWER(COALESCE(TRIM(s.compania), '')) != 'sin seguro'
        ORDER BY COALESCE(DATE({seguro_date_sql('fecha_vencimiento', 's')}), DATE({seguro_date_sql('fecha_efecto', 's')}), DATE(s.updated_at), DATE(s.created_at)) ASC
        LIMIT 16
        """,
        empresa_ids,
    ).fetchall()

    # Financiación: evitar UNION y ORDER BY global (se vuelve muy costoso con tablas grandes).
    financiacion_rows = []
    financiacion_ases = conn.execute(
        f"""
        SELECT
          af.cliente1_id AS cliente_id,
          COALESCE(NULLIF(TRIM(af.cliente1_nombre), ''), NULLIF(TRIM(af.cliente2_nombre), ''), '') AS titulo,
          'Asesoramiento financiero' AS subtitulo,
          COALESCE(af.estado, 'Pendiente') AS estado,
          COALESCE(af.fecha, af.updated_at, af.created_at) AS fecha,
          CASE WHEN COALESCE(af.ingresos_conjuntos, 0) > 0 THEN COALESCE(af.ingresos_conjuntos, 0) ELSE NULL END AS valor,
          1 AS sort_group
        FROM asesoramientos_financiacion af
        WHERE af.empresa_id IN ({placeholders})
          AND LOWER(COALESCE(af.estado, '')) NOT IN ('firmada', 'cerrado', 'cerrada', 'cancelado', 'cancelada', 'rechazado', 'rechazada')
        ORDER BY DATE(COALESCE(af.fecha, af.updated_at, af.created_at, '1900-01-01')) DESC, titulo COLLATE NOCASE ASC
        LIMIT 8
        """,
        empresa_ids,
    ).fetchall()
    financiacion_hipotecas = conn.execute(
        f"""
        SELECT
          h.cliente_id,
          COALESCE(NULLIF(TRIM(h.cliente), ''), c.nombre, '') AS titulo,
          COALESCE(NULLIF(TRIM(h.banco), ''), 'Hipoteca') AS subtitulo,
          COALESCE(h.estado, 'Firmada') AS estado,
          COALESCE(h.fecha_firma, h.fecha_encargo, h.updated_at, h.created_at) AS fecha,
          CASE WHEN COALESCE(h.comision, h.comision_modernia, 0) > 0 THEN COALESCE(h.comision, h.comision_modernia, 0) ELSE NULL END AS valor,
          2 AS sort_group
        FROM hipotecas h
        LEFT JOIN clientes c ON c.id = h.cliente_id
        WHERE h.empresa_id IN ({placeholders})
        ORDER BY DATE(COALESCE(h.fecha_firma, h.fecha_encargo, h.updated_at, h.created_at, '1900-01-01')) DESC, titulo COLLATE NOCASE ASC
        LIMIT 8
        """,
        empresa_ids,
    ).fetchall()
    financiacion_rows = [*financiacion_ases, *financiacion_hipotecas]
    # Orden estable: grupo ASC, fecha DESC, título ASC.
    financiacion_rows.sort(key=lambda row: str(row["titulo"] or "").lower())
    financiacion_rows.sort(key=lambda row: str(row["fecha"] or "")[:10], reverse=True)
    financiacion_rows.sort(key=lambda row: int(row["sort_group"] or 9))
    financiacion_rows = financiacion_rows[:16]

    # Inmobiliaria: evitar UNION global (muy costoso) y limitar cada fuente.
    inmobiliaria_rows = []
    inmo_captaciones = conn.execute(
        f"""
        SELECT
          '' AS cliente_id,
          COALESCE(NULLIF(TRIM(c.direccion), ''), 'Captación') AS titulo,
          COALESCE(NULLIF(TRIM(c.zona), ''), 'Sin zona') AS subtitulo,
          COALESCE(c.etapa, 'Captación') AS estado,
          COALESCE(c.fecha_contacto, c.updated_at, c.created_at) AS fecha,
          CASE WHEN COALESCE(c.precio_objetivo, 0) > 0 THEN COALESCE(c.precio_objetivo, 0) ELSE NULL END AS valor,
          1 AS sort_group
        FROM captaciones c
        WHERE c.empresa_id IN ({placeholders})
          AND LOWER(COALESCE(c.etapa, '')) NOT IN ('cerrado negativamente', 'vendido', 'alquiler')
        ORDER BY DATE(COALESCE(c.fecha_contacto, c.updated_at, c.created_at, '1900-01-01')) DESC, titulo COLLATE NOCASE ASC
        LIMIT 6
        """,
        empresa_ids,
    ).fetchall()
    inmo_operaciones = conn.execute(
        f"""
        SELECT
          COALESCE(o.contraparte1_id, o.propietario1_id, '') AS cliente_id,
          COALESCE(NULLIF(TRIM(o.direccion), ''), 'Compraventa') AS titulo,
          COALESCE(NULLIF(TRIM(o.tipo_operacion), ''), 'Operación') AS subtitulo,
          COALESCE(o.estado, 'Cerrada') AS estado,
          COALESCE(o.fecha_escritura, o.fecha_operacion, o.fecha_contrato, o.fecha_propuesta, o.updated_at, o.created_at) AS fecha,
          CASE WHEN COALESCE(o.precio_escritura, o.precio_contrato, o.precio_propuesta, 0) > 0 THEN COALESCE(o.precio_escritura, o.precio_contrato, o.precio_propuesta, 0) ELSE NULL END AS valor,
          2 AS sort_group
        FROM operaciones_inmobiliarias o
        WHERE o.empresa_id IN ({placeholders})
        ORDER BY DATE(COALESCE(o.fecha_escritura, o.fecha_operacion, o.fecha_contrato, o.fecha_propuesta, o.updated_at, o.created_at, '1900-01-01')) DESC, titulo COLLATE NOCASE ASC
        LIMIT 6
        """,
        empresa_ids,
    ).fetchall()
    inmo_visitas = conn.execute(
        f"""
        SELECT
          d.cliente_id,
          COALESCE(NULLIF(TRIM(i.direccion), ''), 'Visita') AS titulo,
          COALESCE(c.nombre, 'Sin demanda') AS subtitulo,
          COALESCE(v.estado, 'Pendiente') AS estado,
          v.fecha || CASE WHEN COALESCE(v.hora, '') <> '' THEN ' ' || v.hora ELSE '' END AS fecha,
          '' AS valor,
          3 AS sort_group
        FROM visitas v
        LEFT JOIN inmuebles i ON i.id = v.inmueble_id
        LEFT JOIN demandas d ON d.id = v.demanda_id
        LEFT JOIN clientes c ON c.id = d.cliente_id
        WHERE v.empresa_id IN ({placeholders})
          AND v.fecha IS NOT NULL
          AND DATE(v.fecha) >= DATE(?)
          AND LOWER(COALESCE(v.estado, '')) NOT IN ('cancelada', 'cancelado', 'hecha', 'realizada')
        ORDER BY DATE(v.fecha) ASC, TIME(COALESCE(v.hora, '23:59')) ASC, titulo COLLATE NOCASE ASC
        LIMIT 6
        """,
        [*empresa_ids, today],
    ).fetchall()
    inmobiliaria_rows = [*inmo_captaciones, *inmo_operaciones, *inmo_visitas]
    inmobiliaria_rows = inmobiliaria_rows[:16]

    return {
        "gestoria": _format_valor(gestoria_rows),
        "seguros": _format_valor(seguros_rows),
        "financiacion": _format_valor(financiacion_rows),
        "inmobiliaria": _format_valor(inmobiliaria_rows),
    }


def fetch_workspace_series(conn, workspace_id):
    rows = conn.execute(
        """
        SELECT
          s.id,
          s.workspace_id,
          s.empresa_id,
          COALESCE(e.nombre, '') AS empresa_nombre,
          s.servicio,
          s.serie,
          COALESCE(s.prefijo, '') AS prefijo,
          COALESCE(s.siguiente_numero, 1) AS siguiente_numero,
          COALESCE(s.activa, 1) AS activa
        FROM workspace_facturacion_series s
        LEFT JOIN empresas e ON e.id = s.empresa_id
        WHERE s.workspace_id = ?
        ORDER BY COALESCE(e.nombre, '') COLLATE NOCASE ASC, s.serie COLLATE NOCASE ASC
        """,
        (workspace_id,),
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}


def fetch_workspace_inbox_queue(conn, workspace_id, limit=40):
    rows = conn.execute(
        """
        SELECT
          q.id,
          q.workspace_id,
          q.empresa_id,
          COALESCE(e.nombre, '') AS empresa_nombre,
          q.cliente_id,
          COALESCE(c.nombre, '') AS cliente_nombre,
          q.suggested_cliente_id,
          COALESCE(sc.nombre, '') AS suggested_cliente_nombre,
          q.servicio,
          q.nombre,
          q.tipo,
          q.clasificacion,
          q.canal_entrada,
          q.prioridad,
          q.estado,
          q.doc_key,
          q.doc_url,
          q.origen_tipo,
          q.origen_id,
          q.reviewed_at,
          q.reviewed_by,
          q.notas,
          q.created_at,
          q.updated_at,
          COALESCE(req.titulo, '') AS requerimiento_titulo
        FROM workspace_documentos_inbox q
        LEFT JOIN empresas e ON e.id = q.empresa_id
        LEFT JOIN clientes c ON c.id = q.cliente_id
        LEFT JOIN clientes sc ON sc.id = q.suggested_cliente_id
        LEFT JOIN workspace_portal_requerimientos req ON req.id = q.origen_id AND q.origen_tipo = 'portal_requerimiento'
        WHERE q.workspace_id = ?
        ORDER BY q.updated_at DESC, q.created_at DESC
        LIMIT ?
        """,
        (workspace_id, max(1, min(int(limit or 40), 100))),
    ).fetchall()
    return {"rows": [dict(row) for row in rows]}


