def build_workspace_time_xlsx(rows, workspace=None, company=None, persona=None, month=""):
    workspace = workspace or {}
    company = company or {}
    persona = persona or {}
    # Generate a minimal .xlsx (OOXML) without external dependencies (openpyxl).
    # Excel can open this file normally.
    import zipfile
    from xml.sax.saxutils import escape as xml_escape

    def col_letter(idx):
        idx = int(idx)
        letters = ""
        while idx > 0:
            idx, rem = divmod(idx - 1, 26)
            letters = chr(65 + rem) + letters
        return letters

    def cell_ref(row_idx, col_idx):
        return f"{col_letter(col_idx)}{row_idx}"

    def xml_cell(row_idx, col_idx, value):
        ref = cell_ref(row_idx, col_idx)
        if value is None:
            return f'<c r="{ref}"/>'
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return f'<c r="{ref}"><v>{value}</v></c>'
        text = str(value)
        # Keep newlines; Excel supports them in inline strings.
        text = xml_escape(text)
        return f'<c r="{ref}" t="inlineStr"><is><t xml:space="preserve">{text}</t></is></c>'

    lines = []
    worker_name = persona.get("persona_nombre") or persona.get("nombre") or ""
    worker_nif = persona.get("nif") or persona.get("persona_nif") or ""
    worker_email = persona.get("email") or persona.get("persona_email") or ""
    lines.append(["Workspace", workspace.get("nombre") or ""])
    lines.append(["Empresa", company.get("nombre") or ""])
    lines.append(["Trabajador", worker_name])
    if worker_nif:
        lines.append(["DNI/NIF", worker_nif])
    if worker_email:
        lines.append(["Email", worker_email])
    lines.append(["Mes", month or ""])
    lines.append(["Zona horaria", APP_TIMEZONE])
    lines.append(["Generado", app_now().strftime("%Y-%m-%d %H:%M:%S")])
    lines.append([])
    lines.append(
        [
            "Fecha",
            "Inicio",
            "Fin",
            "Pausa (min)",
            "Minutos trabajados",
            "Horas (HH:MM)",
            "Método",
            "Geo entrada",
            "Geo salida",
            "Estado",
            "Notas",
            "Creado",
            "Actualizado",
        ]
    )
    for row in rows or []:
        minutos = int(row.get("minutos_trabajados") or 0)
        geo_in = ""
        if row.get("geo_in_lat") not in (None, "") and row.get("geo_in_lon") not in (None, ""):
            geo_in = f"{row.get('geo_in_lat')},{row.get('geo_in_lon')}" + (f" ±{row.get('geo_in_acc')}m" if row.get("geo_in_acc") not in (None, "") else "")
        geo_out = ""
        if row.get("geo_out_lat") not in (None, "") and row.get("geo_out_lon") not in (None, ""):
            geo_out = f"{row.get('geo_out_lat')},{row.get('geo_out_lon')}" + (f" ±{row.get('geo_out_acc')}m" if row.get("geo_out_acc") not in (None, "") else "")
        lines.append(
            [
                row.get("fecha") or "",
                row.get("hora_inicio") or "",
                row.get("hora_fin") or "",
                int(row.get("pausa_min") or 0),
                minutos,
                format_minutes_hhmm(minutos),
                row.get("metodo_registro") or "",
                geo_in,
                geo_out,
                row.get("estado") or "",
                row.get("notas") or "",
                row.get("created_at") or "",
                row.get("updated_at") or "",
            ]
        )

    sheet_rows = []
    for r_idx, row in enumerate(lines, start=1):
        if not row:
            sheet_rows.append(f'<row r="{r_idx}"></row>')
            continue
        cells = []
        for c_idx, val in enumerate(row, start=1):
            cells.append(xml_cell(r_idx, c_idx, val))
        sheet_rows.append(f'<row r="{r_idx}">{"".join(cells)}</row>')

    sheet_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        "<sheetData>"
        + "".join(sheet_rows)
        + "</sheetData>"
        "</worksheet>"
    )

    workbook_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
        "<sheets>"
        '<sheet name="Registro horario" sheetId="1" r:id="rId1"/>'
        "</sheets>"
        "</workbook>"
    )

    rels_root = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
        "</Relationships>"
    )

    rels_wb = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
        '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
        "</Relationships>"
    )

    # Minimal styles (required by some Excel versions to avoid warnings).
    styles_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        "<fonts count=\"1\"><font><sz val=\"11\"/><color rgb=\"FF000000\"/><name val=\"Calibri\"/><family val=\"2\"/></font></fonts>"
        "<fills count=\"1\"><fill><patternFill patternType=\"none\"/></fill></fills>"
        "<borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders>"
        "<cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs>"
        "<cellXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyFont=\"1\"/></cellXfs>"
        "<cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles>"
        "</styleSheet>"
    )

    content_types = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Default Extension="xml" ContentType="application/xml"/>'
        '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
        '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
        '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
        "</Types>"
    )

    buffer = BytesIO()
    with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("[Content_Types].xml", content_types)
        zf.writestr("_rels/.rels", rels_root)
        zf.writestr("xl/workbook.xml", workbook_xml)
        zf.writestr("xl/_rels/workbook.xml.rels", rels_wb)
        zf.writestr("xl/worksheets/sheet1.xml", sheet_xml)
        zf.writestr("xl/styles.xml", styles_xml)
    return buffer.getvalue()


def fetch_workspace_alert_preferences(conn, workspace_id, persona_id=None):
    where = ["workspace_id = ?"]
    params = [workspace_id]
    if persona_id:
        where.append("persona_id = ?")
        params.append(persona_id)
    row = conn.execute(
        f"""
        SELECT * FROM workspace_registro_alerts
        WHERE {' AND '.join(where)}
        LIMIT 1
        """,
        params,
    ).fetchone()
    if row:
        return dict(row)
    # fallback to personal record (maps legacy column names to the alert schema)
    if persona_id:
        row = conn.execute(
            """
            SELECT *
            FROM workspace_registro_personal
            WHERE workspace_id = ? AND id = ?
            LIMIT 1
            """,
            (workspace_id, persona_id),
        ).fetchone()
        if row:
            record = dict(row)
            return {
                "workspace_id": workspace_id,
                "empresa_id": record.get("empresa_id"),
                "persona_id": record.get("id"),
                "alert_missing_checkin": record.get("alert_missing_checkin", 1),
                "alert_missing_checkout": record.get("alert_missing_checkout", 1),
                "notify_worker": record.get("alert_notify_worker", 1),
                "notify_admin": record.get("alert_notify_admin", 1),
                "admin_contact": record.get("alert_admin_contact") or "",
                "schedule": "",
            }
    return None


def upsert_workspace_alert_config(conn, workspace_id, persona_id, payload, now=None):
    now_ts = now or datetime.now().isoformat()
    existing = conn.execute(
        """
        SELECT id FROM workspace_registro_alerts
        WHERE workspace_id = ? AND persona_id = ?
        LIMIT 1
        """,
        (workspace_id, persona_id),
    ).fetchone()
    values = (
        (payload.get("empresa_id") or "").strip() or None,
        0 if str(payload.get("alert_missing_checkin") or "1").strip().lower() in {"0", "false", "no", "off"} else 1,
        0 if str(payload.get("alert_missing_checkout") or "1").strip().lower() in {"0", "false", "no", "off"} else 1,
        0 if str(payload.get("notify_worker") or "1").strip().lower() in {"0", "false", "no", "off"} else 1,
        0 if str(payload.get("notify_admin") or "1").strip().lower() in {"0", "false", "no", "off"} else 1,
        (payload.get("admin_contact") or "").strip() or "",
        (payload.get("schedule") or "").strip() or "",
    )
    if existing:
        conn.execute(
            """
            UPDATE workspace_registro_alerts
            SET empresa_id = ?, alert_missing_checkin = ?, alert_missing_checkout = ?, notify_worker = ?, notify_admin = ?, admin_contact = ?, schedule = ?, updated_at = ?
            WHERE id = ? AND workspace_id = ?
            """,
            (*values, now_ts, existing["id"], workspace_id),
        )
        return existing["id"]
    record_id = os.urandom(16).hex()
    conn.execute(
        """
        INSERT INTO workspace_registro_alerts (
          id, workspace_id, empresa_id, persona_id, alert_missing_checkin, alert_missing_checkout,
          notify_worker, notify_admin, admin_contact, schedule, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (record_id, workspace_id, values[0], persona_id, values[1], values[2], values[3], values[4], values[5], values[6], now_ts, now_ts),
    )
    return record_id


def fetch_workspace_notifications(conn, workspace_id, limit=40, persona_id=None):
    where = ["workspace_id = ?"]
