def _parse_iso_date(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.strptime(raw[:10], "%Y-%m-%d").date()
    except Exception:
        return None


def _count_business_days(start_date, end_date):
    if not start_date or not end_date or end_date < start_date:
        return 0
    days = 0
    cursor = start_date
    while cursor <= end_date:
        if cursor.weekday() < 5:
            days += 1
        cursor += timedelta(days=1)
    return days


def _count_calendar_days(start_date, end_date):
    if not start_date or not end_date or end_date < start_date:
        return 0
    return (end_date - start_date).days + 1


def _count_absence_days(start_date, end_date, mode="habiles"):
    mode_key = str(mode or "").strip().lower()
    if mode_key in {"naturales", "natural", "calendario", "calendar"}:
        return _count_calendar_days(start_date, end_date)
    return _count_business_days(start_date, end_date)


def _fetch_empresa_vacaciones_modo_map(conn, empresa_ids):
    ids = [str(i or "").strip() for i in list(empresa_ids or []) if str(i or "").strip()]
    if not ids:
        return {}
    placeholders = ",".join(["?"] * len(ids))
    rows = conn.execute(
        f"SELECT id, COALESCE(NULLIF(vacaciones_modo,''), 'habiles') AS modo FROM empresas WHERE id IN ({placeholders})",
        ids,
    ).fetchall()
    return {str(r["id"]): str(r["modo"] or "habiles") for r in rows if str(r["id"] or "").strip()}


def fetch_workspace_rrhh_vacaciones_summary(conn, workspace_id, year=None):
    try:
        year_int = int(str(year or "").strip() or datetime.now().year)
    except Exception:
        year_int = datetime.now().year
    year_int = max(2000, min(year_int, 2100))
    year_start = date(year_int, 1, 1)
    year_end = date(year_int, 12, 31)

    # Totales por persona (si no hay perfil, asumimos 22).
    profile_rows = conn.execute(
        """
        SELECT persona_id, COALESCE(vacaciones_dias_anuales, 22) AS dias_total
        FROM workspace_rrhh_profile
        WHERE workspace_id = ?
        """,
        (workspace_id,),
    ).fetchall()
    total_map = {str(r["persona_id"]): float(r["dias_total"] or 22) for r in profile_rows if str(r["persona_id"] or "").strip()}

    # Personas del workspace (excluye legacy auto).
    personal_rows = conn.execute(
        """
        SELECT id AS persona_id
        FROM workspace_registro_personal
        WHERE workspace_id = ?
          AND COALESCE(source, 'manual') != 'auto'
        """,
        (workspace_id,),
    ).fetchall()
    persona_ids = [str(r["persona_id"]) for r in personal_rows if str(r["persona_id"] or "").strip()]

    # Vacaciones aprobadas del año.
    abs_rows = conn.execute(
        """
        SELECT persona_id, empresa_id, fecha_inicio, fecha_fin
        FROM workspace_rrhh_ausencias
        WHERE workspace_id = ?
          AND tipo = 'Vacaciones'
          AND estado = 'Aprobada'
          AND (substr(fecha_inicio, 1, 4) = ? OR substr(fecha_fin, 1, 4) = ?)
        """,
        (workspace_id, str(year_int), str(year_int)),
    ).fetchall()
    empresa_ids = {str(r["empresa_id"] or "").strip() for r in abs_rows if str(r["empresa_id"] or "").strip()}
    vac_mode_map = _fetch_empresa_vacaciones_modo_map(conn, empresa_ids)
    used_map = {pid: 0 for pid in persona_ids}
    for row in abs_rows:
        pid = str(row["persona_id"] or "").strip()
        if not pid:
            continue
        start = _parse_iso_date(row["fecha_inicio"])
        end = _parse_iso_date(row["fecha_fin"])
        if not start or not end:
            continue
        if end < year_start or start > year_end:
            continue
        clipped_start = max(start, year_start)
        clipped_end = min(end, year_end)
        modo = vac_mode_map.get(str(row["empresa_id"] or "").strip(), "habiles")
        used_map[pid] = used_map.get(pid, 0) + _count_absence_days(clipped_start, clipped_end, modo)

    rows = []
    for pid in persona_ids:
        total = float(total_map.get(pid, 22) or 22)
        used = float(used_map.get(pid, 0) or 0)
        pending = max(total - used, 0.0)
        rows.append(
            {
                "persona_id": pid,
                "year": year_int,
                "dias_total": round(total, 2),
                "dias_usados": round(used, 2),
                "dias_pendientes": round(pending, 2),
            }
        )
    return {"rows": rows}


def _parse_alert_last_sent(value):
    raw = str(value or "").strip()
    if not raw:
        return {}
    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _update_alert_last_sent(conn, workspace_id, persona_id, updates, now=None):
    now_ts = now or app_now().isoformat()
    existing = conn.execute(
        """
        SELECT alert_last_sent
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND id = ?
        LIMIT 1
        """,
        (workspace_id, persona_id),
    ).fetchone()
    current = _parse_alert_last_sent(existing["alert_last_sent"] if existing else "")
    current.update({k: v for k, v in (updates or {}).items() if v})
    conn.execute(
        """
        UPDATE workspace_registro_personal
        SET alert_last_sent = ?, updated_at = datetime(?)
        WHERE workspace_id = ? AND id = ?
        """,
        (json.dumps(current, ensure_ascii=False), now_ts, workspace_id, persona_id),
    )


def run_workspace_time_missing_sweep(conn, workspace_id, now=None):
    # Importante: Render suele ejecutar en UTC. Para alertas (faltan entrada/salida) usamos hora local.
    if now:
        now_ts = now
        now_dt = parse_iso_datetime(now_ts) or app_now()
    else:
        now_dt = app_now()
        now_ts = now_dt.isoformat()
    today = now_dt.date().isoformat()
    now_minutes = parse_hhmm_to_minutes(now_dt.strftime("%H:%M")) or 0
    personal = conn.execute(
        """
        SELECT id, workspace_id, empresa_id, nombre, horas_pactadas_dia,
               COALESCE(alert_missing_checkin, 1) AS alert_missing_checkin,
               COALESCE(alert_missing_checkout, 1) AS alert_missing_checkout,
               COALESCE(alert_notify_worker, 1) AS alert_notify_worker,
               COALESCE(alert_notify_admin, 1) AS alert_notify_admin,
               COALESCE(alert_admin_contact, '') AS alert_admin_contact,
               COALESCE(alert_last_sent, '') AS alert_last_sent
        FROM workspace_registro_personal
        WHERE workspace_id = ? AND COALESCE(activo, 1) = 1
        ORDER BY nombre COLLATE NOCASE ASC
        """,
        (workspace_id,),
    ).fetchall()
    created = []
    for row in personal:
        persona_id = str(row["id"] or "").strip()
        if not persona_id:
            continue
        prefs = fetch_workspace_alert_preferences(conn, workspace_id, persona_id=persona_id) or {}
        schedule = str(prefs.get("schedule") or "").strip() or "10:00"
        checkin_deadline = parse_hhmm_to_minutes(schedule) or 600
        horas_pactadas = row["horas_pactadas_dia"]
        try:
            horas_pactadas = float(horas_pactadas) if horas_pactadas not in (None, "") else 8.0
        except Exception:
            horas_pactadas = 8.0
        checkout_deadline = checkin_deadline + int(round(horas_pactadas * 60)) + 30
        last_sent = _parse_alert_last_sent(row["alert_last_sent"])
        worker_payload = {
            "persona_nombre": row["nombre"],
            "fecha": today,
            "empresa_id": row["empresa_id"],
            "admin_contact": prefs.get("admin_contact") or row["alert_admin_contact"] or "",
        }
        today_entry = conn.execute(
            """
            SELECT id, hora_inicio, hora_fin
            FROM workspace_registro_horario
            WHERE workspace_id = ? AND persona_id = ? AND fecha = ?
            ORDER BY hora_inicio DESC
            LIMIT 1
            """,
            (workspace_id, persona_id, today),
        ).fetchone()
        has_checkin = bool(today_entry and str(today_entry["hora_inicio"] or "").strip())
        open_entry = bool(today_entry and not str(today_entry["hora_fin"] or "").strip())
        if not has_checkin and now_minutes >= checkin_deadline and int(prefs.get("alert_missing_checkin") or row["alert_missing_checkin"] or 0) == 1:
            if last_sent.get("missing_checkin") != today:
                if int(prefs.get("notify_worker") or row["alert_notify_worker"] or 0) == 1:
                    log_workspace_notification(conn, workspace_id, persona_id, "worker_missing_checkin", worker_payload, now=now_ts)
                    created.append("worker_missing_checkin")
                if int(prefs.get("notify_admin") or row["alert_notify_admin"] or 0) == 1:
                    log_workspace_notification(conn, workspace_id, persona_id, "admin_missing_checkin", worker_payload, now=now_ts)
                    created.append("admin_missing_checkin")
                _update_alert_last_sent(conn, workspace_id, persona_id, {"missing_checkin": today}, now=now_ts)
        if open_entry and now_minutes >= checkout_deadline and int(prefs.get("alert_missing_checkout") or row["alert_missing_checkout"] or 0) == 1:
            if last_sent.get("missing_checkout") != today:
                if int(prefs.get("notify_worker") or row["alert_notify_worker"] or 0) == 1:
                    log_workspace_notification(conn, workspace_id, persona_id, "worker_missing_checkout", worker_payload, now=now_ts)
                    created.append("worker_missing_checkout")
                if int(prefs.get("notify_admin") or row["alert_notify_admin"] or 0) == 1:
                    log_workspace_notification(conn, workspace_id, persona_id, "admin_missing_checkout", worker_payload, now=now_ts)
                    created.append("admin_missing_checkout")
                _update_alert_last_sent(conn, workspace_id, persona_id, {"missing_checkout": today}, now=now_ts)
    return created


def workspace_time_sweep_loop(db_path, interval_seconds=300):
    while True:
        try:
            conn = get_db(db_path)
            ensure_workspace_product_tables(conn)
            workspaces = conn.execute("SELECT id FROM workspaces").fetchall()
            notifications_total = 0
            workspaces_scanned = 0
            for row in workspaces:
                workspace_id = str(row_value(row, "id") or row_value(row, 0) or "").strip()
                if not workspace_id:
                    continue
                workspaces_scanned += 1
                enabled = conn.execute(
                    """
                    SELECT 1
                    FROM workspace_modulos
                    WHERE workspace_id = ? AND modulo_key = 'registro_horario' AND COALESCE(enabled, 0) = 1
                    LIMIT 1
                    """,
                    (workspace_id,),
                ).fetchone()
                if not enabled:
                    continue
                created = run_workspace_time_missing_sweep(conn, workspace_id)
                if created:
                    notifications_total += len(created)
                    conn.commit()
            conn.close()
            with WORKSPACE_TIME_SWEEP_STATE_LOCK:
                WORKSPACE_TIME_SWEEP_STATE["last_run_at"] = datetime.now().isoformat()
                WORKSPACE_TIME_SWEEP_STATE["last_error"] = ""
                WORKSPACE_TIME_SWEEP_STATE["last_workspaces"] = workspaces_scanned
                WORKSPACE_TIME_SWEEP_STATE["last_notifications"] = notifications_total
        except Exception as exc:
            try:
                conn.close()
            except Exception:
                pass
            with WORKSPACE_TIME_SWEEP_STATE_LOCK:
                WORKSPACE_TIME_SWEEP_STATE["last_run_at"] = datetime.now().isoformat()
                WORKSPACE_TIME_SWEEP_STATE["last_error"] = str(exc)
        time.sleep(max(60, int(interval_seconds or 300)))


def legal_radar_auto_scan_loop(db_path, interval_seconds=3600):
    # No usamos sync_knowledge aquí para evitar que un proceso background reescriba JSON del repo.
    # El "reservorio" principal es la tabla legal_radar_items; el admin puede sincronizar manualmente si lo desea.
    if LEGAL_RADAR_AUTO_SCAN_ON_START:
        time.sleep(5)
    while True:
        try:
            conn = get_db(db_path)
            now_ts = datetime.now(timezone.utc).isoformat()
            created_total = 0
            updated_total = 0
            for area_key in list(LEGAL_AREA_DEFINITIONS.keys()):
                result = scan_legal_radar_sources(conn, area=area_key, now=now_ts, sync_knowledge=False)
                created_total += int(result.get("created") or 0)
                updated_total += int(result.get("updated") or 0)
            try:
                conn.commit()
            except Exception:
                pass
            try:
                conn.close()
            except Exception:
                pass
            with LEGAL_RADAR_AUTO_SCAN_LOCK:
                LEGAL_RADAR_AUTO_SCAN_STATE["last_run_at"] = now_ts
                LEGAL_RADAR_AUTO_SCAN_STATE["last_error"] = ""
                LEGAL_RADAR_AUTO_SCAN_STATE["last_created"] = created_total
                LEGAL_RADAR_AUTO_SCAN_STATE["last_updated"] = updated_total
        except Exception as exc:
            try:
                conn.close()
            except Exception:
                pass
            with LEGAL_RADAR_AUTO_SCAN_LOCK:
                LEGAL_RADAR_AUTO_SCAN_STATE["last_run_at"] = datetime.now(timezone.utc).isoformat()
                LEGAL_RADAR_AUTO_SCAN_STATE["last_error"] = str(exc)
        time.sleep(max(300, int(interval_seconds or 3600)))


def run_workspace_time_alerts(conn, workspace_id, entry, now=None):
    now_ts = now or datetime.now().isoformat()
    persona_id = entry.get("persona_id")
    persona_nombre = entry.get("persona_nombre")
    company_name = entry.get("empresa_nombre") or ""
    prefs = fetch_workspace_alert_preferences(conn, workspace_id, persona_id=persona_id)
    if not prefs:
        return []
    notifications = []
    worker_payload = {
        "persona_nombre": persona_nombre,
        "fecha": entry.get("fecha"),
        "hora_inicio": entry.get("hora_inicio") or "",
        "hora_fin": entry.get("hora_fin") or "",
        "empresa_nombre": company_name,
    }
    event = normalize_lookup_text(entry.get("event") or "")
    # Missing check-in/out alerts are computed by a periodic sweep endpoint (no background scheduler).
    if event in {"checkin", "entrada"}:
        if prefs.get("notify_admin"):
            log_workspace_notification(conn, workspace_id, persona_id, "admin_entry_log", worker_payload, now=now_ts)
            notifications.append("admin_entry_log")
        if prefs.get("notify_worker"):
            log_workspace_notification(conn, workspace_id, persona_id, "worker_entry_log", worker_payload, now=now_ts)
            notifications.append("worker_entry_log")
    if event in {"checkout", "salida", "cierre"}:
        if prefs.get("notify_admin"):
            log_workspace_notification(conn, workspace_id, persona_id, "admin_exit_log", worker_payload, now=now_ts)
            notifications.append("admin_exit_log")
        if prefs.get("notify_worker"):
            log_workspace_notification(conn, workspace_id, persona_id, "worker_exit_log", worker_payload, now=now_ts)
            notifications.append("worker_exit_log")
    return notifications


def fetch_workspace_time_sweep_status():
    with WORKSPACE_TIME_SWEEP_STATE_LOCK:
        return dict(WORKSPACE_TIME_SWEEP_STATE)


def build_workspace_time_xml(rows, persona_name="", company_name="", month=""):
    root = ET.Element("registro_horario", workspace=normalize_lookup_text(persona_name or ""), empresa=company_name or "", mes=month or "")
    for row in rows:
        entry = ET.SubElement(root, "entrada")
        ET.SubElement(entry, "fecha").text = row.get("fecha") or ""
        ET.SubElement(entry, "hora_inicio").text = row.get("hora_inicio") or ""
        ET.SubElement(entry, "hora_fin").text = row.get("hora_fin") or ""
        ET.SubElement(entry, "pausa_min").text = str(row.get("pausa_min") or 0)
        ET.SubElement(entry, "minutos_trabajados").text = str(row.get("minutos_trabajados") or 0)
        ET.SubElement(entry, "tipo_jornada").text = row.get("tipo_jornada") or ""
        ET.SubElement(entry, "estado").text = row.get("estado") or ""
        ET.SubElement(entry, "notas").text = row.get("notas") or ""
    return ET.tostring(root, encoding="utf-8", xml_declaration=True)


