    return build_branded_document_pdf(
        "HOJA DE ENCARGO DE SERVICIOS",
        f"{company.get('nombre') or workspace.get('nombre') or 'Modernia'} · {servicio}",
        sections,
        footer_lines,
        brand_logo_url=company.get("logo_url"),
    )


