                set_parts = [
                    "estado_renovacion = ?",
                    "renovacion_fecha = ?",
                    "estado_poliza = 'activa'",
                    "fecha_vencimiento = COALESCE(NULLIF(?, ''), fecha_vencimiento)",
                ]
